@Composable
fun PeopleProfileEditPhotosView(viewModel: PeopleProfileEditVM) {

    Column(
        modifier = Modifier.settingsBgModifierJs().padding(top = 16.dp, leftRight = 16.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        PeopleProfileEditPhotosGrid(viewModel, Modifier.fillMaxWidth())

        Spacer(modifier = Modifier.height(14.dp))
        ShapeButtonsWithBorderJs(
            stringResource(Res.string.people_profile_photos_manage),
            modifier = Modifier.padding(leftRight = 26.dp, topBottom = 14.dp),
            onClick = { viewModel.viewModelCallback(PeopleProfileEditEvent.ProfilePhotosScreen) }
        )
        Spacer(modifier = Modifier.height(14.dp))
    }
}

@Composable
private fun PeopleProfileEditPhotosGrid(
    viewModel: PeopleProfileEditVM,
    modifier: Modifier,
) {
    val photosSize = viewModel.photosListFlow.value.size
    val items = remember { List(3) { it } }
    var draggedIndex by remember { mutableStateOf<Int?>(null) }
    // Настройки сетки
    val columns = 3
    val rows = 1
    val horizontalSpacing = 12
    val verticalSpacing = 14


    // Контейнер-измеритель
    Box(
        modifier
            .fillMaxSize()
            .padding(leftRight = 16.dp)
            .overflow(Overflow.Hidden),

        ) {

        // --- Рендеринг Сетки ---
        // Используем key, чтобы сетка пересоздавалась при изменении размеров
        Div(
            attrs = Modifier.toAttrs{
                style {
                    display(DisplayStyle.Grid)
                    gridTemplateColumns("repeat($columns, minmax(0, 1fr))")
                    gridTemplateRows("repeat($rows, 1fr)")
                    gap(verticalSpacing.px, horizontalSpacing.px)
                    property("box-sizing", "border-box") // ВАЖНО
                    width(100.percent)
                    // Центрируем по горизонтали
                    property("margin-left", "auto")
                    property("margin-right", "auto")
                    // Прижимаем к верху
                    property("margin-top", "0px")
                }
            }
        ) {
            items.forEach { index ->
                val photoUrl =
                    if (index <= photosSize - 1) viewModel.photosListFlow.value[index] else null

                val spanX = 1
                val spanY = 1

                Div(
                    attrs = Modifier.aspectRatio(1/1.2).toAttrs{
                        style {
                            property("grid-column", "span $spanX")
                            property("grid-row", "span $spanY")
                            display(DisplayStyle.Flex)
                            justifyContent(JustifyContent.Center)
                            alignItems(AlignItems.Center)
                        }
                    }
                ) {
                    ProfileSelectPhotosItemJs(
                        index = index,
                        photoUrl = photoUrl,
                        selectedPhotoIndex = null,
                        showAddPhoto = photosSize == index,
                        uploadPhoto = ""/*viewModel.uploadPhoto.value*/,
                        showDeleteButton = false,
                        addPhotoClick = { viewModel.viewModelCallback(PeopleProfileEditEvent.ProfilePhotosScreen) },
                        longPhotoClick = { },
                        deletePhotoClick = { },
                        rollBack = { }
                    )
                }
            }
        }
    }
}