package kotpref.models.typeConverter.multi

import kotpref.models.account.enums.AccountSexPosition


/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-16.
 */
class AccountSexPositionConverter {
    companion object {
        fun positionsToItem(position: String?): AccountSexPosition {
            var item = AccountSexPosition.DO_NOT_SHOW
            enumValues<AccountSexPosition>().forEach { if (position == it.value) item = it }
            return item
        }
    }
}