@Composable
fun ProfileCameraScreenJs(
    callback: (String?) -> Unit
) {

    val videoId = "cam"
    suspend fun startCamera(videoId: String): Boolean {
        val video = document.getElementById(videoId) as? HTMLVideoElement ?: return false

        return try {
            val stream = try {
                // Phone
                window.navigator.mediaDevices
                    .getUserMedia(js("{ video: { facingMode: 'user' } }"))
                    .await()
            } catch (_: dynamic) {
                // PC
                window.navigator.mediaDevices
                    .getUserMedia(js("{ video: true }"))
                    .await()
            }

            video.srcObject = stream
            video.play()
            true
        } catch (_: dynamic) {
            callback.invoke(null)
            false
        }
    }

    fun stopCamera() {
        val video = document.getElementById(videoId) as? HTMLVideoElement ?: return
        val stream = video.srcObject as? MediaStream ?: return
        stream.getTracks().forEach { it.stop() }
        video.srcObject = null
    }

    val cameraManager = rememberCameraManager(
        onSuccess = {
            stopCamera()
            callback.invoke(it)
        },
        onError = {
            stopCamera()
            callback.invoke(null)
        }
    )

    LaunchedEffect(Unit) {
        startCamera(videoId)
    }

    PageContainer {
        JsCustomTabBar(
            onBack = { callback.invoke(null) },
            withBackground = false,
            tabBarType = TabBars.EmptyTabBar
        )
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .flexGrow(1)
                .position(Position.Relative)
                .overflow(Overflow.Hidden)
        ) {
            Div(
                Modifier.fillMaxSize().position(Position.Absolute).toAttrs()
            ) {
                Video(
                    attrs = Modifier
                        .fillMaxSize()
                        .toAttrs {
                            id("cam")
                            style {
                                property("object-fit", "cover")
                                property("transform", "scaleX(-1)")
                            }
                        },
                )
            }

            Box(
                modifier = Modifier.size(64.dp).borderRadius(50.percent)
                    .margin(bottom = 48.dp)
                    .background(JsMainTheme.colors.main_color_white_transparent_70)
                    .align(Alignment.BottomCenter)
                    .position(Position.Absolute)
                    .onClick {
                        cameraManager.launch()
                    },
                contentAlignment = Alignment.Center
            ) {
                Box(
                    modifier = Modifier.size(48.dp).borderRadius(50.percent)
                        .background(JsMainTheme.colors.text_color_gray)
                )
            }
        }
    }
}