package ui.screens.settings.settingsInfo

import androidx.annotation.UiThread
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.nav_settings_privacy_title
import fiori.sharedmodule.generated.resources.nav_settings_terms_title
import dependencies.di
import dependencies.AccountRepository
import managers.analytics.AnalyticsManager
import managers.analytics.AnalyticsSettingsEvents
import kotlinx.coroutines.launch
import network.restApi.Endpoint
import org.kodein.di.instance
import ui.resources.ResManager

sealed class SettingsInfoEvent {
    data class SettingsWebPage(val endpoint: String, val title: String) : SettingsInfoEvent()
    data object Back : SettingsInfoEvent()
}

class SettingsInfoVM(
    val viewModelCallback: (SettingsInfoEvent) -> Unit
) : ViewModel() {

    val accountRepository by di.instance<AccountRepository>()

    fun showPrivacyPage() {
        viewModelScope.launch {
            val title: String = ResManager.getString(Res.string.nav_settings_privacy_title)
            AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.informationPrivacyPolicyOpen.name)
            viewModelCallback.invoke(SettingsInfoEvent.SettingsWebPage(Endpoint.getPrivacyPolicyUrl(), title))
        }
    }

    fun showTermsPage() {
        viewModelScope.launch {
            val title: String = ResManager.getString(Res.string.nav_settings_terms_title)
            AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.informationTermsConditionsOpen.name)
            viewModelCallback.invoke(SettingsInfoEvent.SettingsWebPage(Endpoint.getTermsUrl(), title))
        }
    }

    @UiThread
    fun back() {
        viewModelCallback.invoke(SettingsInfoEvent.Back)
    }

}