package kotpref.models.account

import kotlinx.serialization.SerialName
import kotpref.models.WithId
import kotpref.models.account.enums.AccountVerificationStatus
import kotpref.models.getDefaultId

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-11.
 */
/*@Entity(
    tableName = "account", primaryKeys = ["id"]
)*/
@kotlinx.serialization.Serializable
data class Account(
    @SerialName("account_id") override var id: String = "",
    @SerialName("uri") var profileId: String = "",
    @SerialName("uuid") var uuid: String? = null,

    @SerialName("auth_provider_id") var login: String? = null,
    @SerialName("email") var email: String? = null,
    @SerialName("avatar") var avatar: String? = null,
    @SerialName("nickname") var nickname: String? = null,
    @SerialName("language") var language: String? = null,

    @SerialName("photo_verification_status") var photoVerificationStatus: String? = null,
    @SerialName("verification_attempts") var photoVerificationAttempts: Int? = null,

//    //@ColumnInfo(name = "distance_from_point")
    @SerialName("distance") var distance: Double? = null,
    @SerialName("auth_provider") var authProvider: Int? = null,

    @SerialName("email_verified") var emailVerified: Boolean? = null,
    @SerialName("is_online") var isOnline: Boolean? = null,
    @SerialName("is_invisible") var isInvisible: Boolean? = null,
    @SerialName("birthday_is_edited") var birthdayIsEdited: Boolean? = null,
    @SerialName("gender_is_edited") var genderIsEdited: Boolean? = null,

    @SerialName("show_my_age") var showMyAge: Int? = null,
    @SerialName("show_my_location") var showMyLocation: Int? = null,
    @SerialName("show_for_min_age") var showMinAge: Int? = null,
    @SerialName("show_for_max_age") var showMaxAge: Int? = null,
    @SerialName("search_rate") var searchRate: Int? = null,

    @SerialName("not_visible_for_genders")
//    @TypeConverters(ListIntConverter::class)
    var notVisibleForGenders: MutableList<Int>? = null,

    @SerialName("status") var status: Int? = null,
    @SerialName("ban_status") var banStatus: Int? = null,
    @SerialName("ban_status_changed_at") var banStatusChangedAt: String? = null,

    @SerialName("measurement_units")
    /** Metric = 1; Imperial = 2 **/
    var measurementUnits: Int? = null,

    @SerialName("last_active_at") var lastActive: String? = null,

    //@ColumnInfo(name = "account_created_at")
    @SerialName("created_at") var createdAt: String? = null,

    //@Embedded
    @SerialName("info") var info: AccountInfo = AccountInfo(),
    //@Embedded
    @SerialName("compatibilities") var compatibilities: AccountCompatibilities? = null,


    @SerialName("compatibilities_updated_at") var compatibilitiesUpdatedAt: String? = null,


    //@Embedded
    @SerialName("location") var location: AccountLocation? = null,

    //@Embedded
    @SerialName("subscription") var subscriptionStatus: AccountSubscriptionStatus? = null,

    //@Embedded
    @SerialName("filters") var filters: AccountFilters? = null,

    //@Embedded
    @SerialName("limits") var limits: AccountLimits? = null,

//    @TypeConverters(AccountPhotoConverter::class)
    //@ColumnInfo(name = "account_public_photos")
    @SerialName("photos") var photos: MutableList<AccountPhoto>? = null,

//    @TypeConverters(ListStringConverter::class)
    //@ColumnInfo(name = "account_instagram_photos")
    @SerialName("instagramPhotos") var instagramPhotos: MutableList<String>? = null,

    @SerialName("id") var accountId: Int = 0,

    var update: Boolean = false
): WithId /*: Serializable*/ {
    constructor() : this(getDefaultId())

    init {
        if (accountId != 0) id = accountId.toString()
        if (id.isNotEmpty()) accountId = id.toInt()
    }

    fun getVerificationStatus(): AccountVerificationStatus {
        return when (photoVerificationStatus) {
            "in-progress", "need_verify_started" -> AccountVerificationStatus.IN_PROGRESS
            "started" -> AccountVerificationStatus.STARTED
            "verified", "approved" -> AccountVerificationStatus.VERIFIED
            "failed" -> AccountVerificationStatus.FAILED
            else -> AccountVerificationStatus.NOT_VERIFIED
        }
    }

    fun isBlockForVerification(): Boolean {
        //if (AppVariant.isTestBuild()) return true
        return photoVerificationStatus == "need_verify" || photoVerificationStatus == "need_verify_started" || photoVerificationStatus == "in-progress"
    }
}