@Composable
fun PeopleProfileEditAboutMeView(
    viewModel: PeopleProfileEditVM
) {

    Box(modifier = Modifier.settingsBgModifierJs()) {
        val maxLength = 500
        val textareaRef = remember { mutableStateOf<HTMLElement?>(null) }
        val hint = stringResource(Res.string.onboarding_about_text_hint)
        val counter = maxLength - viewModel.aboutMe.value.length

        Row(
            modifier = Modifier.fillMaxWidth()
        ) {
            TextArea(
                value = viewModel.aboutMe.value,
                attrs = Modifier
                    .fillMaxWidth()
                    .fontSize(getMaxMinSize(16).max.cssRem)
                    .padding(topBottom = 12.dp, leftRight = 16.dp)
                    .backgroundColor(JsMainTheme.colors.main_color_bg_1)
                    .styleModifier {
                        property("border", "none")
                        outline("none")
                        property("resize", "none")
                        overflow("hidden")
                        property("line-height", "1.4")
//                        property("white-space", "pre-wrap")
//                        property("word-break", "normal")
//                        property("overflow-wrap", "break-word")
                    }
                    .onKeyDown { e ->
                        if (e.key == "Enter") {
                            e.preventDefault()

                            if (viewModel.aboutMe.value.isNotBlank()) {

                                //Перенести во VM при сохранении аккаунта
                                val singleLine = viewModel.aboutMe.value
                                    .replace("\n", " ")
                                    .replace(Regex("\\s+"), " ")
                                viewModel.aboutMeSingleLine = singleLine

                                textareaRef.value?.style?.height = "auto"
                            }
                        }
                    }
                    .toAttrs {
                        attr("rows", "1")
                        onInput { event ->
                            val target = event.target
                            viewModel.aboutMe.value = target.value.take(maxLength)
                            // авто-рост
                            target.style.height = "auto"
                            target.style.height = "${target.scrollHeight}px"
                        }

                        placeholder(hint)
                    }
            )

            JsTextView(
                text = counter.toString(),
                modifier = Modifier.margin(right = 16.dp).padding(topBottom = 12.dp),
                textSize = 16,
                fontWeight = FontWeight.Medium,
                textColor = JsMainTheme.colors.text_color_hint
            )
        }
    }
}