package web.helpers

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.ui.graphics.Color
import kotpref.models.account.enums.AccountVerificationStatus
import web.theme.JsMainTheme

class AccountVerificationStatusManagerJs {

    @Composable
    fun getVerificationStatusColor(status: AccountVerificationStatus?, container: Boolean): Color {
        return when (status) {
            AccountVerificationStatus.NOT_VERIFIED,
            AccountVerificationStatus.STARTED,
            AccountVerificationStatus.FAILED -> {
                if (container) JsMainTheme.colors.main_color_verification_in_failed_alpha
                else JsMainTheme.colors.main_color_verification_in_failed
            }

            AccountVerificationStatus.IN_PROGRESS -> {
                if (container) JsMainTheme.colors.main_color_verification_in_progress_alpha
                else JsMainTheme.colors.main_color_verification_in_progress
            }

            else -> JsMainTheme.colors.main_color_bg_1
        }
    }
}