@Composable
fun RatingDialog(
    callback: (String) -> Unit,
    onDismiss: () -> Unit,
) {
    val rating = remember { mutableIntStateOf(-1) }

    fun onDialogOk() {
        val appKeys by di.instance<IAppKeysStorage>()
        if (rating.value < 4) {
            appKeys.feedbackShowResult = true
            AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.ratingWindowLow.name)
            val url = when {
                AppVariant.isElizium() -> "https://docs.google.com/forms/d/e/1FAIpQLSc8bdkJWLdw7VPZsNNaY21bYOSljqVwVidI70w5tRuoDM0ZRw/viewform"
                AppVariant.isHeaven() -> "https://docs.google.com/forms/d/e/1FAIpQLSc5WDq-OuipiiRVsVNUYkydT1nwzyKOHHN2Ka6jsAXn3Rm8ng/viewform"
                AppVariant.isParadiz() -> "https://docs.google.com/forms/d/e/1FAIpQLSdIK7wcys_rJwvxVIQPKt_0r_FwCSlmNUP0o4msID5uKzzPMw/viewform"
                else -> "https://docs.google.com/forms/d/e/1FAIpQLSdSQ6yFLpjxunGZIdFyZCjsDHi3kF5xAysBD8y7O_7VTYsHpw/viewform"
            }
            callback(url)
            onDismiss()
        } else {
            appKeys.feedbackShowResult = true
            AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.ratingWindowHigh.name)
//            goToPlayMarket(context)
            onDismiss()
        }
    }

    Box(
        modifier = Modifier.fillMaxSize().zIndex(9000)
            .background(JsMainTheme.colors.main_color_black_transparent_70)
            .clickable { onDismiss() }
            .padding(horizontal = 32.dp),
        contentAlignment = Alignment.Center
    ) {
        Box(
            modifier = Modifier
                .minWidth(250.dp)
                .background(JsMainTheme.colors.main_color_bg_1)
//                .borderRadius(16.dp)
                .border(width = 2.dp, color = JsMainTheme.colors.color_dialog_stroke)
                .boxShadow(
                    blurRadius = 4.dp,
                    spreadRadius = 0.dp,
                    offsetX = 0.dp,
                    offsetY = 2.dp
                )
                .styleModifier {
                    property("position", "relative")
                    property("overflow", "hidden")
                }
                .onClick { event -> event.stopPropagation() },
        ) {
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                JsTextView(
                    text = stringResource(Res.string.dialog_rating_feedback_title),
                    modifier = Modifier.width(60.percent).padding(top = 24.dp),
                    textSize = 24,
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center,
                )

                JsTextView(
                    text = stringResource(Res.string.dialog_rating_feedback_text),
                    modifier = Modifier.margin(top = 10.dp, leftRight = 20.dp),
                    textSize = 14,
                    fontWeight = FontWeight.Normal,
                    textColor = JsMainTheme.colors.text_color_gray,
                    textAlign = TextAlign.Center,
                )

                Row(
                    modifier = Modifier.fillMaxWidth().margin(top = 16.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.Center
                ) {
                    repeat(5) {
                        val imageId = if (it < rating.value) "ratingStarFilled" else "ratingStarOutline"
                        JsImageView(
                            imageId,
                            modifier = Modifier.size(32.dp).margin(leftRight = 4.dp)
                                .clickable {
                                    rating.value =  if (rating.value == 1 && it == 0) 0 else it + 1
                                },
                        )
                    }
                }

                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 24.dp, left = 16.dp, right = 16.dp, bottom = 16.dp)
                ){
                    Box(
                        modifier = Modifier.fillMaxWidth()
                            .height(50.dp)
                            .borderRadius(4.dp)
                            .background(JsMainTheme.colors.app_main_color)
                            .clickable {
                                onDialogOk()
                            },
                        contentAlignment = Alignment.Center
                    ) {
                        JsTextView(
                            text = stringResource(Res.string.dialog_rating_feedback_btn),
                            modifier = Modifier,
                            textSize = 16,
                            fontWeight = FontWeight.Medium
                        )
                    }
                }
            }

            Box(modifier = Modifier.align(Alignment.TopEnd).padding(12.dp).clickable {
                onDismiss()
            }) {
                JsImageView(
                    "ic_close_attach",
                    modifier = Modifier.size(32.dp),
                    tintColor = JsMainTheme.colors.app_main_color
                )
            }
        }
    }
}