package web.views

import androidx.compose.runtime.Composable
import androidx.compose.ui.layout.ContentScale
import com.varabyte.kobweb.compose.css.FontWeight
import com.varabyte.kobweb.compose.css.TextAlign
import com.varabyte.kobweb.compose.css.TextDecorationLine
import com.varabyte.kobweb.compose.css.TextOverflow
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.foundation.layout.Column
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.graphics.Color
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxHeight
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxSize
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxWidth
import com.varabyte.kobweb.compose.ui.modifiers.height
import com.varabyte.kobweb.compose.ui.modifiers.padding
import org.jetbrains.compose.resources.DrawableResource
import org.jetbrains.compose.web.css.px
import web.helpers.clickable
import web.helpers.copy
import web.helpers.dp
import web.helpers.padding
import web.helpers.resultHeight
import web.helpers.toPercent
import web.screens.splash.SplashFiorryButton
import web.theme.JsMainTheme


@Composable
fun OnBoardingDefaultBox(
    image: DrawableResource,
    imageFormat: String = "png",
    backButtonVisibility: Boolean = false,
    title: String,
    text: String,
    textColor: Color = JsMainTheme.colors.text_color_default,
    buttonText: String,
    compatibilityText: String = "",
    skipText: String = "",
    boxHeight: Float = 0.725f,
    mainButtonClick: () -> Unit,
    backButtonClick: () -> Unit = {},
    skipButtonClick: () -> Unit = {}
) {
    Box(modifier = Modifier.fillMaxSize()) {
        JsImageView(
            image,
            format = imageFormat,
            modifier = Modifier.fillMaxWidth().height(resultHeight.value.px),
            contentScale = ContentScale.FillWidth,
            align = Alignment.TopCenter
        )
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .fillMaxHeight(0.835f.toPercent()),
            contentAlignment = Alignment.TopCenter
        ) {
            Column(
                Modifier
                    .fillMaxWidth(0.85f.toPercent())
                    .fillMaxHeight()
                    .padding(bottom = 16.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Box(modifier = Modifier.weight(1f))
                JsTextView(
                    text = title,
                    modifier = Modifier.padding(bottom = 12.dp),
                    textColor = JsMainTheme.colors.text_color_default,
                    textSize = 24,
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center
                )
                JsAutoResizeText(
                    text = text,
                    color = JsMainTheme.colors.text_color_default.copy(0.8f),
                    fontWeight = FontWeight.Normal,
                    maxTextSize = 15,
                    minTextSize = 10,
                    textAlign = TextAlign.Center,
                    maxLines = 6
                )
                JsAutoResizeText(
                    text = compatibilityText,
                    modifier = Modifier.padding(
                        top = 16.dp, start = 24.dp, end = 24.dp, bottom = 2.dp
                    ),
                    color = Color.rgb(0XB46BEE).copy(alpha = 0.5f),
                    fontWeight = FontWeight.Normal,
                    maxTextSize = 15,
                    textAlign = TextAlign.Center,
                    overflow = TextOverflow.Ellipsis,
                    maxLines = 2
                )
            }

            if (backButtonVisibility) {
                JsCustomTabBar(
                    onBack = { backButtonClick.invoke() },
                    withBackground = false
                )
            }

        }

        Column(
            Modifier.fillMaxWidth().align(Alignment.BottomCenter),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            SplashFiorryButton(title = buttonText) { mainButtonClick.invoke() }

            if (!backButtonVisibility && skipText.isNotEmpty()) {
                JsTextView(
                    text = skipText,
                    modifier = Modifier.padding(
                        top = 20.dp, bottom = 16.dp, start = 16.dp, end = 16.dp
                    ).clickable { skipButtonClick.invoke() },
                    textSize = 15,
                    textColor = Color.rgb(0X8F97AC),
                    textDecoration = TextDecorationLine.Underline,
                    fontWeight = FontWeight.Normal,
                    textAlign = TextAlign.Center,
                )
            } else Box(Modifier.height(26.dp))
        }
    }
}
