@Composable
fun JsOnBoardingStartScreen(
    startPage: Boolean,
    viewModelCallback: (OnBoardingStartEvent) -> Unit,
    viewModel: OnBoardingStartVM = rememberJsViewModel {
        OnBoardingStartVM(startPage, viewModelCallback)
    }
) {
    JsImagePreloaderQueue.addToQueue(
        listOf(
            "${Res.drawable.bg_onboarding_compatibility.getDrawableIdName()}.webp",
            "ic_onboarding_age_web.webp",
        )
    )

    val screenSize = getJsScreenSizeInfo()
    val height = screenSize.heightPx
    val fullScreenScroll = resultHeight.value > height

    if (fullScreenScroll) {
        PageContainer { OnboardingStartScreenContent(viewModel, startPage, this) }
    } else {
        Box(Modifier.fillMaxSize()) { OnboardingStartScreenContent(viewModel, startPage, this) }
    }
}

@Composable
private fun OnboardingStartScreenContent(
    viewModel: OnBoardingStartVM,
    startPage: Boolean,
    scope: BoxScope
) {
    val title =
        if (startPage) stringResource(resource = Res.string.onboarding_start_title)
        else stringResource(resource = Res.string.onboarding_start_interest_title)

    Column(Modifier.fillMaxSize(), horizontalAlignment = Alignment.CenterHorizontally) {
        if (startPage) {
            JsCustomTabBar(
                onBack = { viewModel.back() },
                withBackground = false,
            )
            /*Box(
                contentAlignment = Alignment.CenterStart,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(56.dp)
                    .clickable { viewModel.back() }
            ) {
                JsTextView(
                    stringResource(resource = Res.string.btn_cancel), textSize = 15,
                    textColor = JsMainTheme.colors.app_main_color,
                    fontWeight = FontWeight.Normal,
                    modifier = Modifier.padding(all = 16.dp).fillMaxHeight()
                )
            }*/
        } else {
            JsCustomTabBar(
                onBack = { viewModel.back() },
                withBackground = false,
            )
        }

        Spacer(modifier = Modifier.height(30.dp))
        JsTextView(
            text = title, textSize = 24,
            modifier = Modifier.fillMaxWidth(0.8f.toPercent()).minHeight(30.dp),
            textColor = JsMainTheme.colors.text_color_default,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )
        if (AppVariant.isFiorryOrHeaven()) Spacer(modifier = Modifier.height(8.dp))

        Spacer(Modifier.size(24.dp))
        Box(modifier = Modifier.weight(1f).fillMaxWidth().overflow(Overflow.Auto)) {
            JsButtonsMultiSelect(
                viewModel.multiSelectListFlow, Modifier.fillMaxWidth()
            ) { viewModel.setSelectItem(it) }
        }
        Spacer(Modifier.size(24.dp))

        Box(
            modifier = Modifier.height(50.dp).fillMaxWidth(), contentAlignment = Alignment.Center
        ) {
            SplashFiorryButton(
                title = stringResource(resource = Res.string.onboarding_start_btn_text_next)
            ) { viewModel.clickedBtn(false) }
        }
        Spacer(modifier = Modifier.height(26.dp))
    }

    if (viewModel.multiSelectListFlow.value.size > 2) {
        scope.run {
            Box(
                modifier = Modifier
                    .padding(start = 16.dp, end = 16.dp, top = 10.dp, bottom = 10.dp)
                    .align(Alignment.TopEnd)
                    .clickable { viewModel.infoBtnClick() },
                contentAlignment = Alignment.Center
            ) {
                JsImageView(
                    drawableRes = Res.drawable.ic_genders_info,
                    modifier = Modifier.size(38.dp)
                )
            }
        }
    }

    if (viewModel.showGenderInfoDialog.value) JsDialogInfoGender(false) {
        viewModel.showGenderInfoDialog.value = false
    }

    if (viewModel.loading.value) LoadingBlockState()
}

