class AccountEducationConverter {
    companion object {
        fun positionsToItem(position: Int?): AccountEducation {
            var item = AccountEducation.DO_NOT_SHOW
            enumValues<AccountEducation>().forEach { if (position == it.position) item = it }
            return item
        }
    }
}