package ui.screens.settings.settingsNotifications

import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dependencies.AccountRepository
import dependencies.di
import kotlinx.coroutines.launch
import kotpref.models.account.AccountNotifications
import kotpref.models.typeConverter.DateTimeConverter
import kotpref.utils.INotificationManager
import managers.AmplitudeEvent
import managers.AmplitudeManager
import managers.analytics.AnalyticsManager
import managers.analytics.AnalyticsSettingsEvents
import org.kodein.di.instance
import ui.components.BaseEventVM
import ui.components.EventVM

sealed class SettingsNotificationsEvent{
    data object Back: SettingsNotificationsEvent()
}

class SettingsNotificationsVM(
    val viewModelCallback: (SettingsNotificationsEvent) -> Unit,
    private val viewModelEvent: ((EventVM) -> Unit) -> Unit
): ViewModel() {
    val accountRepository by di.instance<AccountRepository>()
    val notificationsUtils by di.instance<INotificationManager>()
    val amplitudeManager by di.instance<AmplitudeManager>()


    private var saveData = false
    private lateinit var notifications: AccountNotifications

    val messageSwitch = mutableStateOf(false)
    val wowSwitch = mutableStateOf(false)
    val emailSwitch = mutableStateOf(false)


    fun obtainEvent(event: EventVM){
        when (event){
            is BaseEventVM.ClickSystemBack -> event.systemBack.invoke(back())
            SettingsNotificationsEventVM.SaveData -> saveData()
        }
    }
    init {
        viewModelEvent.invoke(::obtainEvent)
        viewModelScope.launch {/* runBlocking */
            notifications = accountRepository.getMyNotifications() ?: AccountNotifications()
            messageSwitch.value = notifications.messages
            wowSwitch.value = notifications.wows
            //binding.settingsNotificationsPreviewSwitch.isChecked = notifications.previews
            emailSwitch.value = notifications.email
        }
    }

    private fun saveData() {
        saveData = true
        val notifications = AccountNotifications()
        notifications.messages = messageSwitch.value
        notifications.wows = wowSwitch.value
        //notifications.previews = binding.settingsNotificationsPreviewSwitch.isChecked
        notifications.email = emailSwitch.value
        sendEvents(notifications)
        viewModelCallback.invoke(SettingsNotificationsEvent.Back)
        accountRepository.changeAccountNotification(notifications, onSuccess = {
            checkBlockNotifications(notifications)
            viewModelScope.launch { notificationsUtils.init() }
        })
    }

    private fun sendEvents(newNotifications: AccountNotifications) {
        if (notifications.messages != newNotifications.messages) {
            if (newNotifications.messages) {
                amplitudeManager.sendIdentify(AmplitudeEvent.NotificationsAboutMessages, "yes")
                AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.notificationsMessageOn.name)
            }
            else {
                amplitudeManager.sendIdentify(AmplitudeEvent.NotificationsAboutMessages, "no")
                AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.notificationsMessageOff.name)
            }
        }
        if (notifications.wows != newNotifications.wows) {
            if (newNotifications.wows) {
                amplitudeManager.sendIdentify(AmplitudeEvent.NotificationsAboutWows, "yes")
                AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.notificationsWowOn.name)
            }
            else {
                amplitudeManager.sendIdentify(AmplitudeEvent.NotificationsAboutWows, "no")
                AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.notificationsWowOff.name)
            }
        }
        if (notifications.email != newNotifications.email) {
            if (newNotifications.email){
                amplitudeManager.sendIdentify(AmplitudeEvent.NotificationsByEmail, "yes")
                AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.notificationsEmailOn.name)
            }
            else {
                amplitudeManager.sendIdentify(AmplitudeEvent.NotificationsByEmail, "no")
                AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.notificationsEmailOff.name)
            }
        }
    }

    private fun checkBlockNotifications(notifications: AccountNotifications) {
        val appKeys = accountRepository.getAppKeys()
        val blockNotifications = appKeys.userBlockNotifications
        if (notifications.messages && notifications.wows) appKeys.userBlockNotifications = ""
        else if (blockNotifications.isEmpty()) appKeys.userBlockNotifications =
            DateTimeConverter.dateToString()
    }

    private fun back(): Boolean {
        return if (saveData) false
        else {
            saveData()
            true
        }
    }
}

sealed class SettingsNotificationsEventVM : EventVM {
    data object SaveData : SettingsNotificationsEventVM()
}