@Composable
fun JsSubscribeButtonsBoxStyle(
    productDetails: List<ProductDetails>,
    selectedProduct: String,
    selectedProductID: MutableState<String>,
    discountOnlyForPopularProduct: Boolean,
    startPrice: Double,
    isWeekFormat: Boolean,
    annual12MonthsText: Boolean,
    btnProgress: MutableState<Boolean>,
    isReview: Boolean,
    showCancelAnytime: Boolean = false,
    isPlus: Boolean = false,
    isBottomDrawerFragment: Boolean = false,
    callback: (Int) -> Unit = {},
    buySubscription: (Billings, Boolean, Boolean) -> Unit,
) {
    val boxHeight = (((resultWidth.value - 12 - 32) / 3) * 1.4).px
    val maxHeight = remember { mutableStateOf(boxHeight.value) }

    val textPeriodSize = remember { mutableStateOf(if (isReview) 12 else 10) }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = 12.px)
            .heightIn(min = maxHeight.value.px)
            .onSizeChanged { _, _ -> callback.invoke(productDetails.size) }
    ) {
        productDetails.forEach {
            JsSubscribeBoxButton(
                modifier = Modifier
                    .heightIn(min = maxHeight.value.px)
                    .onSizeChanged { width, height ->
                        if (maxHeight.value < height) {
                            maxHeight.value = height.toFloat()
                        }
                    },
                productDetails = it.productDetails,
                discountDetails = it.discountDetails,
                selectedProductID = selectedProductID,
                discountOnlyForPopularProduct = discountOnlyForPopularProduct,
                isPopular = selectedProduct == it.productDetails.productId,
                startPrice = startPrice,
                isWeekFormat = isWeekFormat,
                annual12MonthsText = annual12MonthsText,
                isPlus = isPlus,
                isBottomDrawerFragment = isBottomDrawerFragment,
                btnProgress = btnProgress,
                isReview = isReview,
                textPeriodSize = textPeriodSize,
            ) {
                val productId = it.productDetails.productId
                if (selectedProductID.value == productId) {
                    btnProgress.value = true
                    val buyProductId = it.discountDetails?.productId ?: productId
                    Billings.getBillingByProductId(buyProductId)
                        ?.let { billing ->
                            buySubscription.invoke(billing, true, isBottomDrawerFragment)
                        }
                } else {
                    selectedProductID.value = productId
                    /*val buyProductId = it.discountDetails?.productId ?: productId
                    Billings.getBillingByProductId(buyProductId)?.let { billing ->
                        buySubscription.invoke(billing, false, isBottomDrawerFragment)
                    }*/
                }
            }
        }
    }

    if (showCancelAnytime) {
        Spacer(modifier = Modifier.size(32.dp))
        JsCancelAnytimeContent()
    }
}