package ui.resources

import org.jetbrains.compose.resources.DrawableResource
import org.jetbrains.compose.resources.StringResource
import org.jetbrains.compose.resources.getDrawableResourceBytes
import org.jetbrains.compose.resources.getSystemResourceEnvironment

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 30.01.2023.
 */

object ResManager {

    val drawable = AppVariantImageManager
    /*if (AppVariant.isHeaven()) HeavenImageManager
    else if (AppVariant.isElizium()) EliziumImageManager
    else if (AppVariant.isParadiz()) ParadizImageManager
    else FiorryImageManager*/

    val appStrings = AppVariantStringsManager
    var stringManager: IResStringManager? = null

    suspend fun getString(resId: StringResource): String =
        stringManager?.getPlatformString(resId) ?: org.jetbrains.compose.resources.getString(resId)

    suspend fun getString(resId: StringResource, formatArg: String): String {
        return stringManager?.getPlatformString(resId, formatArgs = arrayOf(formatArg))
            ?: org.jetbrains.compose.resources.getString(resId, formatArgs = arrayOf(formatArg))
    }

    suspend fun getString(resId: StringResource, formatArgs: Array<String>): String {
        return stringManager?.getPlatformString(resId, formatArgs = formatArgs)
            ?: org.jetbrains.compose.resources.getString(resId, formatArgs = formatArgs)
    }

    suspend fun getDrawable(resId: DrawableResource): ByteArray {
        val environment = getSystemResourceEnvironment()
        val drawable = getDrawableResourceBytes(environment, resId)
        return drawable
    }
}

interface IResStringManager {
    fun getPlatformString(resId: StringResource): String
    fun getPlatformString(resId: StringResource, formatArgs: Array<String>): String
}