package network

import io.ktor.client.request.HttpRequestBuilder
import io.ktor.client.request.delete
import io.ktor.client.request.forms.submitFormWithBinaryData
import io.ktor.client.request.get
import io.ktor.client.request.header
import io.ktor.client.request.headers
import io.ktor.client.request.patch
import io.ktor.client.request.post
import io.ktor.client.request.put
import io.ktor.client.request.setBody
import io.ktor.client.statement.HttpResponse
import io.ktor.client.statement.bodyAsText
import io.ktor.http.HttpHeaders
import io.ktor.http.HttpMethod
import io.ktor.http.content.PartData
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.logging.CommonLogger
import kotpref.logging.LogLvl
import kotpref.models.ResponseError
import kotpref.models.ServerError
import kotpref.models.typeConverter.JsonObjectConverter
import network.restApi.requests.ResponseCallback

class KtorClient(
    private val userAgent: String,
    private val language: () -> String,
    val os: Int
) {

    companion object {
        val queue = mutableListOf<RequestItem>()
        val spans = setOf<String>()

        fun resumeQueue() {
            if (queue.size <= 0) return
            val currentQueue = mutableListOf<RequestItem>()
            currentQueue.addAll(queue)
            queue.clear()
            currentQueue.forEach { item ->
                try {
                    item.callback?.invoke()
                } catch (t: Throwable) {
                    CommonLogger().log(LogLvl.ERROR,"KtorClient", "callback failed", t)
                }
            }
        }

        var refreshedToken = ""
    }

    val client = HttpClient().buildOkHttpClient(userAgent, language)
    val logger = CommonLogger()


    ///region Queue Requests
    inline fun <reified R : Any> getOrDeleteInfo(
        url: String,
        token: String = "",
        requestType: RequestType = RequestType.GET,
        responseCallback: ResponseCallback<R?>
    ) {
        try {
            queueRequest(requestType, url, Unit, token, responseCallback)
        } catch (ex: Exception) {
            logger.log(LogLvl.ERROR, requestType.name, url)
            responseCallback.onFailure(url, ex, null)
        }
    }

    inline fun <reified B : Any, reified R : Any> postData(
        url: String,
        body: B,
        token: String = "",
        requestType: RequestType = RequestType.POST,
        responseCallback: ResponseCallback<R?>
    ) {
        try {
            queueRequest(requestType, url, body, token, responseCallback)
        } catch (ex: Exception) {
            logger.log(LogLvl.ERROR, requestType.name, url)
            responseCallback.onFailure(url, ex, null)
        }
    }

    suspend inline fun <reified B : Any, reified R : Any> postDataWithResult(
        url: String,
        body: B,
        token: String = "",
        requestType: RequestType = RequestType.POST
    ): R? {
        return try {
            clientRequest(requestType, url, body, null, token)
        } catch (ex: Exception) {
            logger.log(LogLvl.ERROR, requestType.name, url)
            null
        }
    }

    inline fun <reified R : Any> multipart(
        url: String,
        formData: List<PartData>,
        token: String = "",
        requestType: RequestType = RequestType.POST,
        responseCallback: ResponseCallback<R?>
    ) {
        CoroutineScope(Dispatchers.Default).launch {
            try {
                val response: HttpResponse = client.submitFormWithBinaryData(
                    url = url,
                    formData = formData
                ) {
                    method = if (requestType == RequestType.PUT) HttpMethod.Put else HttpMethod.Post
                    if (token.isNotEmpty()) header(HttpHeaders.Authorization, token)
                }
                parseResponse<R>(url, response, responseCallback)
            } catch (ex: Exception) {
                logger.log(LogLvl.ERROR, requestType.name, url)
                responseCallback.onFailure(url, ex, null)
            }
        }
    }


    suspend inline fun <reified R : Any> multipartWithResult(
        url: String,
        formData: List<PartData>,
        token: String = "",
        requestType: RequestType = RequestType.POST
    ): R? {
        return try {
            val response: HttpResponse = client.submitFormWithBinaryData(
                url = url,
                formData = formData
            ) {
                method = if (requestType == RequestType.PUT) HttpMethod.Put else HttpMethod.Post
                if (token.isNotEmpty()) header(HttpHeaders.Authorization, token)
            }
            parseResponse<R>(url, response, null)
        } catch (ex: Exception) {
            logger.log(LogLvl.ERROR, requestType.name, url)
            null
        }
    }


    inline fun <reified B : Any, reified R : Any> queueRequest(
        type: RequestType, url: String, body: B, token: String = "",
        responseCallback: ResponseCallback<R?>
    ) {
        spans.plus(url)

        val request: suspend () -> Unit = {
            try {
                var currentToken = token
                if (refreshedToken.isNotEmpty() && token.isNotEmpty()) currentToken =
                    "Bearer $refreshedToken"
                clientRequest(type, url, body, responseCallback, currentToken)
            } catch (ex: Exception) {
                logger.log(LogLvl.ERROR, type.name, url)
                responseCallback.onFailure(url, ex, null)
            }
        }

        responseCallback.errorRetryCallback = {
            queue.add(RequestItem {
                CoroutineScope(Dispatchers.Default).launch { request() }
            })
        }
        responseCallback.errorCallback = { spanFinish(url) }
        responseCallback.successCallback = { spanFinish(url) }
        CoroutineScope(Dispatchers.Default).launch { request() }
    }

    fun spanFinish(url: String) {
        spans.minus(url)
    }
    ///endregion


    ///region Ktor Requests
    suspend inline fun <reified B : Any, reified R : Any> clientRequest(
        type: RequestType,
        url: String,
        body: B,
        callback: ResponseCallback<R?>?,
        token: String = ""
    ): R? {
        val initRequestBuilder: HttpRequestBuilder.() -> Unit = {
            if (body !is Unit) setBody(body)
            if (token.isNotEmpty()) headers {
                append(HttpHeaders.Authorization, token)
            }
        }

        val response = when (type) {
            RequestType.GET -> client.get(url, initRequestBuilder)
            RequestType.POST -> client.post(url, initRequestBuilder)
            RequestType.PUT -> client.put(url, initRequestBuilder)
            RequestType.DELETE -> client.delete(url, initRequestBuilder)
            RequestType.PATCH -> client.patch(url, initRequestBuilder)
        }
        return parseResponse<R>(url, response, callback)
    }
    ///endregion


    suspend inline fun <reified R : Any> parseResponse(
        url: String,
        response: HttpResponse,
        callback: ResponseCallback<R?>?
    ): R? {
        val stringBody: String = response.bodyAsText()
        try {
            when (val responseStatus = response.status.value) {
                200 -> {
                    logger.logResponse(response, stringBody, LogLvl.INFO)
                    val result = JsonObjectConverter.stringToObject<R>(stringBody)
                    if (callback != null) CoroutineScope(Dispatchers.Main).launch {
                        callback.onResponse(result)
                    } else return result
                }

                in 200..299 -> {
                    logger.logResponse(response, stringBody, LogLvl.INFO)
                    CoroutineScope(Dispatchers.Main).launch {
                        callback?.onResponse(null)
                    }
                }

                else -> {
                    logger.logResponse(response, stringBody, LogLvl.ERROR)
                    try {
                        val error = JsonObjectConverter.stringToObject<ResponseError>(stringBody)
                        error?.serverErrors?.forEach { it.baseCode = responseStatus }
                        CoroutineScope(Dispatchers.Main).launch { callback?.onError(url, error) }
                    } catch (ex: Exception) {
                        val error = ServerError(
                            code = responseStatus,
                            description = "",
                            baseCode = responseStatus
                        )
                        val responseError =
                            ResponseError(responseStatus, serverErrors = mutableListOf(error))
                        CoroutineScope(Dispatchers.Main).launch {
                            callback?.onError(
                                url,
                                responseError
                            )
                        }
                    }
                }
            }
        } catch (ex: Exception) {
            logger.logResponse(response, stringBody, LogLvl.ERROR)
            CoroutineScope(Dispatchers.Main).launch {
                callback?.onFailure(url, ex, response)
            }
        }
        return null
    }

    data class RequestItem(var callback: (() -> Unit)?)

}

enum class RequestType { GET, POST, PUT, DELETE, PATCH }