@Composable
fun SettingsInfoScreenJs(
    viewModelCallback: (SettingsInfoEvent) -> Unit,
    viewModel: SettingsInfoVM = rememberJsViewModel {
        SettingsInfoVM(viewModelCallback)
    }
) {
    PageColumnContainer{
        JsCustomTabBar(
            onBack = { viewModel.back() },
            tabBarType = TabBars.DefaultTabBar(stringResource(Res.string.nav_settings_info_title))
        )

        SettingsInfoItemJs(
            imageId = "ic_settings_privacy",
            text = stringResource(resource = Res.string.nav_settings_privacy_title)
        ) { viewModel.showPrivacyPage() }

        SettingsInfoItemJs(
            imageId = "ic_settings_terms",
            text = stringResource(resource = Res.string.nav_settings_terms_title)
        ) { viewModel.showTermsPage() }

    }
}

@Composable
private fun SettingsInfoItemJs(imageId: String, text: String, onClick: () -> Unit){

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(48.dp)
            .clickable { onClick.invoke() }
    ) {
        Box(
            modifier = Modifier.padding(start = 16.dp, top = 12.dp, bottom = 12.dp)
        ){
            JsImageView(
                drawableId = imageId,
                contentScale = ContentScale.Fit,
                modifier = Modifier.size(36.dp, 24.dp)
            )
        }

        Column(
            modifier = Modifier
                .padding(start = 16.dp)
                .fillMaxHeight()
                .weight(1),
        ){
            Box(modifier = Modifier.weight(1)){
                JsTextView(
                    text = text,
                    textSize = 18,
                    fontWeight = FontWeight.Medium,
                    modifier = Modifier.align(Alignment.CenterStart)
                )
            }
            JsDividerLine()
        }
    }
}