package kotpref.models.photos

import kotlinx.serialization.SerialName

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-10-02.
 */
@kotlinx.serialization.Serializable
data class ModerateNudity(
    @SerialName("raw") var raw: Double? = 0.0,
    @SerialName("safe") var safe: Double? = 0.0,
    @SerialName("partial") var partial: Double? = 0.0,
    @SerialName("partial_tag") var partialTag: String? = null
) {

    fun getPartialTag(): PartialTag? {
        return when (partialTag) {
            PartialTag.cleavage.name -> PartialTag.cleavage
            else -> null
        }
    }

}

enum class PartialTag {
    cleavage
}