@Composable
fun OnBoardingTransTrialScreen(
    previewMode: Boolean = true,
    viewModelCallback: (OnBoardingTransTrialEvent) -> Unit,
    viewModel: OnBoardingTransTrialVM = rememberJsViewModel {
        OnBoardingTransTrialVM(previewMode, viewModelCallback)
    }
) {
    PageContainer {
        Column(
            modifier = Modifier.fillMaxSize(),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            JsCustomTabBar(
                onBack = { viewModel.back() },
                withBackground = false,
                tabBarType = TabBars.EmptyTabBar
            )

            Box(modifier = Modifier.weight(1f).fillMaxWidth()) {
                OnBoardingTransTrialsContent(viewModel)
            }

            Box(modifier = Modifier.height(26.dp))
        }


        if (!previewMode) StripeByAppleGoogleScreen(
            viewModel,
            onPurchase = { paymentId, priceId, productId ->
                viewModel.showStripeAppleGoogle.value = false
                viewModel.boughtSuccess()
            }, onError = {
                viewModel.dialogManager.showMessageDialog(it)
            }, onClose = {
                viewModel.showStripeAppleGoogle.value = false
            }
        )

        if (viewModel.showingProgress.value) LoadingBlockState()
        if (viewModel.showingPreloader.value) Box(
            Modifier.fillMaxSize().background(JsMainTheme.colors.main_color_background)
        ) {
            JsCircularProgressIndicator(
                modifier = Modifier.align(Alignment.Center), color = Colors.White
            )
        }
    }
}

@Composable
fun OnBoardingTransTrialsContent(viewModel: OnBoardingTransTrialVM) {
    val previewMode = viewModel.previewMode
    val containerSize = remember { mutableStateOf(0) }


    Column(
        modifier = Modifier.fillMaxSize().onSizeChanged { width, height ->
            containerSize.value = height
        },
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        var modifier = Modifier.fillMaxWidth().overflow(Overflow.Auto)
        modifier =
            if (containerSize.value == 0) modifier.fillMaxHeight()
            else modifier.heightIn(min = containerSize.value.px)

        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Box(modifier = Modifier.weight(1f))

            JsImageView(
                "ic_trans_trial_logo",
                format = "png",
                modifier = Modifier.fillMaxWidth(0.2f.toPercent())
            )

            Spacer(modifier = Modifier.height(20.dp))
            JsAutoResizeText(
                text = stringResource(resource = Res.string.onboarding_trans_trial_title),
                modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp),
                color = JsMainTheme.colors.text_color_default,
                fontWeight = FontWeight.Bold,
                maxTextSize = 16,
                minTextSize = 12,
                textAlign = TextAlign.Center,
                maxLines = 2
            )

            Spacer(modifier = Modifier.height(20.dp))
            JsAutoResizeText(
                text = stringResource(resource = Res.string.onboarding_trans_woman_trial_text),
                modifier = Modifier.fillMaxWidth().padding(horizontal = 48.dp),
                color = JsMainTheme.colors.text_color_default.copy(0.8f),
                maxTextSize = 16,
                minTextSize = 12,
                textAlign = TextAlign.Center,
            )

            Box(modifier = Modifier.weight(1f))

            Spacer(modifier = Modifier.height(30.dp))
            TransModeText(viewModel)
            Spacer(modifier = Modifier.height(if (previewMode) 30.dp else 20.dp))
            TryFreeView(previewMode)
            Spacer(modifier = Modifier.height(if (previewMode) 30.dp else 20.dp))
            InvisibleModeText(previewMode)
            Spacer(modifier = Modifier.height(30.dp))
            Box(modifier = Modifier.weight(1f))

            val buttonTextRes = if (previewMode) Res.string.onboarding_trans_trial_activate_btn_free
            else Res.string.onboarding_trans_trial_activate_btn

            Box(Modifier.fillMaxWidth().height(50.dp), contentAlignment = Alignment.Center) {
                OnboardingButton(title = stringResource(buttonTextRes)) { viewModel.clickedBtn() }
            }

            Spacer(modifier = Modifier.height(20.dp))

            if (!previewMode) {
                val isWeekFormat = Billings.isWeekSubscribe(viewModel.productId.value)
                val periodFormat = stringResource(
                    resource =
                        if (isWeekFormat) Res.string.subscribe_settings_weekly_text
                        else Res.string.subscribe_settings_month_text
                ).lowercase()

                JsAutoResizeText(
                    text = stringResource(
                        resource = Res.string.onboarding_trans_trial_activate_price,
                        "${viewModel.priceString.value} $periodFormat"
                    ),
                    modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp),
                    color = Color.rgb(0X687C8B),
                    maxTextSize = 10,
                    textAlign = TextAlign.Center,
                    maxLines = 1
                )

                Spacer(modifier = Modifier.height(20.dp))

                CancelAnytimeStripe()
                Spacer(modifier = Modifier.height(20.dp))
            }

            JsAutoResizeText(
                text = stringResource(resource = Res.string.onboarding_trans_trial_skip_btn),
                modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp).clickable {
                    viewModel.showNextPage()
                },
                color = JsMainTheme.colors.text_color_default,
                maxTextSize = 14,
                minTextSize = 12,
                textAlign = TextAlign.Center,
                textDecoration = TextDecorationLine.Underline
            )
        }
    }
}

@Composable
fun TransModeText(viewModel: OnBoardingTransTrialVM) {
    val transMode = stringResource(resource = Res.string.onboarding_trans_trial_mode_title)
    val fullText = stringResource(resource = Res.string.onboarding_trans_trial_mode_text, transMode)

    val transModeModifier = Modifier.styleModifier {
        fontWeight(FontWeight.Bold)
    }

    val transModeStartIndex = fullText.indexOf(transMode)
    val freeText = stringResource(
        resource = Res.string.onboarding_trans_trial_mode_text_free,
        viewModel.notVisibleGenders.value
    )

    val annotatedString =
        if (viewModel.previewMode) listOf(AnnotatedString(freeText, null))
        else listOf(
            AnnotatedString(fullText.substring(0, transModeStartIndex), null),
            AnnotatedString(
                fullText.substring(transModeStartIndex, transModeStartIndex + transMode.length),
                transModeModifier
            ),
            AnnotatedString(
                fullText.substring(transModeStartIndex + transMode.length),
                null
            ),
        )

    JsAnnotatedStringsText(
        annotatedStrings = annotatedString,
        textSize = 16,
        textColor = JsMainTheme.colors.text_color_default,
        modifier = Modifier.fillMaxWidth().padding(horizontal = 24.dp),
        textAlign = TextAlign.Center,
    )
}

@Composable
fun TryFreeView(previewMode: Boolean) {
    Box(Modifier.fillMaxWidth().padding(horizontal = 24.dp)) {
        Column(
            Modifier.fillMaxWidth().background(JsMainTheme.colors.text_color_white.copy(0.2f))
                .clipByCorner()
                .padding(horizontal = 16.dp, vertical = 10.dp)
        ) {
            if (previewMode) {
                Row(Modifier.align(Alignment.CenterHorizontally)) {
                    JsTextView(
                        text = "\uD83D\uDC8E",
                        modifier = Modifier.padding(end = 2.dp),
                        fontWeight = FontWeight.Bold,
                        textSize = 14,
                    )
                    JsTextView(
                        text = stringResource(resource = Res.string.onboarding_trans_trial_try_free_text),
                        modifier = Modifier.weight(1f),
                        textAlign = TextAlign.Center,
                        textColor = JsMainTheme.colors.text_color_default,
                        fontWeight = FontWeight.Bold,
                        textSize = 14,
                    )
                }
            } else {
                JsAutoResizeText(
                    text = stringResource(resource = Res.string.onboarding_trans_trial_try_free_text_1),
                    modifier = Modifier.fillMaxWidth(),
                    color = JsMainTheme.colors.text_color_default,
                    fontWeight = FontWeight.Bold,
                    maxTextSize = 12,
                    minTextSize = 10,
                )
                Spacer(modifier = Modifier.height(4.dp))
                JsAutoResizeText(
                    text = stringResource(resource = Res.string.onboarding_trans_trial_try_free_text_2),
                    modifier = Modifier.fillMaxWidth(),
                    color = JsMainTheme.colors.text_color_default,
                    maxTextSize = 12,
                    minTextSize = 10,
                )
            }
        }
    }
}

