@Composable
fun OnboardingButton(
    title: String,
    textColor: Color = JsMainTheme.colors.text_color_default,
    backgroundColor: Color = JsMainTheme.colors.gradient_main_button_start,
    backgroundGradientColor: Color? = JsMainTheme.colors.gradient_main_button_end,
    withBorder: Boolean = false,
    buttonWidth: Float = 0.7f,
    onClick: () -> Unit,
) {
    var modifier = Modifier
        .fillMaxWidth(buttonWidth.toPercent())
        .height(50.dp)
        .clickable { onClick() }
        .clipByCorner(25)
    modifier = if (withBorder) {
        modifier.clipByCorner(25).border(1.dp, color = backgroundColor)
    } else {
        if (backgroundGradientColor == null) {
            modifier.background(color = backgroundColor)
        } else {
            val colors = listOf(
                JsMainTheme.colors.gradient_subscribe_unlim_color_start,
                JsMainTheme.colors.gradient_subscribe_unlim_color_end
            )
            modifier.gradientBackground(colors, 300)
        }
    }
    Box(
        modifier = modifier,
        contentAlignment = Alignment.Center
    ) {
        JsAutoResizeText(
            text = title,
            modifier = Modifier.padding(start = 10.dp, end = 10.dp),
            color = textColor,
            maxTextSize = 16,
            fontWeight = FontWeight.Medium,
            textAlign = TextAlign.Center,
        )
    }
}