@Composable
fun OnboardingInterestsScreen(
    useSelectData: Boolean,
    profileDataField: ProfileDataField,
    viewModelCallback: (ProfileMultiSelectEvent) -> Unit,
    viewModel: ProfileMultiSelectVM = rememberJsViewModel {
        ProfileMultiSelectVM(useSelectData, profileDataField, viewModelCallback)
    }
) {
    val screenSize = getJsScreenSizeInfo()
    val height = screenSize.heightPx
    val fullScreenScroll = resultHeight.value > height

    if (fullScreenScroll) {
        PageContainer { OnboardingInterestsScreenContent(viewModel) }
    } else {
        Box(Modifier.fillMaxSize()) { OnboardingInterestsScreenContent(viewModel) }
    }
}

@Composable
private fun OnboardingInterestsScreenContent(viewModel: ProfileMultiSelectVM) {
    Column(
        modifier = Modifier.fillMaxSize(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Box(modifier = Modifier.fillMaxWidth()) {
            val titlePadding = remember { mutableStateOf(0) }
            JsTextView(
                viewModel.profileMultiSelectTitle.value, 20,
                Modifier.align(Alignment.Center)
                    .padding(start = titlePadding.value.dp, end = titlePadding.value.dp),
                FontWeight.Medium,
                JsMainTheme.colors.text_color_default,
                maxLines = 1
            )

            Box(Modifier.padding(top = 16.dp, left = 16.dp, bottom = 16.dp)) {
                TabBarBackArrow { viewModel.back() }
            }
        }
        JsTextView(
            text = viewModel.profileMultiSelectText.value,
            modifier = Modifier.fillMaxWidth().padding(start = 24.dp, end = 24.dp, bottom = 12.dp),
            textColor = JsMainTheme.colors.text_color_gray,
            textSize = 16,
            fontWeight = FontWeight.Normal,
            textAlign = TextAlign.Center
        )
        Spacer(modifier = Modifier.height(8.dp))
        Column(modifier = Modifier.fillMaxWidth().weight(1f).overflow(Overflow.Auto)) {
            JsButtonsProfileMultiSelect(itemsState = viewModel.profileMultiSelectList) {
                viewModel.setSelectItem(it)
            }
        }
        Spacer(modifier = Modifier.height(20.dp))

        if (!viewModel.userRegistered) {
            Box(
                modifier = Modifier.height(50.dp).fillMaxWidth(),
                contentAlignment = Alignment.Center
            ) {
                SplashFiorryButton(
                    title = stringResource(resource = Res.string.onboarding_start_btn_text_next)
                ) { viewModel.clickedBtn(false) }
            }
            Spacer(modifier = Modifier.height(26.dp))
        }
    }

    if (viewModel.showingProgress.value) LoadingBlockState()
}

@Composable
fun JsButtonsProfileMultiSelect(
    itemsState: List<MultiSelectItem>,
    onClick: (MultiSelectItem) -> Unit
) {
    FlowRow(
        modifier = Modifier.fillMaxWidth()
            .padding(bottom = 16.dp)
            .padding(horizontal = 8.dp),
        alignment = JustifyContent.Center,
        innerPadding = 8,
    ) {
        itemsState.forEachIndexed { index, multiSelectItem ->
            val isDisableItem = itemsState.filter { it.onSelected }.size >= 10
                    && !multiSelectItem.onSelected
            val color =
                if (isDisableItem) JsMainTheme.colors.text_color_gray
                else if (AppVariant.isEliziumOrParadiz()) JsMainTheme.colors.app_main_color
                else jsBackgroundItemColor(itemsState.size, index % 7)
            ProfileMultiSelectItem(multiSelectItem, isDisableItem, color, onClick)
        }
    }
}

@Composable
fun ProfileMultiSelectItem(
    item: MultiSelectItem,
    isDisableItem: Boolean,
    color: Color,
    onClick: (MultiSelectItem) -> Unit
) {
    val textColor = if (isDisableItem) color else JsMainTheme.colors.text_color_default

    Box(
        modifier = Modifier.clickable { onClick.invoke(item) }
            .clipByCorner(30)
            .background(if (item.onSelected) color else JsMainTheme.colors.main_color_background)
            .border(
                2.dp,
                LineStyle.Solid,
                color = if (item.onSelected) color else color.copy(alpha = 0.5f)
            ),
    ) {
        Box(Modifier.padding(horizontal = 16.dp, vertical = 12.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                val image =
                    if (item.onSelected) Res.drawable.ic_accept_ok else Res.drawable.ic_plus
                JsImageView(
                    drawableRes = image,
                    modifier = Modifier.size(20.dp),
                    tintColor = textColor
                )

                JsTextView(
                    text = item.itemTitle,
                    modifier = Modifier.padding(start = 12.dp),
                    textColor = textColor,
                    textSize = 16,
                    fontWeight = FontWeight.Medium,
                    textAlign = TextAlign.Center,
                    maxLines = 2
                )
            }
        }
    }
}