package managers

import dependencies.di
import kotlinx.browser.document
import kotlinx.browser.window
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.logging.CommonLogger
import kotpref.logging.LogLvl
import kotpref.models.AppVariant
import kotpref.stores.IAppKeysStorage
import managers.VercelManager.loadVercelConfig
import org.kodein.di.instance
import org.w3c.dom.HTMLScriptElement
import kotlin.js.Promise.Companion.resolve

@Suppress(names = ["EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING"])
actual class MixPanelManager {

    private var initialized = false
    private var queue = mutableListOf<Pair<AmplitudeEvent, Map<String, Any?>>>()
    private var identifyId = ""
    private var identifies = hashMapOf<String, String>()

    val appKeys by di.instance<IAppKeysStorage>()
    private val logger = CommonLogger()

    private val stub = """
(function(f,b){
    if(!b.__SV){
        var a,e,i,g;
        window.mixpanel = b;
        b._i=[];
        b.init = function(token, config, name){
            function p(obj, methodName){
                var parts = methodName.split(".");
                if (parts.length == 2) {
                    obj = obj[parts[0]];
                    methodName = parts[1];
                }
                obj[methodName] = function(){
                    obj.push([methodName].concat(Array.prototype.slice.call(arguments,0)))
                }
            }
            var target = b;
            if (name !== undefined) {
                target = b[name] = [];
            } else {
                name = "mixpanel";
            }
            target.people = target.people || [];
            target.toString = function(_){
                var str = "mixpanel";
                if (name !== "mixpanel") str += "." + name;
                if (!_ ) str += " (stub)";
                return str;
            };
            target.people.toString = function(){
                return target.toString(1) + ".people (stub)"
            };
            i="disable time_event track track_pageview track_links track_forms register register_once alias unregister identify name_tag set_config reset people.set people.set_once people.unset people.increment people.append people.union people.track_charge people.clear_charges people.delete_user"
                .split(" ");
            for(g=0; g < i.length; g++) p(target, i[g]);
            b._i.push([token, config, name]);
        };
        b.__SV = 1.2;
    }
   })(document, window.mixpanel || []);
    """.trimIndent()

    fun init() {
        if (!AppVariant.isFiorry()) return
        if (initialized) {
            resolve(Unit)
            return
        }

        CoroutineScope(Dispatchers.Main).launch {
            val vercelConfig = loadVercelConfig()
            val mixPanelToken = if (AppVariant.isFiorry()) vercelConfig.mixpanelKey else ""
            if (mixPanelToken.isNullOrEmpty()) return@launch

            val stubScript = document.createElement("script") as HTMLScriptElement
            stubScript.type = "text/javascript"
            stubScript.text = stub
            document.head!!.appendChild(stubScript)

            val sdk = document.createElement("script") as HTMLScriptElement
            sdk.async = true
            sdk.src = "https://cdn.mxpnl.com/libs/mixpanel-2-latest.min.js"

            sdk.onload = {
                window.asDynamic().mixpanel.init(mixPanelToken)
                window.asDynamic().mixpanel.register(js("{ Platform: 'Web' }"))
                initialized = true
                logger.log(LogLvl.DEBUG, "MixPanelManager", "initialized")
                checkQueue()
            }

            document.head?.appendChild(sdk)
        }
    }

    private fun checkQueue() {
        if (queue.isNotEmpty()) {
            val item = queue.first()
            queue.remove(item)
            sending(item.first, item.second)
        }
    }

    private fun sending(event: AmplitudeEvent, params: Map<String, Any?>) {
        if (identifyId.isNotEmpty()) sendIdentifyId(identifyId)
        if (identifies.isNotEmpty()) sendIdentifies(hashMapOf())

        if (params.isNotEmpty()) {
            logger.log(
                LogLvl.DEBUG,
                "MixPanelManager",
                "sendEvent ${event.name}; with params = $params"
            )
            val jsonProps = mapToJson(params)
            window.asDynamic().mixpanel.track(event.name, jsonProps)
        } else {
            window.asDynamic().mixpanel.track(event.name)
            logger.log(LogLvl.DEBUG, "MixPanelManager", "sendEvent ${event.name}")
        }
        checkQueue()
    }

    fun mapToJson(props: Map<String, Any?>): dynamic {
        val jsonString = JSON.stringify(props)
        return JSON.parse(jsonString)
    }

    actual fun sendIdentifyId(id: String) {
        if (!initialized) {
            identifyId = id
            return
        }
        if (id.isEmpty() || appKeys.mixPanelUserId.isNotEmpty()) return
        window.asDynamic().mixpanel.identify(id)
        appKeys.mixPanelUserId = id
        logger.log(LogLvl.DEBUG, "MixPanelManager", "sendIdentifyId: $id")
        identifyId = ""
    }

    actual fun sendIdentify(key: String, value: String) {
        if (!initialized) {
            if (value.isNotEmpty()) identifies[key] = value
            return
        }
        if (value.isNotEmpty()) identifies[key] = value
        sendIdentifies(identifies)
    }

    actual fun sendIdentifies(properties: HashMap<String, String>) {
        val validProperties = properties.filterValues { it.isNotEmpty() }
        if (!initialized) {
            identifies.putAll(validProperties)
            return
        }

        val jsonProps = mapToJson(identifies)
        if (jsonProps != null) {
            window.asDynamic().mixpanel.people.set(jsonProps)
            logger.log(LogLvl.DEBUG, "MixPanelManager", "sendIdentifies: $validProperties")
        }
        identifies.clear()
    }

    actual fun sendEvent(event: AmplitudeEvent, params: Map<String, Any?>) {
        if (!initialized) {
            queue.add(event to params)
            return
        }
        if (queue.isNotEmpty()) {
            queue.add(event to params)
            checkQueue()
        } else {
            sending(event, params)
        }
    }
}