package ui.screens.main.mainStart

import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import dependencies.RepositoriesProvider
import dependencies.di
import kotpref.stores.IAppKeysStorage
import org.kodein.di.instance
import kotlin.getValue


sealed class MainStartScreenEvent {
    object OnChatTabSelected : MainStartScreenEvent()
    object OnPeopleTabSelected : MainStartScreenEvent()
    object OnSettingsTabSelected : MainStartScreenEvent()
    object ClearData : MainStartScreenEvent()
}
class CommonMainStartViewModel(
    val obtainEvent: (MainStartScreenEvent) -> Unit
): ViewModel() {

    val appKeys by di.instance<IAppKeysStorage>()
    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val accountRepository = repositoriesProvider.accountRepository

    val selectedTab = mutableStateOf(1)

    init {
        appKeys.userRegistered = true
    }

    fun onTabSelected(index: Int) {
        if (selectedTab.value != index) {
            selectedTab.value = index
            when (index) {
                0 -> obtainEvent(MainStartScreenEvent.OnChatTabSelected)
                1 -> obtainEvent(MainStartScreenEvent.OnPeopleTabSelected)
                2 -> obtainEvent(MainStartScreenEvent.OnSettingsTabSelected)
            }
        }
    }
}
