import androidx.compose.runtime.mutableStateListOf
import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dependencies.AccountRepository
import dependencies.di
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.error_message_account_edit_survey_text
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotpref.models.account.Account
import kotpref.models.account.AccountPhoto
import kotpref.models.account.enums.AccountInfoType
import kotpref.models.typeConverter.DateTimeConverter
import kotpref.profile.ProfileData
import kotpref.profile.ProfileDataField
import kotpref.utils.IDialogManager
import managers.AmplitudeManager
import managers.analytics.AnalyticsManager
import managers.analytics.AnalyticsPeopleEvents
import org.kodein.di.instance
import ui.managers.profileData.ProfileDataManager
import ui.resources.ResManager.getString

sealed class PeopleProfileEditEvent {
    data object Back : PeopleProfileEditEvent()
    data object ProfilePhotosScreen : PeopleProfileEditEvent()
    data object MenuPhotosBottomSheet : PeopleProfileEditEvent()
    data object CropPhoto : PeopleProfileEditEvent()
    data object ProfileAddCompatibility : PeopleProfileEditEvent()
    data class PeopleProfileAddInfo(val profileData: ProfileData) : PeopleProfileEditEvent()
    data class ProfileMultiSelect(val profileData: ProfileData) : PeopleProfileEditEvent()
}

class PeopleProfileEditVM(
    val viewModelCallback: (PeopleProfileEditEvent) -> Unit
) : ViewModel() {

    private val amplitudeManager by di.instance<AmplitudeManager>()
    private val accountRepository by di.instance<AccountRepository>()
    private val dialogManager by di.instance<IDialogManager>()
    val profileDataConverter = ProfileDataManager()

    val account: MutableState<Account?> = mutableStateOf(null)
    val aboutMe = mutableStateOf("")
    var aboutMeSingleLine = ""
    val nickname = mutableStateOf("")

    private val photos = mutableStateListOf<String>()
    private val _photosListFlow = MutableStateFlow(photos)
    val photosListFlow: StateFlow<List<String>> get() = _photosListFlow
    var pickPhoto: String = ""
    val profileAgeSwitchChecked = mutableStateOf(false)
    val profileSettingsLocationSwitchChecked = mutableStateOf(false)
    val invisibleIcon = mutableStateOf("ic_settings_invisible")
    val isLoading = mutableStateOf(true)

    init {
        accountRepository.loadMe(::updateData)
    }

    private fun updateData(acc: Account?) {
        account.value = acc
        profileDataConverter.setMeasurement(acc?.measurementUnits)
        profileDataConverter.setAccount(acc)

        photos.addAll(sortPhotos(acc?.photos))
        setInvisibleIcon()
        initSwitch()
//        initAboutMeText()
        isLoading.value = false
    }

    private fun sortPhotos(photos: MutableList<AccountPhoto>?): MutableList<String> {
        val publicPhotos = mutableListOf<AccountPhoto>()
        publicPhotos.addAll(photos?.sortedBy { it.sortId } ?: mutableListOf())

        val items = mutableListOf<String>()
        publicPhotos.forEach { photo -> photo.url?.let { items.add(it) } }
        return items
    }

    fun initSwitch() {
        val accountPlus = account.value?.subscriptionStatus?.subscription?.type == 1
        val accountUnlimited = account.value?.subscriptionStatus?.subscription?.type == 2

        profileAgeSwitchChecked.value =
            if (accountPlus || accountUnlimited) account.value?.showMyAge != 0 else true

        profileSettingsLocationSwitchChecked.value =
            if (accountUnlimited) account.value?.showMyLocation != 0 else true
    }

    fun setInvisibleIcon() {
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            account.value = accountRepository.getMyAccount()
            val subscribeType = account.value?.subscriptionStatus?.subscription?.type ?: 0
            val genders = account.value?.notVisibleForGenders
            val minAge = account.value?.showMinAge ?: 18
            val maxAge = account.value?.showMaxAge ?: 100

            invisibleIcon.value = if (((genders?.size
                    ?: 0) > 0 || minAge > 18 || maxAge < 100)/* && subscribeType != 0*/)
                "ic_settings_invisible_on"
            else "ic_settings_invisible"
        }
    }

    suspend fun clickedBtn(profileData: ProfileData) {
        if (profileData.canChangeData) {
            when (profileData.type) {
                AccountInfoType.Multi -> {
                    viewModelCallback.invoke(PeopleProfileEditEvent.PeopleProfileAddInfo(profileData))
                }

                AccountInfoType.Compatibility -> {
                    val lessThanOneDay =
                        DateTimeConverter.lessThanDays(
                            account.value?.compatibilitiesUpdatedAt,
                            1,
                            false
                        )
                    if (lessThanOneDay) {
                        val message = getString(Res.string.error_message_account_edit_survey_text)
                        dialogManager.showMessageDialog(message)
                    } else viewModelCallback.invoke(PeopleProfileEditEvent.ProfileAddCompatibility)
                }

                AccountInfoType.Zodiac -> {
                }

                else -> {
                    if (profileData.profileDataField == ProfileDataField.Interests) {
                        AnalyticsManager.onSendEvent(AnalyticsPeopleEvents.editProfileInterestsClick.name)
                    } else if (profileData.profileDataField == ProfileDataField.Music) {
                        AnalyticsManager.onSendEvent(AnalyticsPeopleEvents.editProfileMusicClick.name)
                    }
                    viewModelCallback.invoke(PeopleProfileEditEvent.PeopleProfileAddInfo(profileData))
                }
            }
        }
    }

    fun onBack() {
        viewModelCallback.invoke(PeopleProfileEditEvent.Back)
    }
}