package ui.screens.settings.settingsBloackedUsers

import androidx.annotation.UiThread
import dependencies.AccountRepository
import dependencies.di
import kotpref.models.account.Account
import managers.analytics.AnalyticsManager
import managers.analytics.AnalyticsSettingsEvents
import org.kodein.di.instance
import ui.components.BaseSharedViewModel
import ui.screens.settings.settingsBloackedUsers.models.SettingsBlockedUsersEvent
import ui.screens.settings.settingsBloackedUsers.models.SettingsBlockedUsersVS


class SettingsBlockedUsersVM(
    val isBlockedUsers: Boolean,
    private val back: () -> Unit
) : BaseSharedViewModel<SettingsBlockedUsersVS, SettingsBlockedUsersEvent>(
    initialState = SettingsBlockedUsersVS.Loading
) {

    private val accountRepository by di.instance<AccountRepository>()

    override fun obtainEvent(event: SettingsBlockedUsersEvent) {
        when (viewState) {
            is SettingsBlockedUsersVS.WithUsers -> reduce(event)
            else -> {}
        }
    }

    private fun reduce(event: SettingsBlockedUsersEvent) {
        when (event) {
            is SettingsBlockedUsersEvent.UnblockUser -> {
                //viewState = SettingsBlockedUsersVS.Loading
                val profileId = event.profileId
                fun onSuccess() {
                    val accounts = event.accounts.filter { it.id != profileId }
                    viewState = if (accounts.isEmpty()) SettingsBlockedUsersVS.EmptyUsers
                    else SettingsBlockedUsersVS.WithUsers(accounts)
                }

                if (isBlockedUsers) accountRepository.unblockUser(profileId, onSuccess = {
                    AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.unblockUser.name)
                    onSuccess()
                }) else accountRepository.showUser(profileId, onSuccess = {
                    AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.unhideUser.name)
                    onSuccess()
                })
            }
        }
    }

    init {
        if (isBlockedUsers) accountRepository.blockUsers(::updateData, ::onError)
        else accountRepository.hiddenUsers(::updateData, ::onError)
    }

    private fun onError() {
        viewState = SettingsBlockedUsersVS.EmptyUsers
    }

    private fun updateData(accounts: MutableList<Account>?) {
        if (accounts != null && accounts.size > 0) {
            viewState = SettingsBlockedUsersVS.WithUsers(accounts)
        } else onError()
    }

    fun back() {
        back.invoke()
    }

}