@Composable
fun SettingsScreenJs(
    initEventCallback: ((SettingsEventVM) -> Unit) -> Unit,
    viewModelCallback: (SettingsRouteEvent) -> Unit,
    viewModel: SettingsVM = rememberJsViewModel {
        SettingsVM(viewModelCallback, initEventCallback)
    }
) {
    Column(
        modifier = Modifier.fillMaxSize().styleModifier {
            property("overflow-y", "hidden")
        }
            .background(JsMainTheme.colors.main_color_background)
    ) {
        JsCustomTabBar(
            onBack = {},
            tabBarType = TabBars.OnlyTitleTabBar(stringResource(resource = Res.string.nav_settings_title))
        )

        Column(
            modifier = Modifier
                .fillMaxWidth()
                .styleModifier {
//                    property("flex", "1 1 auto")
                    property("overflow-y", "auto")
//                    property("min-height", "0")
                }
                .padding(start = 16.dp, end = 16.dp, top = 12.dp, bottom = 14.dp)
        ) {
            ProfileInfoJs(viewModel)
            ProfileSettingsJs(viewModel)
            AppearanceSettingsJs(viewModel)
            CommunitySettingsJs(viewModel)
            AccountSettingsJs(viewModel)
            InterlinkingContainerJs(viewModel)
        }
    }
}

@Composable
fun ProfileInfoJs(viewModel: SettingsVM) {
    Row(
        modifier = Modifier
            .settingsBgModifierJs()
            .minHeight(60.dp)
            .padding(leftRight = 16.dp, topBottom = 12.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        Box(
            modifier = Modifier
                .size(48.dp)
                .clipByCorner(24)
        ) {
            AsyncAvatarJs(
                avatar = viewModel.avatar.value ?: "",
                placeholderSize = 48,
            )
        }

        Column(
            Modifier
                .padding(start = 20.dp, end = 12.dp)
                .weight(1)
        ) {
            val myAccount = viewModel.myAccount.value
            Box {
                val showVerifyIcon =
                    myAccount?.getVerificationStatus() == AccountVerificationStatus.VERIFIED
                JsAutoResizeText(
                    text = myAccount?.nickname ?: "",
                    maxTextSize = 14,
                    fontWeight = FontWeight.Medium,
                    maxLines = 1,
                    modifier = Modifier
                        .padding(end = if (showVerifyIcon) 24.dp else 8.dp)
                        .align(Alignment.CenterStart)
                )

                if (showVerifyIcon) JsImageView(
                    "ic_verification_verify",
                    modifier = Modifier
                        .size(16.dp)
                        .align(Alignment.CenterEnd)
                )
            }

            val profileLogin = when (myAccount?.authProvider ?: 0) {
                1, 5 -> myAccount?.login
                2 -> stringResource(Res.string.nav_settings_sign_in_facebook_title)
                4 -> stringResource(Res.string.nav_settings_sign_in_google_title)
                else -> stringResource(Res.string.string_empty)
            }
            if (!profileLogin.isNullOrEmpty()) {
                JsTextView(
                    text = profileLogin,
                    textSize = 14,
                    textColor = JsMainTheme.colors.text_color_gray,
                    modifier = Modifier.padding(top = 4.dp)
                )
            }
        }

        //Arrow
        JsSettingsImageArrow(
            height = 24,
            tintColor = JsMainTheme.colors.app_main_color,
        )
    }
}

@Composable
fun ProfileSettingsJs(viewModel: SettingsVM) {
    Column(modifier = Modifier.settingsCategoryModifierJs()) {
        SettingsCategoryTitleJs(stringResource(resource = Res.string.nav_settings_profile))
        Column(modifier = Modifier.settingsBgModifierJs()) {
            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_photos),
                "ic_nav_photos"
            ) {
                viewModel.onPhotosClick()
            }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_edit_profile),
                "ic_profile_edit"
            ) {
                viewModel.onEditProfileClick()
            }

            val myAccount = viewModel.myAccount.value
            if (myAccount?.getVerificationStatus() != AccountVerificationStatus.VERIFIED) {
                val backgroundColor =
                    AccountVerificationStatusManagerJs().getVerificationStatusColor(  //Перенести AccountVerificationStatusManager
                        myAccount?.getVerificationStatus(), true
                    )
                SettingsItemJs(
                    stringResource(resource = Res.string.verification_settings_title),
                    "ic_settings_verification",
                    backgroundColor = backgroundColor
                ) { viewModel.onVerificationProfileClick() }
            }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_share_profile),
                "ic_settings_share"
            ) { viewModel.onShareProfileClick() }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_invisible_mode_title),
                viewModel.getInvisibleIconJs(),
//                itemType = SettingsItemType.Default(1, viewModel.subscribeType.intValue)
            ) { viewModel.onInvisibleModeClick() }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_subscription_title),
                "ic_settings_subscription",
                showDivider = viewModel.currentScreenType.intValue != 0,
                itemType = SettingsItemType.Text(stringResource(viewModel.getSubscribeName()))
            ) { viewModel.showSubscriptionPage() }

            if (viewModel.currentScreenType.intValue != 0) {
                val itemType =
                    if (viewModel.clearDislikesInProgress.value) SettingsItemType.Progress
                    else SettingsItemType.Default()

                SettingsItemJs(
                    stringResource(resource = Res.string.nav_settings_clear_dislikes_title),
                    "ic_clear_dislikes",
                    showDivider = false,
                    itemType = itemType
                ) { viewModel.clearDislikes() }
            }
        }
    }
}

@Composable
fun AppearanceSettingsJs(viewModel: SettingsVM) {
    Column(modifier = Modifier.settingsCategoryModifierJs()) {
        SettingsCategoryTitleJs(stringResource(resource = Res.string.nav_settings_appearance))
        Column(modifier = Modifier.settingsBgModifierJs()) {
            val measureText =
                if (viewModel.myAccount.value?.measurementUnits == 2)
                    stringResource(resource = Res.string.nav_settings_measurement_imperial)
                else stringResource(resource = Res.string.nav_settings_measurement_metric)
            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_measure),
                "ic_settings_measure",
                itemType = SettingsItemType.Text(measureText)
            ) { viewModel.chooseMeasureUnits() }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_language),
                "ic_settings_language",
                itemType = SettingsItemType.Text(viewModel.getLanguageValue()),
                showDivider = false
            ) { viewModel.onLanguageClick() }
        }
    }
}

