@Composable
fun AccountSettingsJs(viewModel: SettingsVM) {
    Column(modifier = Modifier.settingsCategoryModifierJs()) {
        SettingsCategoryTitleJs(stringResource(resource = Res.string.nav_settings_account))
        Column(modifier = Modifier.settingsBgModifierJs()) {
            if (viewModel.showCredentialsItem.value) {
                SettingsItemJs(
                    stringResource(Res.string.nav_settings_credentials_change_email),
                    "ic_settings_email_new"
                ) { viewModel.onChangeMailClick() }

                SettingsItemJs(
                    stringResource(Res.string.nav_settings_password_page_title),
                    "ic_settings_password"
                ) { viewModel.onChangePasswordClick() }
            }

            if (viewModel.showRestoreItem.value) {
                val itemType =
                    if (viewModel.restoreInProgress.value) SettingsItemType.Progress
                    else SettingsItemType.Default()

                SettingsItemJs(
                    stringResource(resource = Res.string.nav_settings_restore_purchases),
                    "ic_settings_restore_purchases",
                    itemType = itemType
                ) { viewModel.clickRestorePurchasesPage() }
            }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_notifications_title),
                "ic_settings_notifications"
            ) { viewModel.showNotificationsPage() }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_blocked_title),
                "ic_settings_blocked"
            ) { viewModel.showBlockedUsers() }

            if (viewModel.currentScreenType.intValue < 2) {
                SettingsItemJs(
                    stringResource(resource = Res.string.nav_settings_hidden_title),
                    "ic_settings_hidden"
                ) { viewModel.showHiddenUsers() }
            }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_suspend_title),
                "ic_settings_suspend"
            ) { viewModel.showDeletePage() }

            SettingsItemJs(
                stringResource(resource = Res.string.nav_settings_log_out),
                "ic_nav_log_out",
                itemType = SettingsItemType.Empty,
                showDivider = false
            ) { viewModel.onLogOutClick() }
        }
    }
}

@Composable
fun InterlinkingContainerJs(viewModel: SettingsVM) {
    Column(
        modifier = Modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Box(
            modifier = Modifier.fillMaxWidth().margin(topBottom = 24.dp),
            contentAlignment = Alignment.Center
        ) {
            val text =
                stringResource(
                    if (AppVariant.isElizium()) Res.string.nav_settings_interlinking_title_elizium
                    else Res.string.nav_settings_interlinking_title
                )

            val interlinkingClickableText =
                if (AppVariant.isElizium()) stringResource(resource = Res.string.nav_settings_interlinking_btn_elizium)
                else stringResource(resource = Res.string.nav_settings_interlinking_btn)

            val textColor = JsMainTheme.colors.app_main_color
            val interlinkingModifier = Modifier.styleModifier {
                fontSize(getMaxMinSize(14).max.cssRem)
                color(textColor)
                fontWeight(FontWeight.Normal)
                whiteSpace("pre-wrap")
                textDecorationLine(TextDecorationLine.Underline)
                overflow(Overflow.Hidden)
                textAlign(TextAlign.Center)
            }.clickable { viewModel.showInterlinkingApp() }

            val fullText =
                text + (if (AppVariant.isElizium()) "\n" else " ") + interlinkingClickableText


            val interlinkingStartIndex = fullText.indexOf(interlinkingClickableText)
            val annotatedString = listOf(
                AnnotatedString(fullText.substring(0, interlinkingStartIndex), null),
                AnnotatedString(
                    fullText.substring(
                        interlinkingStartIndex,
                        interlinkingStartIndex + interlinkingClickableText.length
                    ), interlinkingModifier
                )
            )

            JsAnnotatedStringsText(
                annotatedStrings = annotatedString,
                textSize = 14,
                textColor = JsMainTheme.colors.text_color_gray,
                modifier = Modifier
                    .fillMaxWidth(80.percent)
                    .margin(bottom = 40.dp),
                textAlign = TextAlign.Center
            )
        }
    }
}


