package ui.components

import androidx.lifecycle.ViewModel
import kotlinx.coroutines.ExperimentalForInheritanceCoroutinesApi
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 14.02.2023.
 */
abstract class BaseSharedViewModel<State : Any, Event>(initialState: State) : ViewModel() {

    private val _viewStates = MutableStateFlow(initialState)

    fun viewStates(): WrappedStateFlow<State> = WrappedStateFlow(_viewStates.asStateFlow())

    protected var viewState: State
        get() = _viewStates.value
        set(value) {
            _viewStates.value = value
        }

    abstract fun obtainEvent(event: Event)
}

@OptIn(ExperimentalForInheritanceCoroutinesApi::class)
class WrappedStateFlow<T : Any>(private val origin: StateFlow<T>) : StateFlow<T> by origin


sealed class BaseEventVM : EventVM {
    data class ClickSystemBack(var systemBack: (Boolean) -> Unit) : BaseEventVM()
    data class GetOnPause(val onPause: (Boolean) -> Unit) : BaseEventVM()
    data class SetOnPause(val onPause: Boolean) : BaseEventVM()
    data object ClickBackBtn : BaseEventVM()
    data class ClickedBtn(val isDuplicate: Boolean = false) : BaseEventVM()
}

interface EventVM