package ui.screens.settings.settingsInvisibleGender

import androidx.annotation.UiThread
import androidx.compose.runtime.mutableStateListOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dependencies.RepositoriesProvider
import dependencies.di
import managers.analytics.AnalyticsManager
import managers.analytics.AnalyticsSubscriptionEvents
import kotpref.models.account.enums.AccountIam
import kotpref.models.account.enums.getString
import ui.components.BaseEventVM
import ui.components.EventVM
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.launch
import kotpref.profile.ProfileData
import org.kodein.di.instance
import ui.screens.onboarding.start.MultiSelectItem


class SettingsInvisibleGenderVM(
    val handleEvent: (MutableList<String>) -> Unit,
    val profileData: ProfileData,
    val viewModelCallback: (SettingsInvisibleGenderEvent) -> Unit,
    private val viewModelEvent: ((EventVM) -> Unit) -> Unit,
) : ViewModel() {

    val repositoriesProvider by di.instance<RepositoriesProvider>()
//    val dialogManager by di.instance<DialogManager>()

    private val accountRepository = repositoriesProvider.accountRepository
    private var subscribeType: Int? = null

    private var multiSelectList = mutableStateListOf<MultiSelectItem>()
    private val _multiSelectListFlow = MutableStateFlow(multiSelectList)
    val multiSelectListFlow: StateFlow<List<MultiSelectItem>> get() = _multiSelectListFlow


    fun obtainEvent(event: EventVM) {
        when (event) {
            SettingsInvisibleGenderEventVM.SubscribeSuccess -> initSubscribeType()
            is SettingsInvisibleGenderEventVM.SetSelectItem -> setSelectItem(event.item)
            SettingsInvisibleGenderEventVM.InfoBtnClick -> infoBtnClick()

            is BaseEventVM.ClickedBtn -> clickedBtn(event.isDuplicate)
            BaseEventVM.ClickBackBtn -> back()
        }
    }

    init {
        viewModelEvent.invoke(::obtainEvent)
        initSubscribeType()
        viewModelScope.launch(Dispatchers.Main) {
            AccountIam.sortList().forEach {
                val identity = it.secondResId()
                multiSelectList.add(MultiSelectItem(identity.getString()))
            }

            val infoData = profileData.infoData
            val selectData = profileData.selectData
            if (!selectData.isNullOrEmpty()) {
                selectData.split(", ").forEach {
                    for (i in 0 until infoData.size) {
                        if (infoData[i] == it) {
                            val index = multiSelectList.indexOf(MultiSelectItem(it))
                            multiSelectList[index] = multiSelectList[index].copy(onSelected = true)
                        }
                    }
                }
            }
        }
    }

    private fun initSubscribeType() {
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val account = accountRepository.getMyAccount()
            subscribeType = account?.subscriptionStatus?.subscription?.type ?: 0
            /*if (subscribeType == 1 || subscribeType == 2) {
                binding.btnBack.visibility = View.GONE
            }*/
        }
    }

    private fun setSelectItem(item: MultiSelectItem) {
        val index = multiSelectList.indexOf(item)
        multiSelectList[index] = multiSelectList[index].copy(onSelected = !item.onSelected)
    }

    private fun clickedBtn(duplicate: Boolean) {
        if (duplicate) {
            AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeSelectGendersAll.name)
            for (i in multiSelectList.indices) {
                multiSelectList[i] = multiSelectList[i].copy(onSelected = true)
            }
        } else {
            /*if (subscribeType == null || subscribeType == 0) {
                AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeSelectGendersSubscription.name)
                viewModelCallback.invoke(
                    SettingsInvisibleGenderEvent.SubscribePage(
                        returnToPeople = false,
                        openFromPage = "invisible_mode_select_genders"
                    )
                )
            } else {*/
                AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeSelectGendersSave.name)
                viewModelScope.launch(Dispatchers.Main) {
                    val data = mutableListOf<String>()
                    multiSelectList.forEach {
                        AccountIam.sortList().forEach { enum ->
                            val identity = enum.secondResId().getString()
                            if (identity == it.itemTitle && it.onSelected) data.add(identity)
                        }
                    }
                    handleEvent(data)
                }
            //}
        }
    }

    private fun infoBtnClick() {
        viewModelCallback.invoke(SettingsInvisibleGenderEvent.OnBoardingGenderInfo)
    }

    @UiThread
    private fun back() {
        viewModelCallback.invoke(SettingsInvisibleGenderEvent.Back)
    }
}

sealed class SettingsInvisibleGenderEventVM : EventVM {
    data object SubscribeSuccess : SettingsInvisibleGenderEventVM()
    data object InfoBtnClick : SettingsInvisibleGenderEventVM()
    data class SetSelectItem(val item: MultiSelectItem) : SettingsInvisibleGenderEventVM()
}

sealed class SettingsInvisibleGenderEvent {
    data class SubscribePage(val returnToPeople: Boolean, val openFromPage: String) :
        SettingsInvisibleGenderEvent()

    data object OnBoardingGenderInfo : SettingsInvisibleGenderEvent()
    data object Back : SettingsInvisibleGenderEvent()
}