@Composable
fun ProfileAddInfoScreenJs(
    profileData: ProfileData,
    viewModelCallback: (ProfileAddInfoEvent) -> Unit,
) {
    val months = shortMonthsList()
    val viewModel: ProfileAddInfoVM = rememberJsViewModel {
        ProfileAddInfoVM(profileData, months, viewModelCallback)
    }
    val state = viewModel.state.collectAsState()

    val title = stringResource(
        resource = when (profileData.profileDataField) {
            ProfileDataField.Iam -> Res.string.people_profile_identity_my_title
            else -> profileData.profileDataField.stringRes
        }
    )

    Column(
        modifier = Modifier.fillMaxSize().styleModifier {
            property("overflow-y", "hidden")
        }
            .background(JsMainTheme.colors.main_color_background)
    ) {
        JsCustomTabBar(
            onBack = { viewModel.onBack() },
            tabBarType = TabBars.DefaultTabBar(title.replace("-\n", ""))
        )

        Box(
            modifier = Modifier.fillMaxWidth().weight(1)
        ) {

            when (val value = state.value) {

                ProfileAddScreenState.Loading -> LoadingState()
                ProfileAddScreenState.DateState -> {
                    AddInfoItemsDate(viewModel)
                }

                is ProfileAddScreenState.MultiState -> {
                    val isSingleSelect = profileData.profileDataField == ProfileDataField.Iam
                    AddInfoItemsMulti(value.isMulti, isSingleSelect, viewModel )
                }

                ProfileAddScreenState.NumberState -> {
                    AddInfoItemsNumber(viewModel)
                }

                is ProfileAddScreenState.SingleState -> {
                    AddInfoItemsSingle(viewModel)
                }

                ProfileAddScreenState.TextState -> {

                }
            }
        }
    }
}

@Composable
private fun AddInfoItemsMulti(
    isMulti: Boolean,
    isSingleSelect: Boolean,
    viewModel: ProfileAddInfoVM
) {

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(topBottom = 8.dp)
            .gap(6.dp)
    ) {
        JsTextView(
            text = viewModel.profileMultiSelectTitle.value,
            modifier = Modifier.fillMaxWidth().padding(start = 24.dp, end = 24.dp, bottom = 12.dp),
            textColor = JsMainTheme.colors.text_color_gray,
            textSize = 16,
            fontWeight = FontWeight.Normal,
            textAlign = TextAlign.Center
        )
        Spacer(modifier = Modifier.height(8.dp))
        Column(modifier = Modifier.fillMaxWidth().weight(1f).overflow(Overflow.Auto)) {
            if (isMulti) {
                JsButtonsProfileMultiSelect(itemsState = viewModel.profileMultiSelectList) {
                    viewModel.setSelectMultiItem(it)
                }
            } else {
                JsButtonsAddInfoMultiSelect(
                    viewModel.profileMultiSelectList, Modifier.fillMaxWidth()
                ) { viewModel.setSelectGenderItem(it, isSingleSelect) }
            }
        }
    }
}


@Composable
private fun AddInfoItemsSingle(
    viewModel: ProfileAddInfoVM
) {

    Column(modifier = Modifier.fillMaxSize(), horizontalAlignment = Alignment.CenterHorizontally) {
        viewModel.profileMultiSelectList.forEach {
            SettingsRadioItemJs(
                title = it.itemTitle,
                isSelected = it.onSelected
            ) {
                viewModel.setSelectGenderItem(it, true)
            }
        }
    }
}

@Composable
private fun AddInfoItemsDate(
    viewModel: ProfileAddInfoVM
) {
    val selectorProperties: SelectorProperties = JsPickerDefaults.selectorProperties()
    val rowHeight = 80
    val rowCount = 3


    Box(
        modifier = Modifier.fillMaxSize().overflow(Overflow.Hidden),
        contentAlignment = Alignment.Center
    ) {
        JsDatePicker(
            selectorProperties = selectorProperties,
            itemHeight = rowHeight,
            rowCount = rowCount,
            modifier = Modifier.fillMaxWidth()
                .padding(top = 14.dp, bottom = 14.dp, left = 48.dp, right = 48.dp),
            startDate = viewModel.birthdayDate,
            onDateChanged = { snappedDate ->
                viewModel.selectedDate(snappedDate) {

                }
            }
        )
    }

}

