@Composable
fun JsImageView(
    drawableId: String,
    modifier: Modifier = Modifier,
    format: String = "png",
    contentScale: ContentScale = ContentScale.Crop,
    align: Alignment? = null,
    tintColor: Color? = null,
    width: Int? = null,
    height: Int? = null,
    onImageMeasured: ((Int, Int) -> Unit)? = null
) {
    val objectFit = when (contentScale) {
        ContentScale.Fit -> "contain"
        ContentScale.FillBounds -> "fill"
        ContentScale.FillWidth -> "cover"
        ContentScale.Crop -> "cover"
        ContentScale.None -> "none"
        else -> "none"
    }

    val objectPosition = when (contentScale) {
        ContentScale.FillWidth -> when (align) {
            Alignment.Center -> "center"
            Alignment.BottomCenter -> "bottom center"
            else -> "top center"
        }

        else -> "center"
    }

    if (drawableId.isEmpty()) Box(modifier = modifier)
    else Image(
        src = "images/$drawableId.$format",
        width = width,
        height = height,
        modifier = modifier.styleModifier {
            if (platformType == PlatformType.WebIOS) {
                display(DisplayStyle.Block)
            }
            property("object-fit", objectFit)
            property("object-position", objectPosition)
            property("user-select", "none")
            if (tintColor != null) {
                color(tintColor)
            }
        }.attrsModifier {
            attr("decoding", "sync")
            attr("loading", "eager")

            if (platformType == PlatformType.WebIOS) {
                ref { element ->
                    val img = element as org.w3c.dom.HTMLImageElement

                    val measure: () -> Unit = {
                        //if (img.naturalHeight > 0) {
                        onImageMeasured?.invoke(img.naturalWidth, img.naturalHeight)
                        //}
                    }

                    if (img.complete) measure()

                    val loadListener = { _: org.w3c.dom.events.Event -> measure() }
                    img.addEventListener("load", loadListener)
                    onDispose {
                        img.removeEventListener("load", loadListener)
                    }
                }
            }
        }
    )
}

@Composable
fun JsImageViewTint(
    drawableId: String,
    modifier: Modifier = Modifier,
    format: String = "png",
    contentScale: ContentScale = ContentScale.Crop,
    align: Alignment = Alignment.Center,
    tintColor: Color
) {
    if (drawableId.isEmpty()) {
        Box(modifier = modifier)
        return
    }

    val canvasId = remember { "canvas-${drawableId}" }
    val imageAspectRatio = remember(drawableId) { mutableStateOf(0) }

    Box(modifier) {
        Canvas(
            attrs = Modifier.fillMaxWidth().align(align)
                .thenIf(imageAspectRatio.value != 0, Modifier.aspectRatio(imageAspectRatio.value))
                .styleModifier {
                    property("display", "block") // оставляем только display
                }
                .toAttrs {
                    id(canvasId)
                }
        )
    }

    LaunchedEffect(drawableId, imageAspectRatio.value, tintColor) {
        val canvas = document.getElementById(canvasId) as? HTMLCanvasElement
        if (canvas != null) {
            val ctx = canvas.getContext("2d") as? CanvasRenderingContext2D
            if (ctx != null) {
                val img = document.createElement("img") as HTMLImageElement
                img.crossOrigin = "anonymous"
                img.src = "images/$drawableId.$format"

                img.asDynamic().onload = {
                    val imgW = img.naturalWidth
                    val imgH = img.naturalHeight
                    val imgAspectRatio = imgW / imgH
                    if (imageAspectRatio.value == 0) {
                        imageAspectRatio.value = imgAspectRatio
                    } else {

                        // получаем размеры Canvas из Modifier
                        val rect = canvas.getBoundingClientRect()
                        val imageQualityCorrection = window.devicePixelRatio * 3

                        var w = (rect.width * imageQualityCorrection).toInt()
                        var h = (rect.height * imageQualityCorrection).toInt()

                        // если указана только одна сторона, подстраиваем другую по пропорциям
                        if (w > 0 && h <= 0) h = (w / imgW.toDouble() * imgH).toInt()
                        if (h > 0 && w <= 0) w = (h / imgH.toDouble() * imgW).toInt()
                        w = max(w, 1)
                        h = max(h, 1)

                        canvas.width = w
                        canvas.height = h

                        ctx.clearRect(0.0, 0.0, w.toDouble(), h.toDouble())

                        val (drawW, drawH, offsetX, offsetY) = when (contentScale) {
                            ContentScale.Crop -> {
                                val scale = max(w / imgW.toDouble(), h / imgH.toDouble())
                                val scaledW = imgW * scale
                                val scaledH = imgH * scale
                                val x = (w - scaledW) / 2
                                val y = (h - scaledH) / 2
                                listOf(scaledW, scaledH, x, y)
                            }

                            ContentScale.Fit -> {
                                val scale = min(w / imgW.toDouble(), h / imgH.toDouble())
                                val scaledW = imgW * scale
                                val scaledH = imgH * scale
                                val x = (w - scaledW) / 2
                                val y = (h - scaledH) / 2
                                listOf(scaledW, scaledH, x, y)
                            }

                            ContentScale.FillWidth -> {
                                val scale = w.toDouble() / imgW.toDouble()
                                val scaledW = imgW * scale
                                val scaledH = imgH * scale
                                val x = 0.0
                                val y = when (align) {
                                    Alignment.TopStart, Alignment.TopCenter, Alignment.TopEnd -> 0.0
                                    Alignment.Center, Alignment.CenterStart, Alignment.CenterEnd -> (h - scaledH) / 2.0
                                    else -> (h - scaledH)
                                }.coerceAtLeast(0.0)
                                listOf(scaledW, scaledH, x, y)
                            }

                            ContentScale.FillBounds -> listOf(w.toDouble(), h.toDouble(), 0.0, 0.0)
                            ContentScale.None -> listOf(
                                imgW.toDouble(),
                                imgH.toDouble(),
                                (w - imgW) / 2.0,
                                (h - imgH) / 2.0
                            )

                            else -> listOf(w.toDouble(), h.toDouble(), 0.0, 0.0)
                        }

                        ctx.drawImage(img, offsetX, offsetY, drawW, drawH)

                        ctx.save()
                        //ctx.imageSmoothingEnabled = true
                        //ctx.imageSmoothingQuality = ImageSmoothingQuality.HIGH
                        ctx.globalCompositeOperation = "source-in"
                        ctx.fillStyle = tintColor.toString()
                        ctx.fillRect(0.0, 0.0, w.toDouble(), h.toDouble())
                        ctx.restore()
                    }
                }

                img.asDynamic().onerror = {
                    CommonLogger().log(LogLvl.DEBUG,"JsImageView: failed to load image images/$drawableId.$format")
                }
            }
        } else {
            CommonLogger().log(LogLvl.DEBUG,"JsImageView: canvas is null")
        }
    }
}

@Composable
fun JsImageView(
    drawableRes: DrawableResource?,
    modifier: Modifier = Modifier,
    format: String = "png",
    contentScale: ContentScale = ContentScale.Crop,
    align: Alignment? = null,
    tintColor: Color? = null,
    onImageMeasured: ((Int, Int) -> Unit)? = null
) {
    val drawableId = drawableRes?.getDrawableIdName() ?: ""
    JsImageView(
        drawableId, modifier, format, contentScale, align, tintColor,
        onImageMeasured = onImageMeasured
    )
}


object JsImagePreloaderQueue {

    private var queue = emptyList<String>()
    private var loadedList = mutableListOf<String>()
    private var currentResourceToProcess: String? = null

    fun addToQueue(resource: String) {
        if (resource !in this.queue) {
            val newList = queue + resource
            queue = newList
            if (currentResourceToProcess == null) {
                currentResourceToProcess = newList.firstOrNull()
                preloadResource()
            }
        }
    }

    fun addToQueue(resources: List<String>) {
        val newRes = resources.filter { !queue.contains(it) }
        if (newRes.isNotEmpty()) {
            val newList = queue + newRes
            queue = newList
            if (currentResourceToProcess == null) {
                currentResourceToProcess = newList.firstOrNull()
                preloadResource()
            }
        }
    }

    private fun preloadResource() {
        val activeResource = currentResourceToProcess ?: return
        if (!loadedList.contains(activeResource)) {
            val img = org.w3c.dom.Image()
            val url = "images/$activeResource"
            try {
                img.style.apply {
                    position = "absolute"
                    width = "auto"
                    height = "auto"
                    maxWidth = "256px"
                    maxHeight = "256px"
                    top = "120vh"  // реально “внизу” страницы, но внутри layout
                    opacity = "0"
                }
                img.style.asDynamic().pointerEvents = "none"
                img.style.asDynamic().willChange = "transform"

                img.onload = {
                    completeCurrentPreload(activeResource)
                    CommonLogger().log(
                        LogLvl.DEBUG, "PreloadManager", "Success preload image: $url"
                    )
                }
                img.onerror = { _, _, _, _, _ ->
                    CommonLogger().log(
                        LogLvl.DEBUG, "PreloadManager", "Failed to preload image: $url"
                    )
                    completeCurrentPreload(activeResource)
                }
                img.src = url


                window.document.body?.appendChild(img)

                // Удаляем после первого кадра, когда GPU уже сделала upload
                window.requestAnimationFrame {
                    window.document.body?.removeChild(img)
                }
            } catch (e: Exception) {
                CommonLogger().log(
                    LogLvl.DEBUG, "PreloadManager", "Error preloading image $url: ${e.message}"
                )
                completeCurrentPreload(activeResource)
            }
        } else completeCurrentPreload(activeResource)
    }

    private fun completeCurrentPreload(resource: String) {
        loadedList.add(resource)
        val newList = queue.toMutableList()
        if (newList.firstOrNull() == resource) {
            newList.removeAt(0)
        }
        queue = newList
        currentResourceToProcess = newList.firstOrNull()
        preloadResource()
    }
}

@Composable
fun AsyncAvatarJs(
    avatar: String,
    modifier: Modifier = Modifier,
    placeholderSize: Int = 66,
    onSuccess: @Composable () -> Unit = {},
    onError: @Composable () -> Unit = {}
){
    AsyncImageJs(
        avatar,
        modifier = modifier,
        onLoading = { LoadingState() },
        onSuccess = onSuccess,
        onError = {
            JsImageView(
                drawableRes = ResManager.drawable.ic_color_profile_placeholder,
                Modifier.size(placeholderSize.dp)
            )
            onError.invoke()
        }
    )
}

@Composable
fun AsyncImageJs(
    src: String,
    modifier: Modifier = Modifier,
    contentDescription: String = "",
    onLoading: @Composable () -> Unit = {},
    onError: @Composable () -> Unit = {},
    onSuccess: @Composable () -> Unit = {},
) {
    var loadState by remember(src) { mutableStateOf(ImageLoadStateJs.LOADING) }

    DisposableEffect(src) {
        val img = Image()
        img.src = src

        img.onload = {
            loadState = ImageLoadStateJs.SUCCESS
            null
        }

        img.onerror = { _, _, _, _, _ ->
            loadState = ImageLoadStateJs.ERROR
            null
        }

        onDispose {
            img.onload = null
            img.onerror = null
        }
    }

    when (loadState) {
        ImageLoadStateJs.LOADING -> onLoading()

        ImageLoadStateJs.SUCCESS -> {
            Img(
                src = src,
                alt = contentDescription,
                attrs = modifier
                    .fillMaxSize()
                    .pointerEvents(PointerEvents.None)
                    .toAttrs()
            )
            onSuccess()
        }

        ImageLoadStateJs.ERROR -> onError()
    }
}

enum class ImageLoadStateJs {
    LOADING, SUCCESS, ERROR
}