data class CropRect(val left: Double, val top: Double, val width: Double, val height: Double) {
    val right get() = left + width
    val bottom get() = top + height
}

@Composable
fun CropImageContentJs(
    imageUrl: String,
    zoom: Float,
    rotation: Int,
    onMinZoomCalculated: (Float) -> Unit,
    onCropResult: (String, ByteArray) -> Unit,
    bottomPanelHeight: Double = 60.0,
    shouldCrop: Boolean = false,
    imageTooLarge: () -> Unit,
) {
    // --- State ---
    val containerWidth = remember { mutableStateOf(0.0) }
    val containerHeight = remember { mutableStateOf(0.0) }
    val imageNaturalWidth = remember { mutableStateOf(0.0) }
    val imageNaturalHeight = remember { mutableStateOf(0.0) }
    val isImageLoaded = remember { mutableStateOf(false) }

    // --- Image Loading ---
    DisposableEffect(imageUrl) {
        val img = org.w3c.dom.Image()
        img.crossOrigin = "Anonymous"
        val listener = org.w3c.dom.events.EventListener {
            imageNaturalWidth.value = img.naturalWidth.toDouble()
            imageNaturalHeight.value = img.naturalHeight.toDouble()
            isImageLoaded.value = true
        }
        img.addEventListener("load", listener)
        img.src = imageUrl
        if (img.complete && img.naturalWidth > 0) {
            imageNaturalWidth.value = img.naturalWidth.toDouble()
            imageNaturalHeight.value = img.naturalHeight.toDouble()
            isImageLoaded.value = true
        }
        onDispose { img.removeEventListener("load", listener) }
    }

    // --- Internal State ---
    val offsetX = remember { mutableStateOf(0.0) }
    val offsetY = remember { mutableStateOf(0.0) }
    val isDragging = remember { mutableStateOf(false) }
    val lastDragX = remember { mutableStateOf(0.0) }
    val lastDragY = remember { mutableStateOf(0.0) }

    // --- Crop Rect Calculation ---
    val cropRect = remember(containerWidth.value, containerHeight.value, bottomPanelHeight) {
        val w = containerWidth.value
        val h = containerHeight.value
        if (w == 0.0 || h == 0.0) return@remember null

        val verticalMargin = bottomPanelHeight
        val availableWidth = w
        val availableHeight = h - (verticalMargin * 2)
        if (availableHeight <= 0) return@remember null

        var targetHeight = availableHeight
        var targetWidth = targetHeight / 1.2
        if (targetWidth > availableWidth) {
            targetWidth = availableWidth
            targetHeight = targetWidth * 1.2
        }
        val left = (w - targetWidth) / 2
        val top = (h - targetHeight) / 2
        CropRect(left, top, targetWidth, targetHeight)
    }

    // --- Image Styles ---
    val imageStyles = remember(
        containerWidth.value,
        containerHeight.value,
        imageNaturalWidth.value,
        imageNaturalHeight.value,
        rotation,
        isImageLoaded.value
    ) {
        if (!isImageLoaded.value || containerWidth.value == 0.0 || cropRect == null) return@remember null

        val isRotated = rotation % 180 != 0
        val natW = imageNaturalWidth.value
        val natH = imageNaturalHeight.value

        // Эффективные размеры (если повернуто)
        val effectiveNatWidth = if (isRotated) natH else natW
        val effectiveNatHeight = if (isRotated) natW else natH

        // ИЗМЕНЕНИЕ: Считаем scale так, чтобы картинка СРАЗУ покрывала рамку кропа
        // (Режим Cover относительно cropRect)
        val scaleW = cropRect.width / effectiveNatWidth
        val scaleH = cropRect.height / effectiveNatHeight
        val scale = max(scaleW, scaleH) // Берем MAX, чтобы заполнить без дырок

        val styleWidth = natW * scale
        val styleHeight = natH * scale
        Triple(styleWidth, styleHeight, scale)
    }

    val minZoom = remember(cropRect, imageStyles, rotation) {
        if (cropRect == null || imageStyles == null) return@remember 1f
        val (styleWidth, styleHeight, _) = imageStyles
        val isRotated = rotation % 180 != 0
        val visualWidth = if (isRotated) styleHeight else styleWidth
        val visualHeight = if (isRotated) styleWidth else styleHeight
        val zoomW = cropRect.width / visualWidth
        val zoomH = cropRect.height / visualHeight
        max(zoomW, zoomH).toFloat()
    }

    LaunchedEffect(minZoom, isImageLoaded.value) {
        if (isImageLoaded.value) {
            onMinZoomCalculated(minZoom)
        }
    }

    // --- Clamp Logic ---
    fun clampOffset(
        proposedX: Double,
        proposedY: Double,
        currentZoom: Float
    ): Pair<Double, Double> {
        if (cropRect == null || imageStyles == null) return 0.0 to 0.0
        val (styleWidth, styleHeight, _) = imageStyles
        val isRotated = rotation % 180 != 0
        val visualWidth = (if (isRotated) styleHeight else styleWidth) * currentZoom
        val visualHeight = (if (isRotated) styleWidth else styleHeight) * currentZoom

        // Разрешаем двигать только если картинка больше рамки
        val maxOffsetX = max(0.0, (visualWidth - cropRect.width) / 2)
        val maxOffsetY = max(0.0, (visualHeight - cropRect.height) / 2)

        return proposedX.coerceIn(-maxOffsetX, maxOffsetX) to proposedY.coerceIn(
            -maxOffsetY,
            maxOffsetY
        )
    }

    LaunchedEffect(zoom, rotation, imageStyles, minZoom) {
        val (clampedX, clampedY) = clampOffset(offsetX.value, offsetY.value, zoom)
        if (clampedX != offsetX.value || clampedY != offsetY.value) {
            offsetX.value = clampedX
            offsetY.value = clampedY
        }
    }

    // --- CROP TRIGGER ---
    LaunchedEffect(shouldCrop) {
        try {
            if (shouldCrop && isImageLoaded.value && cropRect != null && imageStyles != null) {
                val (_, _, currentBaseScale) = imageStyles
                val blob = cropImageToBlobUrl(
                    imageUrl = imageUrl,
                    cropRect = cropRect,
                    imageNaturalWidth = imageNaturalWidth.value,
                    imageNaturalHeight = imageNaturalHeight.value,
                    zoom = zoom,
                    rotation = rotation,
                    offsetX = offsetX.value,
                    offsetY = offsetY.value,
                    containerWidth = containerWidth.value,
                    containerHeight = containerHeight.value,
                    baseScale = currentBaseScale
                )
                if (blob != null) {
                    val result = URL.createObjectURL(blob)
                    val resultByteArray = blobToByteArray(blob)
                    onCropResult.invoke(result, resultByteArray)
                } else imageTooLarge.invoke()
            }
        } catch (e: Exception) {
            console.error("Crop failed", e)
            imageTooLarge.invoke()
        }
    }

    // --- Render ---
    Box(
        modifier = Modifier
            .fillMaxSize()
            .position(Position.Relative)
            .overflow(Overflow.Hidden)
            .zIndex(0)
            .cursor(if (isDragging.value) Cursor.Grabbing else Cursor.Grab)
            .userSelect(UserSelect.None)
            .onMouseDown { evt ->
                isDragging.value = true
                lastDragX.value = evt.clientX.toDouble()
                lastDragY.value = evt.clientY.toDouble()
            }
            .onMouseMove { evt ->
                if (isDragging.value) {
                    val dx = evt.clientX.toDouble() - lastDragX.value
                    val dy = evt.clientY.toDouble() - lastDragY.value
                    lastDragX.value = evt.clientX.toDouble()
                    lastDragY.value = evt.clientY.toDouble()
                    val (newX, newY) = clampOffset(offsetX.value + dx, offsetY.value + dy, zoom)
                    offsetX.value = newX
                    offsetY.value = newY
                }
            }
            .onMouseUp { isDragging.value = false }
            .onMouseLeave { isDragging.value = false }
            .onTouchStart { evt ->
                val touch = evt.touches.item(0) ?: return@onTouchStart
                isDragging.value = true
                lastDragX.value = touch.clientX.toDouble()
                lastDragY.value = touch.clientY.toDouble()
            }
            .onTouchMove { evt ->
                if (isDragging.value) {
                    val touch = evt.touches.item(0) ?: return@onTouchMove
                    val dx = touch.clientX.toDouble() - lastDragX.value
                    val dy = touch.clientY.toDouble() - lastDragY.value
                    lastDragX.value = touch.clientX.toDouble()
                    lastDragY.value = touch.clientY.toDouble()
                    val (newX, newY) = clampOffset(offsetX.value + dx, offsetY.value + dy, zoom)
                    offsetX.value = newX
                    offsetY.value = newY
                    evt.preventDefault()
                }
            }
            .onTouchEnd { isDragging.value = false },
        ref = ref { element ->
            val observer = ResizeObserver { entries, _ ->
                entries.firstOrNull()?.contentRect?.let {
                    containerWidth.value = it.width
                    containerHeight.value = it.height
                }
            }
            observer.observe(element)
            object : DisposableEffectResult {
                override fun dispose() {
                    observer.disconnect()
                }
            }
        }
    ) {
        if (isImageLoaded.value && imageStyles != null) {
            val (styleWidth, styleHeight, _) = imageStyles

            Img(
                src = imageUrl,
                attrs = {
                    style {
                        width(styleWidth.px)
                        height(styleHeight.px)
                        position(Position.Absolute)
                        top(0.5f.toPercent())
                        left(0.5f.toPercent())
                        property(
                            "transform",
                            "translate(-50%, -50%) translate(${offsetX.value}px, ${offsetY.value}px) rotate(${rotation}deg) scale($zoom)"
                        )
                        property(
                            "transition",
                            if (isDragging.value) "none" else "transform 0.1s ease-out"
                        )
                        property("user-select", "none")
                        property("-webkit-user-drag", "none")
                        property("z-index", "1")
                    }
                }
            )
        }

        if (cropRect != null && isImageLoaded.value) {
            val tint = JsMainTheme.colors.main_color_black_transparent_30
            val z = 2
            Box(
                Modifier.position(Position.Absolute).zIndex(z).top(0.px).left(0.px)
                    .width(100.percent).height(cropRect.top.px).backgroundColor(tint)
            )
            Box(
                Modifier.position(Position.Absolute).zIndex(z).top(cropRect.bottom.px).left(0.px)
                    .width(100.percent).height((containerHeight.value - cropRect.bottom).px)
                    .backgroundColor(tint)
            )
            Box(
                Modifier.position(Position.Absolute).zIndex(z).top(cropRect.top.px).left(0.px)
                    .width(cropRect.left.px).height(cropRect.height.px).backgroundColor(tint)
            )
            Box(
                Modifier.position(Position.Absolute).zIndex(z).top(cropRect.top.px)
                    .left(cropRect.right.px).width((containerWidth.value - cropRect.right).px)
                    .height(cropRect.height.px).backgroundColor(tint)
            )
            Box(
                Modifier.position(Position.Absolute).zIndex(z).top(cropRect.top.px)
                    .left(cropRect.left.px).width(cropRect.width.px).height(cropRect.height.px)
                    .styleModifier {
                        property("border", "2px solid white"); property(
                        "pointer-events",
                        "none"
                    )
                    })
        }
    }
}

suspend fun cropImageToBlobUrl(
    imageUrl: String,
    cropRect: CropRect,
    imageNaturalWidth: Double,
    imageNaturalHeight: Double,
    zoom: Float,
    rotation: Int,
    offsetX: Double,
    offsetY: Double,
    containerWidth: Double,
    containerHeight: Double,
    baseScale: Double,
): Blob? = suspendCancellableCoroutine { continuation ->
    val img = Image()
    img.crossOrigin = "Anonymous"
    img.src = imageUrl

    img.onload = {
        try {
            val canvas = document.createElement("canvas") as HTMLCanvasElement
            val ctx = canvas.getContext("2d") as CanvasRenderingContext2D

            val pixelRatio = window.devicePixelRatio
            var drawW = (cropRect.width * pixelRatio).toInt()
            var drawH = (cropRect.height * pixelRatio).toInt()

            // ОПТИМИЗАЦИЯ: Если итоговое разрешение гигантское (> 2048),
            // уменьшаем его сразу, чтобы не мучить память
            val maxDimension = 2048
            if (drawW > maxDimension || drawH > maxDimension) {
                val scale = maxDimension.toDouble() / max(drawW, drawH)
                drawW = (drawW * scale).toInt()
                drawH = (drawH * scale).toInt()
            }

            canvas.width = drawW
            canvas.height = drawH
            val scaleX = drawW.toDouble() / cropRect.width
            val scaleY = drawH.toDouble() / cropRect.height
            ctx.scale(scaleX, scaleY)

            // --- ТРАНСФОРМАЦИИ (Ваша логика) ---
            ctx.translate(cropRect.width / 2.0, cropRect.height / 2.0)

            val cropCenterX = cropRect.left + cropRect.width / 2.0
            val cropCenterY = cropRect.top + cropRect.height / 2.0
            val containerCenterX = containerWidth / 2.0
            val containerCenterY = containerHeight / 2.0

            val cropOffsetFromCenterX = cropCenterX - containerCenterX
            val cropOffsetFromCenterY = cropCenterY - containerCenterY

            ctx.translate(offsetX - cropOffsetFromCenterX, offsetY - cropOffsetFromCenterY)
            ctx.rotate(rotation * PI / 180.0)
            ctx.scale(zoom.toDouble(), zoom.toDouble())

            val isRotated = rotation % 180 != 0
            val effectiveNatWidth = if (isRotated) imageNaturalHeight else imageNaturalWidth
            val effectiveNatHeight = if (isRotated) imageNaturalWidth else imageNaturalHeight
            val drawImageW = imageNaturalWidth * baseScale
            val drawImageH = imageNaturalHeight * baseScale

            ctx.drawImage(img, -drawImageW / 2.0, -drawImageH / 2.0, drawImageW, drawImageH)

            fun tryCompress(quality: Double) {
                canvas.toBlob({ blob ->
                    if (blob != null) {
                        val maxSizeBytes = 20 * 1024 * 1024
                        val recommendedSizeBytes = 3 * 1024 * 1024
                        if (blob.size.toLong() > maxSizeBytes) {
                            continuation.resume(null)
                        } else if (blob.size.toLong() <= recommendedSizeBytes || quality <= 0.1) {
                            continuation.resume(blob)
                        } else {
                            tryCompress(quality - 0.1)
                        }
                    } else {
                        continuation.resumeWithException(Exception("Canvas toBlob failed"))
                    }
                }, "image/jpeg", quality)
            }

            // Начинаем с качества 0.9
            tryCompress(0.9)

        } catch (e: Exception) {
            continuation.resumeWithException(e)
        }
    }

    img.onerror = { _, _, _, _, _ ->
        continuation.resumeWithException(Exception("Failed to load image source"))
    }
}

suspend fun blobToByteArray(blob: Blob): ByteArray = suspendCancellableCoroutine { continuation ->
    val reader = FileReader()

    reader.onloadend = {
        val buffer = reader.result as? org.khronos.webgl.ArrayBuffer
        if (buffer != null) {

            val byteArray = Int8Array(buffer).unsafeCast<ByteArray>()
            continuation.resume(byteArray)
        } else {
            continuation.resumeWithException(Exception("Failed to convert Blob to ByteArray"))
        }
    }

    reader.onerror = {
        continuation.resumeWithException(Exception("FileReader failed"))
    }

    reader.readAsArrayBuffer(blob)
}

external class ResizeObserver(callback: (Array<ResizeObserverEntry>, ResizeObserver) -> Unit) {
    fun observe(target: Element)
    fun disconnect()
}

external interface ResizeObserverEntry {
    val contentRect: DOMRectReadOnly
}

external interface DOMRectReadOnly {
    val width: Double
    val height: Double
}