//@Entity
@kotlinx.serialization.Serializable
data class AccountLocation(
    @SerialName("title") var city: String? = null,
    @SerialName("lat") var lat: Double = 0.0,
    @SerialName("lon") var lon: Double = 0.0,
    @SerialName("country") var country: String? = null,
    @SerialName("state") var state: String? = null,
    @SerialName("distance") var distance: Double? = null
)