@Composable
fun JsMainStartScreen(
    obtainEvent: (MainStartScreenEvent) -> Unit,
    viewModel: CommonMainStartViewModel = rememberJsViewModel { CommonMainStartViewModel(obtainEvent) }
) {
    val animationDuration = 300L
    val selectedTab = viewModel.selectedTab.value
    val previousSelectedTab = remember { mutableStateOf(selectedTab) }
    var additionalPage by remember { mutableStateOf<AdditionalPageRoute?>(null) }
    var showProfilePage by remember { mutableStateOf(false) }

    LaunchedEffect(selectedTab) {
        delay(animationDuration + 50)
        previousSelectedTab.value = selectedTab
    }

    Column(modifier = Modifier.fillMaxSize().background(JsMainTheme.colors.main_color_header)) {
        Box(modifier = Modifier.fillMaxSize().styleModifier {
            property("position", "relative")
            property("overflow", "hidden")
        }) {

            // Chat Tab
            if (selectedTab == 0 || previousSelectedTab.value == 0) JsAnimatedVisibility(
                visible = true,
                animationDirection =
                    if (selectedTab == 0 && previousSelectedTab.value == 0) AnimationDirection.NONE
                    else if (previousSelectedTab.value != 0) AnimationDirection.LEFT_TO_RIGHT
                    else AnimationDirection.LEFT_OUT,
                durationMs = animationDuration,
                hiddenDurationMs = 0,
                minOpacity = 0.8f,
                opacityAnimation = AnimationTimingFunction.Linear
            ) { JsChatStartScreen() }


            // People Tab
            if (selectedTab == 1 || previousSelectedTab.value == 1) JsAnimatedVisibility(
                visible = true,
                animationDirection =
                    if (selectedTab == 1 && previousSelectedTab.value == 1) AnimationDirection.NONE
                    else if (previousSelectedTab.value == 0 && selectedTab == 1) AnimationDirection.RIGHT_TO_LEFT
                    else if (previousSelectedTab.value == 2 && selectedTab == 1) AnimationDirection.LEFT_TO_RIGHT
                    else if (previousSelectedTab.value == 1 && selectedTab == 0) AnimationDirection.RIGHT_OUT
                    else AnimationDirection.LEFT_OUT,
                durationMs = animationDuration,
                hiddenDurationMs = 0,
                minOpacity = 0.8f,
                opacityAnimation = AnimationTimingFunction.Linear
            ) { JsPeopleStartScreen(obtainEvent) }


            // Settings Tab
            if (selectedTab == 2 || previousSelectedTab.value == 2) JsAnimatedVisibility(
                visible = true,
                animationDirection =
                    if (selectedTab == 2 && previousSelectedTab.value != 2) AnimationDirection.RIGHT_TO_LEFT
                    else if (selectedTab != 2 && previousSelectedTab.value == 2) AnimationDirection.RIGHT_OUT
                    else AnimationDirection.NONE,
                durationMs = animationDuration,
                hiddenDurationMs = 0,
                minOpacity = 0.8f,
                opacityAnimation = AnimationTimingFunction.Linear,
                modifier = Modifier.fillMaxSize().styleModifier {
                    property("min-height", "0")
                }
            ) {
                JsSettingsScreen { page ->
                    if (page == AdditionalPageRoute.PeopleProfileEdit) showProfilePage = true
                    else additionalPage = page
                }
            }
        }

        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(1.px)
                .background(Color("#424242"))
        )

        KobwebBottomNavigationBar(selectedTab = selectedTab, onTabSelected = { index ->
            viewModel.onTabSelected(index)
        })
    }

    if (showProfilePage) {
        Box(
            modifier = Modifier.fillMaxSize().styleModifier {
                property("position", "relative")
                property("overflow", "hidden")
            }
        ) {
            PeopleProfileEditScreenJs(
                viewModelCallback = { event ->
                    when (event) {
                        PeopleProfileEditEvent.Back -> showProfilePage = false
                        PeopleProfileEditEvent.CropPhoto -> {}
                        PeopleProfileEditEvent.MenuPhotosBottomSheet -> {}
                        is PeopleProfileEditEvent.PeopleProfileAddInfo -> {
                            additionalPage = AdditionalPageRoute.PeopleProfileAddInfo(event.profileData)
                        }
                        PeopleProfileEditEvent.ProfileAddCompatibility -> {}
                        is PeopleProfileEditEvent.ProfileMultiSelect -> {
                            additionalPage = AdditionalPageRoute.PeopleProfileAddInfo(event.profileData)
                        }

                        PeopleProfileEditEvent.ProfilePhotosScreen -> {
                            additionalPage = AdditionalPageRoute.PhotosSelect
                        }
                    }
                }
            )
        }
    }

    additionalPage?.let {
        Box(
            modifier = Modifier.fillMaxSize().styleModifier {
                property("position", "relative")
                property("overflow", "hidden")
            }
        ) {
            JsMainAdditionalScreen(
                page = it,
                obtainEvent = {}
            ) { route ->
                additionalPage = route
            }
        }
    }
}

@Composable
fun KobwebBottomNavigationBar(selectedTab: Int, onTabSelected: (Int) -> Unit) {
    Box(
        modifier = Modifier.fillMaxWidth().height(56.dp)
    ) {
        Row(
            modifier = Modifier.fillMaxWidth().height(56.dp)
                .background(JsMainTheme.colors.main_color_bg_1),
            verticalAlignment = Alignment.CenterVertically
        ) {
            KobwebBottomNavigationItem(
                iconRes = "ic_chat",
                label = Res.string.chat_start_title,
                isSelected = selectedTab == 0,
                onClick = { onTabSelected(0) }
            )
            KobwebBottomNavigationItem(
                iconRes = "ic_people_active",
                label = Res.string.people_start_title,
                isSelected = selectedTab == 1,
                onClick = { onTabSelected(1) }
            )
            KobwebBottomNavigationItem(
                iconRes = "ic_settings",
                label = Res.string.nav_settings_title,
                isSelected = selectedTab == 2,
                onClick = { onTabSelected(2) }
            )
        }
    }
}

@Composable
private fun RowScope.KobwebBottomNavigationItem(
    iconRes: String,
    label: StringResource,
    isSelected: Boolean,
    onClick: () -> Unit
) {
    val itemColor = if (isSelected) Colors.White else Colors.Gray
    Column(
        modifier = Modifier.flexBasis(0.percent).weight(1f).height(56.dp)
            .clickable { onClick() },
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        JsImageViewTint(iconRes, modifier = Modifier.size(24.dp), tintColor = itemColor)
        JsTextView(stringResource(label), 14, textColor = itemColor)
    }
}

@Composable
fun JsSettingsScreen(
    showPage: (AdditionalPageRoute) -> Unit
) {
    SettingsScreenJs(
        initEventCallback = {},
        viewModelCallback = { event ->
            when (event) {
                SettingsRouteEvent.Back -> {}
                SettingsRouteEvent.OnMenuProfileClick -> {}
                is SettingsRouteEvent.PeopleProfile -> {}
                is SettingsRouteEvent.PeopleProfileEdit -> {
                    showPage.invoke(AdditionalPageRoute.PeopleProfileEdit)
                }

                is SettingsRouteEvent.ProfileSelectPhotos -> {
                    showPage.invoke(PhotosSelect)
                }

                SettingsRouteEvent.ProfileShare -> {}
                is SettingsRouteEvent.ProfileVerificationStart -> {}
                SettingsRouteEvent.SettingsAccountPause -> {
                    showPage.invoke(SettingsAccountPause)
                }

                is SettingsRouteEvent.SettingsBlockedUsers -> {
                    showPage.invoke(SettingsBlockedUsers(event.isBlockedUsers))
                }

                SettingsRouteEvent.SettingsCredentials -> {}
                SettingsRouteEvent.SettingsEmail -> {
                    showPage.invoke(SettingsChangeEmail)
                }

                SettingsRouteEvent.SettingsInfo -> {
                    showPage.invoke(SettingsInfo)
                }

                SettingsRouteEvent.SettingsInvisibleMode -> {
                    showPage.invoke(AdditionalPageRoute.SettingsInvisibleMode)
                }

                SettingsRouteEvent.SettingsLanguage -> {
                    showPage.invoke(SettingsLanguage)
                }

                SettingsRouteEvent.SettingsNotifications -> {
                    showPage.invoke(SettingsNotifications)
                }

                SettingsRouteEvent.SettingsPassword -> {
                    showPage.invoke(SettingsChangePassword)
                }

                is SettingsRouteEvent.SettingsWebPage -> {
                    showPage.invoke(
                        AdditionalPageRoute.SettingsWebPage(
                            event.supportUrl,
                            event.title,
                            null
                        )
                    )
                }

                is SettingsRouteEvent.SubscribePage -> {}
            }
        },
    )
}

