package network

import kotpref.logging.CommonLogger
import kotpref.stores.IAppKeysStorage
import kotpref.utils.INotificationManager
import network.restApi.Endpoint
import network.socket.WebSocketManager

class KtorSession(
    val endpoint: Endpoint,
    val userAgent: String,
    val deviceName: String,
    val appKeys: IAppKeysStorage,
    val notificationsUtils: INotificationManager,
    val logger: CommonLogger,
    val os: Int,
    val timeoutTime: Long = 30L,
    val language: () -> String,
    val hasInternetConnection: () -> Boolean
) {


    val ktorClient = KtorClient(userAgent, language, os)
    var webSocketClient: WebSocketManager

    init {
        val okHttpClient = ktorClient.client

        webSocketClient = WebSocketManager(
            okHttpClient, endpoint, appKeys, notificationsUtils, userAgent, deviceName, os
        ) { hasInternetConnection() }
    }

}