enum class PeopleProfileEditInfoType {
    MultiSelect,
    SingleSelect,
    Default,
}

@Composable
fun PeopleProfileEditInfoView(
    viewModel: PeopleProfileEditVM,
    isEdit: Boolean = true
) {
    val scope = rememberCoroutineScope()
    val profileDataConverter = viewModel.profileDataConverter
    val infoItemsList = profileDataConverter.getAboutCategory()
    val months = web.views.datePicker.shortMonthsList()
    Column(
        modifier = Modifier.settingsBgModifierJs(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        repeat(infoItemsList.size) {
            val item = infoItemsList[it]
            val itemType = when (item) {
                ProfileDataField.Name if isEdit -> PeopleProfileEditInfoType.SingleSelect
                ProfileDataField.AboutMe if isEdit -> PeopleProfileEditInfoType.MultiSelect
                else -> PeopleProfileEditInfoType.Default
            }
            val title = stringResource(resource = item.stringRes)
            val content: MutableState<Any> = remember { mutableStateOf("") }
            scope.launch {
                if (item == ProfileDataField.Age) {
                    // Эксперементальная часть получения даты
                    val birthday = viewModel.account.value?.info?.birthday?.substring(0, 10)
                    if (birthday != null) {
                        val date = LocalDate.parse(birthday)
                        content.value =
                            "${date.day} ${months[date.month.number - 1]} ${date.year}"
                    }

                } else
                    content.value = profileDataConverter.getContentData(
                        item, when (itemType) {
                            PeopleProfileEditInfoType.SingleSelect, PeopleProfileEditInfoType.MultiSelect -> isEdit
                            else -> false
                        }
                    )
            }

            when (itemType) {
                PeopleProfileEditInfoType.MultiSelect -> {}
                PeopleProfileEditInfoType.SingleSelect -> {
                    viewModel.nickname.value = content.value.toString()
                    PeopleProfileEditInfoItem(
                        title = title,
                        showArrow = false,
                        showDivider = it + 1 != infoItemsList.size,
                        onClick = {}
                    ) {
                        PeopleProfileEditSingleContent(
                            viewModel.nickname.value,
                            onValueChange = { changeValue ->
                                viewModel.nickname.value = changeValue
                            },
                            onNext = {}
                        )
                    }
                }

                PeopleProfileEditInfoType.Default -> {
                    PeopleProfileEditInfoItem(
                        title = title,
                        isCompatibility = item == ProfileDataField.Compatibility,
                        showArrow = item != ProfileDataField.Iam,
                        showDivider = it + 1 != infoItemsList.size,
                        onClick = {
                            scope.launch {
                                val data = profileDataConverter.getProfileData(item)
                                viewModel.clickedBtn(data)
                            }
                        }
                    ) {
                        PeopleProfileEditDefaultContent(content = content.value)
                    }
                }
            }
        }
    }
}

@Composable
fun PeopleProfileEditInfoItem(
    title: String,
    showArrow: Boolean = true,
    showDivider: Boolean = true,
    isCompatibility: Boolean = false,
    backgroundColor: Color? = null,
    onClick: () -> Unit,
    content: @Composable () -> Unit,
) {
    val modifier = if (backgroundColor != null) Modifier.background(backgroundColor) else Modifier
    Column(modifier.fillMaxWidth().padding(start = 16.dp).styleModifier {
        property("overflow-y", "hidden")
    }) {
        Row(
            modifier = Modifier
                .minHeight(50.dp)
                .padding(end = 16.dp)
                .fillMaxWidth()
                .clickable { onClick.invoke() }
        ) {
            JsAutoResizeText(
                text = title,
                maxTextSize = 18,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
                modifier = Modifier
                    .padding(topBottom = 12.dp)
                    .width(38.percent)
            )

            Spacer(modifier = Modifier.width(16.dp))

            if (isCompatibility) {
                JsImageView(
                    drawableId = "ic_people_compatibility",
                    modifier = Modifier.margin(top = 10.dp, bottom = 10.dp, left = 16.dp)
                        .height(30.dp),
                    tintColor = JsMainTheme.colors.text_color_default
                )
                Spacer(modifier = Modifier.fillMaxWidth())
            } else content.invoke()

            if (showArrow) {
                JsSettingsImageArrow(
                    modifier = Modifier.margin(topBottom = 16.dp)
                )
            }
        }

        if (showDivider) JsDividerLine(modifier = Modifier.fillMaxWidth())
    }
}

@Composable
fun FlowRowInfo(
    genders: List<String>,
    color: Color = JsMainTheme.colors.bg_splash_sign_up_btn
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .padding(top = 8.dp, bottom = 8.dp, right = 16.dp)
            .display(DisplayStyle.Flex)
            .flexWrap(FlexWrap.Wrap)
            .gap(4.px)
    ) {
        genders.forEach {
            GenderItemJs(text = it, color)
        }
    }
}

@Composable
private fun PeopleProfileEditSingleContent(
    value: String,
    onValueChange: (String) -> Unit,
    onNext: () -> Unit
) {
    var isFocused by remember { mutableStateOf(false) }
    Input(
        type = InputType.Text,
        value = value,
        modifier = Modifier.margin(top = 8.dp, bottom = 8.dp, left = 8.dp).fillMaxWidth()
            .styleModifier {
                textAlign("end")
                property("border", "none")
                outline("none")
            }
            .color(JsMainTheme.colors.app_main_color),
        enabled = true,
        focusBorderColor = JsMainTheme.colors.main_color_bg_1,
        onValueChange = onValueChange,
    )
}

@Composable
fun PeopleProfileEditDefaultContent(
    content: Any,
) {
    Box(
        modifier = Modifier.fillMaxWidth()
    ) {
        when (content) {
            is MutableList<*> -> {
                val list: List<String> = content.filterIsInstance<String>()
                FlowRowInfo(list)
            }

            is String if (content != "" && content != "null") -> {
                JsAutoResizeText(
                    text = content,
                    maxTextSize = 14,
                    fontWeight = FontWeight.Medium,
                    modifier = Modifier
                        .padding(end = 16.dp, top = 14.dp, bottom = 14.dp)
                        .fillMaxWidth(),
                    textAlign = TextAlign.End
                )
            }

            else -> {
                JsAutoResizeText(
                    text = stringResource(Res.string.people_profile_edit_hint),
                    maxTextSize = 14,
                    fontWeight = FontWeight.Medium,
                    color = JsMainTheme.colors.text_color_gray_invisible_mode,
                    modifier = Modifier
                        .padding(end = 16.dp, top = 14.dp, bottom = 14.dp)
                        .fillMaxWidth(),
                    textAlign = TextAlign.End
                )
            }
        }
    }
}
