object JsPickerDefaults {
    @Composable
    fun selectorProperties(
        enabled: Boolean = true,
        separatorColor: Color = JsMainTheme.colors.text_color_gray,
    ): SelectorProperties = DefaultSelectorProperties(
        enabled = enabled,
        borderColor = separatorColor,
    )
}

interface SelectorProperties {
    @Composable
    fun enabled(): State<Boolean>

    @Composable
    fun borderColor(): State<Color>

}

@Immutable
internal class DefaultSelectorProperties(
    private val enabled: Boolean,
    private val borderColor: Color,
) : SelectorProperties {

    @Composable
    override fun enabled(): State<Boolean> {
        return rememberUpdatedState(enabled)
    }

    @Composable
    override fun borderColor(): State<Color> {
        return rememberUpdatedState(borderColor)
    }

}

fun calculateSnappedItemIndex(lazyListState: LazyListState): Int {
    val currentItemIndex = lazyListState.firstVisibleItemIndex
    val itemCount = lazyListState.layoutInfo.totalItemsCount
    val offset = lazyListState.firstVisibleItemScrollOffset
    val itemHeight =
        lazyListState.layoutInfo.visibleItemsInfo.firstOrNull()?.size ?: return currentItemIndex

    return if (offset > itemHeight / 2 && currentItemIndex < itemCount - 1) {
        currentItemIndex + 1
    } else {
        currentItemIndex
    }
}

fun Modifier.fadingEdge(brush: Brush) = this
    .graphicsLayer(compositingStrategy = CompositingStrategy.Offscreen)
    .drawWithContent {
        drawContent()
        drawRect(brush = brush, blendMode = BlendMode.DstIn)
    }

@Composable
fun calculateAnimatedAlpha(
    lazyListState: LazyListState,
    index: Int,
    rowCount: Int
): Float {
    val layoutInfo = remember { derivedStateOf { lazyListState.layoutInfo } }.value
    val itemInfo = layoutInfo.visibleItemsInfo.find { it.index == index } ?: return 0.2f

    val viewPortHeight = layoutInfo.viewportSize.height.toFloat()
    val singleViewPortHeight = viewPortHeight / rowCount
    val viewportCenter = layoutInfo.viewportStartOffset + viewPortHeight / 2
    val itemCenter = itemInfo.offset + itemInfo.size / 2
    val distanceToCenter = abs(itemCenter - viewportCenter)

    return if (distanceToCenter <= singleViewPortHeight) {
        1.2f - (distanceToCenter / singleViewPortHeight)
    } else {
        0.2f
    }
}

@Composable
fun topBottomFade() = Brush.verticalGradient(
    0f to MainTheme.colors.main_color_white_transparent_70,
    0.3f to MainTheme.colors.text_color_default,
    0.7f to MainTheme.colors.text_color_default,
    1f to MainTheme.colors.main_color_white_transparent_70
)