@Composable
fun SettingsItemJs(
    title: String,
    icon: String,
    iconTintColor: Color = JsMainTheme.colors.text_color_white,
    itemType: SettingsItemType = SettingsItemType.Default(),
    showDivider: Boolean = true,
    backgroundColor: Color? = null,
    onClick: () -> Unit
) {
    val modifier = if (backgroundColor != null) Modifier.background(backgroundColor) else Modifier
    Column(modifier.fillMaxWidth()) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier
                .minHeight(50.dp)
                .fillMaxWidth()
                .padding( leftRight = 16.dp)
                .clickable { onClick.invoke() }
        ) {
            JsImageViewTint(
                drawableId = icon,
                tintColor = iconTintColor,
                contentScale = ContentScale.Fit,
                modifier = Modifier
                    .size(width = 36.dp, height = 48.dp)
                    .padding(top = 12.dp, bottom = 12.dp)
            )

            Spacer(modifier = Modifier.width(16.dp))

            if (itemType is SettingsItemType.Default && itemType.itemSubsType != 0) {
                val image = when {
                    itemType.itemSubsType <= itemType.currentSubsType -> ResManager.drawable.ic_subscribe_buy_diamond
                    itemType.itemSubsType == 2 -> ResManager.drawable.ic_subscribe_unlimited_diamond
                    else -> ResManager.drawable.ic_subscribe_plus_diamond
                }
                JsImageView(
                    image, modifier = Modifier
                        .height(20.dp)
                        .padding(end = 10.dp)
                )
            }

            JsAutoResizeText(
                text = title,
                maxTextSize = 18,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
                modifier = Modifier
                    .padding(top = 4.dp, end = 8.dp, bottom = 4.dp)
                    .weight(1)
            )

            when (itemType) {
                is SettingsItemType.Default -> JsSettingsImageArrow()

                SettingsItemType.Empty -> {}
                SettingsItemType.Progress -> {
                    Box(
                        modifier = Modifier.padding(
                            end = 24.dp
                        )
                    ) {
                        JsCircularProgressIndicator(
                            Modifier.size(24.dp),
                            color = JsMainTheme.colors.text_color_default
                        )
                    }
                }

                is SettingsItemType.Text -> JsTextView(
                    text = itemType.buttonTitle,
                    textSize = 14,
                    textColor = JsMainTheme.colors.app_main_color,
                    modifier = Modifier
                )
            }
        }

        if (showDivider) JsDividerLine(modifier = Modifier.fillMaxWidth().margin(left = 68.dp))
    }
}

@Composable
fun JsSettingsImageArrow(
    modifier: Modifier = Modifier,
    height: Int = 18,
    tintColor: Color? = null
) {
    JsImageView(
        drawableId = "ic_arrow_right_web",
        tintColor = tintColor ?: JsMainTheme.colors.text_color_white,
        contentScale = ContentScale.Fit,
        modifier = modifier
            .height(height.dp)
    )
}

@Composable
fun JsDefaultSwitch(
    checked: Boolean,
    onCheckedChange: (Boolean) -> Unit,
    modifier: Modifier = Modifier
) {
    Box(
        modifier = modifier
            .size(width = 42.px, height = 24.px)
            .borderRadius(12.px)
            .backgroundColor(
                if (checked) JsMainTheme.colors.app_main_color
                else JsMainTheme.colors.main_color_input_button_bg
            )
            .onClick { onCheckedChange(!checked) }
            .padding(2.px)
    ) {
        Box(
            modifier = Modifier
                .size(20.px)
                .borderRadius(50.percent)
                .backgroundColor(JsMainTheme.colors.text_color_white)
                .align(if (checked) Alignment.CenterEnd else Alignment.CenterStart)
                .transition(
                    Transition.of(
                        property = TransitionProperty.All,
                        duration = 200.ms,
                        timingFunction = TransitionTimingFunction.Ease
                    )
                )
        )
    }
}

@Composable
fun SettingsRadioItemJs(
    title: String,
    isSelected: Boolean,
    onClick: () -> Unit
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .height(48.dp)
            .clickable {
                onClick.invoke()
//                LocaleHelpers.setLocale(context, language)
//                themeEventBus.updateCurrentLocal(language.locale)
            }
    ) {
        Column(
            modifier = Modifier
                .padding(start = 24.dp)
                .fillMaxSize(),
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1)
                    .padding(end = 8.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier.weight(1)
                ) {
                    JsTextView(
                        text = title,
                        textSize = 16,
                        fontWeight = FontWeight.Medium,
                        modifier = Modifier.align(Alignment.CenterStart)
                    )
                }

                DefaultRadioButtonJs(
                    selected = isSelected
                ) {
                    onClick.invoke()
                }
            }

            JsDividerLine()
        }
    }
}

@Composable
fun DefaultRadioButtonJs(
    selected: Boolean,
    selectedColor: Color = JsMainTheme.colors.app_main_color,
    unselectedColor: Color = JsMainTheme.colors.text_color_gray,
    modifier: Modifier = Modifier,
    onClick: (() -> Unit)? = null
) {
    val radioContainerModifier =
        modifier
            .display(DisplayStyle.LegacyInlineFlex)
            .alignItems(AlignItems.Center)
            .justifyContent(JustifyContent.Center)
            .cursor(Cursor.Pointer)


    val borderColor = when {
        selected -> selectedColor
        else -> unselectedColor
    }

    val dotColor = when {
        else -> selectedColor
    }

    Box(
        radioContainerModifier
            .size(20.dp)
            .borderRadius(50.percent)
            .border(2.dp, LineStyle.Solid, borderColor)
            .onClick {
                onClick?.invoke()
            }
    ) {

        if (selected) {
            Box(
                Modifier
                    .size(10.dp)
                    .borderRadius(50.percent)
                    .backgroundColor(dotColor)
            )
        }
    }
}