@Composable
fun JsAlertByType(
    alertType: AlertType,
    dismissOnBackPress: Boolean = false,
    dismissOnClickOutside: Boolean = false,
    withCloseButton: Boolean = false,
    onPositiveClick: () -> Unit = {},
    onNegativeClick: () -> Unit = {},
    onDismiss: () -> Unit,
) {
    val title = stringResource(alertType.getTitleResource())
    val message = stringResource(alertType.getMessageResource())
    val okButtonText = stringResource(alertType.getOkButtonResource())
    val cancelButtonText = stringResource(alertType.getCancelButtonText())
    val withCancelButton = alertType.withCancelButton()
    val showCloseButton = alertType.withCloseButton() ?: withCloseButton
    val dismissClickOutside = alertType.dismissOnClickOutside() ?: dismissOnClickOutside


    @Composable
    fun buttonsRow() {
        val cornerShape = 6
        val buttonHeight = 42.dp

        Box(modifier = Modifier.height(24.dp))
        Row(
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.fillMaxWidth()
        ) {
            if (withCancelButton) {
                var modifier = Modifier.weight(1f).height(buttonHeight).clipByCorner(cornerShape)
                modifier = if (alertType.cancelButtonWithBorder())
                    modifier.border(
                        1.dp, style = LineStyle.Solid, alertType.getJsCancelButtonBackgroundColor()
                    )
                else modifier.background(alertType.getJsCancelButtonBackgroundColor())

                Box(
                    modifier.clickable {
                        onNegativeClick()
                        onDismiss()
                    }, contentAlignment = Alignment.Center
                ) {
                    JsTextView(
                        text = cancelButtonText, 14,
                        textColor = alertType.getJsCancelButtonTextColor(),
                        fontWeight = FontWeight.Bold,
                        modifier = Modifier.padding(leftRight = 6.dp, topBottom = 8.dp),
                        textAlign = TextAlign.Center, maxLines = 1
                    )
                }
                Box(modifier = Modifier.size(8.dp))
            }
            var modifier = Modifier.weight(1f).height(buttonHeight).clipByCorner(cornerShape)
            modifier = if (alertType.okButtonWithBorder())
                modifier.border(
                    1.dp, style = LineStyle.Solid, alertType.getJsOkButtonBackgroundColor()
                )
            else modifier.background(alertType.getJsOkButtonBackgroundColor())
            Box(
                modifier.clickable {
                    onPositiveClick()
                    onDismiss()
                }, contentAlignment = Alignment.Center
            ) {
                JsTextView(
                    text = okButtonText, 14,
                    textColor = alertType.getJsOkButtonTextColor(),
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 8.dp),
                    textAlign = TextAlign.Center, maxLines = 1
                )
            }
        }
    }

    Box(
        modifier = Modifier.fillMaxSize().zIndex(9000)
            .background(JsMainTheme.colors.main_color_black_transparent_70)
            .clickable { if (dismissClickOutside) onDismiss() }
            .padding(horizontal = 32.dp),
        contentAlignment = Alignment.Center
    ) {
        Box {
            val topPadding = if (showCloseButton) 32.dp else 16.dp
            Column(
                modifier = Modifier.clipByCorner(12)
                    .background(JsMainTheme.colors.main_color_bg_1)
                    .onClick { event -> event.stopPropagation() }
                    .padding(start = 16.dp, end = 16.dp, top = topPadding, bottom = 16.dp)
                    .align(Alignment.Center),
                verticalArrangement = Arrangement.Center,
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                if (title.isNotEmpty()) JsTextView(
                    text = title, 16,
                    textColor = JsMainTheme.colors.text_color_default,
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 8.dp)
                )
                if (title.isNotEmpty() && message.isNotEmpty())
                    Spacer(modifier = Modifier.height(10.dp))
                if (message.isNotEmpty()) JsTextView(
                    text = message, 14,
                    textColor = JsMainTheme.colors.text_color_gray,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 8.dp)
                )
                buttonsRow()
            }

            if (showCloseButton) Box(
                Modifier.clickable { onDismiss() }.padding(all = 12.dp).align(Alignment.TopEnd)
            ) {
                JsImageView(
                    Res.drawable.ic_close_white_24dp,
                    tintColor = JsMainTheme.colors.app_main_color,
                    modifier = Modifier.size(16.dp)
                )
            }
        }
    }
}

@Composable
fun AlertType.getJsOkButtonTextColor(): Color = when (this) {
    else -> JsMainTheme.colors.app_main_color
}

@Composable
fun AlertType.getJsOkButtonBackgroundColor(): Color = when (this) {
    else -> JsMainTheme.colors.main_color_background
}

@Composable
fun AlertType.getJsCancelButtonTextColor(): Color = when (this) {
    else -> JsMainTheme.colors.app_main_color
}

@Composable
fun AlertType.getJsCancelButtonBackgroundColor(): Color = when (this) {
    else -> JsMainTheme.colors.main_color_background
}