package ui.managers

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import kotlinx.browser.document
import org.w3c.dom.CanvasRenderingContext2D
import org.w3c.dom.HTMLCanvasElement
import org.w3c.dom.HTMLInputElement
import org.w3c.dom.HTMLVideoElement
import org.w3c.files.FileReader
import kotlin.js.unsafeCast

@Composable
actual fun rememberCameraManager(
    onSuccess: (String) -> Unit,
    onError: () -> Unit
): CameraManager {
    return remember {
        CameraManager {
            try {
                val input = document.getElementById("cam") as HTMLVideoElement
                val canvas = document.createElement("canvas") as HTMLCanvasElement
                canvas.width = input.videoWidth
                canvas.height = input.videoHeight

                val ctx = canvas.getContext("2d")?.unsafeCast<CanvasRenderingContext2D>()
                ctx?.drawImage(input, 0.0, 0.0)
                onSuccess.invoke(canvas.toDataURL("image/jpeg", 0.9))
            } catch (_: Exception) {
                onError.invoke()
            }
        }
    }
}

@Suppress("EXPECT_ACTUAL_CLASSIFIERS_ARE_IN_BETA_WARNING")
actual class CameraManager actual constructor(private val onLaunch: () -> Unit) {
    actual fun launch() {
        onLaunch()
    }
}