data class ScreenSizeInfo(val heightPx: Int, val widthPx: Int)

@JsName("hideLoader")
external fun hideLoader()

@Composable
@Page
fun Index() {
    val vercelConfig = remember { mutableStateOf<VercelConfig?>(null) }
    LaunchedEffect(Unit) {
        delay(1000)
        vercelConfig.value = VercelManager.loadVercelConfig()
    }
    if (vercelConfig.value == null) return

    LaunchedEffect(Unit) {
        delay(1000)
        hideLoader()
    }

    val viewModel: AppScreenVM = rememberJsViewModel { AppScreenVM() }
    val logger = CommonLogger()

    val mixPanelManager by di.instance<MixPanelManager>()
    val paramsCtx = getParamsCtx()
    val mixPanelId = paramsCtx["mixpanel_id"]
    if (mixPanelManager.appKeys.mixPanelUserId.isEmpty() && !mixPanelId.isNullOrEmpty()) {
        mixPanelManager.sendIdentifyId(mixPanelId)
    }

    logger.log(LogLvl.DEBUG, "Index", "paramsCtx = $paramsCtx")

    val screenSize = getJsScreenSizeInfo()
    val width = screenSize.widthPx
    val height = screenSize.heightPx
    val currentScreenAspectRation = width.toDouble() / height
    if (width > 0) {
        logger.log(
            LogLvl.DEBUG, "App",
            "isMobileLayout = ${isMobileLayout}, isMobileDevice = ${isMobileDevice}"
        )
        logger.log(
            LogLvl.DEBUG, "App",
            "screenWidth = ${screenSize.widthPx}, screenHeight = ${screenSize.heightPx}"
        )
        logger.log(
            LogLvl.DEBUG, "App",
            "currentAspectRation = $currentScreenAspectRation, minAspectRation = $minAspectRation"
        )
    }

    val platInfoManager by di.instance<IPlatformInfoManager>()
    platInfoManager.hideStartLoader()
    Box(
        modifier = Modifier.fillMaxSize()
            .background(JsMainTheme.colors.main_color_background),
        contentAlignment = Alignment.BottomCenter
    ) {
        var currentWidthResult: Double
        var currentHeightResult: Double
        if (currentScreenAspectRation > minAspectRation && !isMobileDevice) {
            currentHeightResult = height.toDouble()
            currentWidthResult = (currentHeightResult * minAspectRation)
        } else {
            if (isMobileDevice && width > height) {
                currentWidthResult = height.toDouble()
                currentHeightResult = width.toDouble()
                if (currentWidthResult < minWidth || currentHeightResult < minHeight) {
                    currentWidthResult = minWidth
                    currentHeightResult = minHeight
                }
            } else {
                currentWidthResult = width.toDouble()
                currentHeightResult = height.toDouble()
            }
        }
        if (!isMobileDevice && (currentWidthResult < minWidth || currentHeightResult < minHeight)) {
            currentWidthResult = minWidth
            currentHeightResult = minHeight
        }

        if (AppVariant.isDebug() && (resultWidth.value != currentWidthResult || resultHeight.value != currentHeightResult)) {
            logger.log(
                LogLvl.DEBUG, "App",
                "resultWidth = $currentWidthResult; resultHeight = $currentHeightResult"
            )
        }

        if (resultWidth.value != currentWidthResult) resultWidth.value = currentWidthResult
        if (resultHeight.value != currentHeightResult) resultHeight.value = currentHeightResult

        Box(Modifier.width(resultWidth.value.px).fillMaxHeight().align(Alignment.Center)) {
            Box(modifier = Modifier.fillMaxSize().clipByCorner(0)) {
                ScreenStates(viewModel)
            }
        }

        if (viewModel.showingLoader.value) HideContentLoader()

        LaunchedEffect(resultWidth.value, resultHeight.value) {
            if (viewModel.initPage) {
                viewModel.showingLoader.value = true
                viewModel.loadingDelayExecutor.start()
            }
        }
    }
}

@Composable
private fun ScreenStates(viewModel: AppScreenVM) {
    val uiState by viewModel.getUiState().collectAsState()
    when (uiState) {
        AppNavigationPage.Loading -> Box(Modifier.fillMaxSize()) {
            JsImageView(
                Res.drawable.ic_logo_start_page,
                Modifier.fillMaxWidth(0.4f.toPercent()).align(Alignment.Center)
            )
        }

        AppNavigationPage.StartScreen -> StartPagesNavigation { viewModel.obtainEvent(it) }
        AppNavigationPage.OnboardingScreen -> OnboardingPagesNavigation(viewModel) {
            viewModel.obtainEvent(it)
        }

        AppNavigationPage.MainScreen ->
            if (AppVariant.isStage()) JsMainStartScreen({
                when (it) {
                    MainStartScreenEvent.ClearData -> viewModel.obtainEvent(AppScreenEvent.ShowStartPages)
                    else -> {}
                }
            })
            else DownloadAppScreen() { viewModel.obtainEvent(AppScreenEvent.ShowStartPages) }
    }

    JsShowAlertDialogs(viewModel.showDialogState)
}