    fun createAccountWithFacebook(
        id: String, token: String, nickname: String, email: String?, birthday: String,
        language: String, appVersion: String, recaptchaToken: String?,
        onSuccess: (AccountData?) -> Unit, onError: (String?) -> Unit = {}
    ) {
        val url = "$coreUrl/auth/register/social/facebook"

        val item = AuthorizationSocial(
            id = id, token = token, tokenId = null, email = email, nickname = nickname,
            birthday = birthday, language = language, version = appVersion,
            networkSession.getUserAgent().getUserAgent(), recaptchaToken
        )
        var json = Json.encodeToJsonElement(item).toString()
        if (!json.contains("\"os\":")) {
            json = "{\"os\":${item.os},${json.substring(1, json.length)}"
        }

        ktorClient.postData(
            url, json, responseCallback =
                ResponseCallback(networkSession, onSuccess, onErrorWithMessage = onError)
        )
    }

