    }

    fun loginByEmail(
        email: String, password: String,
        onSuccess: (AccountData?) -> Unit, onError: (String?) -> Unit = {}
    ) {
        loginByProvider(AuthorizationProvider.email.name, email, password, onSuccess, onError)
    }

    fun loginWithFacebook(
        id: String, token: String, showErrorMessage: Boolean,
        onSuccess: (AccountData?) -> Unit, onError: (String?) -> Unit = {}
    ) {
        loginByProvider(AuthorizationProvider.facebook.name, id, token, onSuccess, onError)
    }

    fun loginWithGoogle(
        id: String, token: String, showErrorMessage: Boolean,
        onSuccess: (AccountData?) -> Unit, onError: (String?) -> Unit = {}
    ) {
        loginByProvider(AuthorizationProvider.google.name, id, token, onSuccess, onError)
    }

    private fun loginByProvider(
        provider: String,
        id: String,
        token: String,
        onSuccess: (AccountData?) -> Unit,
        onError: (String?) -> Unit = {}
    ) {
        val url = "$coreUrl/auth/login/$provider"

        val body: Any = if (AuthorizationProvider.email.name == provider) {
            AuthorizationEmailLoginBody(id, token, ktorClient.os)
        } else if (AuthorizationProvider.phone.name == provider) {
            AuthorizationPhoneLoginBody(id, token, ktorClient.os)
        } else AuthorizationLoginBody(id, token, ktorClient.os)

        ktorClient.postData(
            url, body,
            responseCallback = ResponseCallback(
                networkSession, onSuccess, onErrorWithMessage = onError, showErrorMessage = false
            )
        )
    }

