    fun updateAccount(
        account: Account, clearLogin: Boolean = true,
        onSuccess: (AccountSingle?) -> Unit = {}, onError: (String?) -> Unit = {},
        showErrorMessage: Boolean = true
    ) {
        if (clearLogin) account.login = null
        account.email = null
        var json = Json.encodeToJsonElement(account).toString()
        if (!json.contains("\"info\":")) {
            json = "{\"info\":{},${json.substring(1, json.length)}"
        }
        val url = "$coreUrl/profile"
        ktorClient.postData(
            url, json, getToken(), requestType = RequestType.PUT,
            responseCallback = ResponseCallback(
                networkSession, onSuccess, onErrorWithMessage = onError,
                showErrorMessage = showErrorMessage
            )
        )
    }

