    private var updateDeviceInfoWaitingResult = false

    fun updateMyDeviceInfo(
        deviceInfo: JsonObject, batteryLevel: Int, deviceId: String, lon: Double, lat: Double,
        onSuccess: () -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        if (appKeys.userToken.isEmpty() || updateDeviceInfoWaitingResult) return
        updateDeviceInfoWaitingResult = true
        val url = "$coreUrl/profile/devices"
        ktorClient.postData(
            url, DeviceInfoBody(deviceInfo, batteryLevel, deviceId, lon, lat, ktorClient.os),
            getToken(), responseCallback = ResponseCallback(
                networkSession, {
                    updateDeviceInfoWaitingResult = false
                    onSuccess.invoke()
                }, onErrorWithMessage = {
                    updateDeviceInfoWaitingResult = false
                    onError.invoke(it)
                }, showErrorMessage = true
            )
        )
    }

