    fun verificationStart(
        firstFileName: String, secondFileName: String,
        firstFileBytes: ByteArray, secondFileBytes: ByteArray,
        firstPoseId: Int, secondPoseId: Int,
        captchaToken: String?, onSuccess: (Unit?) -> Unit, onError: (String?) -> Unit = {}
    ) {

        val body = formData {
            append("photo_one", firstFileBytes, Headers.build {
                append(HttpHeaders.ContentType, "image/jpeg")
                append(HttpHeaders.ContentDisposition, "filename=${firstFileName}")
            })
            append("photo_two", secondFileBytes, Headers.build {
                append(HttpHeaders.ContentType, "image/jpeg")
                append(HttpHeaders.ContentDisposition, "filename=${secondFileName}")
            })
            append("src_one_id", firstPoseId.toString())
            append("src_two_id", secondPoseId.toString())
            captchaToken?.let { append("recaptcha_token", captchaToken) }
            append("os", "2")
        }
        val url = "$coreUrl/profile/verification"
        ktorClient.multipart(
            url, body, getToken(), responseCallback = ResponseCallback(
                networkSession, onSuccess, onErrorWithMessage = onError, showErrorMessage = false
            )
        )
    }

