    fun loggedError(
        accountId: String, event: ScreenEnum, request: String, response: String, error: String
    ) {
        val userAgent = networkSession.getUserAgent()
        val loggerError = LoggedError(
            accountId, userAgent.appVersion, userAgent.androidVersion, userAgent.build,
            userAgent.deviceName, event.getEventString(), request, response, error,
            env = if (AppVariant.isStage()) "stage" else "prod",
            os = ktorClient.os
        )
        networkSession.getLogger()
            .log(LogLvl.INFO, "", JsonObjectConverter.objectToString(loggerError) ?: "")
    }

    private fun getToken(): String {
        val token = "Bearer ${appKeys.userToken}"
        return token
    }

