package kotpref.models;

import kotpref.utils.TargetAppManager

object WebAppVariant {

    private val FIORRY = "fiorry"
    private val ELIZIUM = "elizium"
    private val HEAVEN = "heaven"
    private val PARADIZ = "paradiz"
    private val STAGE = "stage"
    private val DEBUG = "debug"

    var isStage = false
    var configAppVariant = ""

    private fun getTargetName() = TargetAppManager.getTargetApp()

    fun init() {
        AppVariant.isElizium = { isElizium() }
        AppVariant.isFiorry = { isFiorry() }
        AppVariant.isHeaven = { isHeaven() }
        AppVariant.isParadiz = { isParadiz() }
        AppVariant.isStage = { isDev() }
        AppVariant.isDebug = { isDebug() }
        AppVariant.isReleaseBuild = { !isDebug() }
        AppVariant.isTimeRelease = { isTimeRelease() }
        AppVariant.isAndroid = { false }
        AppVariant.isIos = { false }
        AppVariant.isWeb = { true }

        initSiteHeader()
    }

    fun isElizium(): Boolean = checkTargetName(ELIZIUM)
    fun isFiorry(): Boolean = checkTargetName(FIORRY)
    fun isHeaven(): Boolean = checkTargetName(HEAVEN)
    fun isParadiz(): Boolean = checkTargetName(PARADIZ)

    fun isDev(): Boolean = checkTargetName(STAGE) || isStage
    fun isDebug(): Boolean = checkTargetName(DEBUG)

    fun isTimeRelease(): Boolean = false

    private fun checkTargetName(value: String): Boolean {
        if (configAppVariant.isNotEmpty()) {
            return configAppVariant.contains(value, ignoreCase = true)
        }
        return getTargetName().contains(value, ignoreCase = true)
    }

    private fun initSiteHeader() {
        var documentTitle = ""
        if (AppVariant.isStage()) documentTitle += "Stage "
        documentTitle += if (AppVariant.isFiorry()) "Fiorry"
        else if (AppVariant.isHeaven()) "Heaven"
        else if (AppVariant.isParadiz()) "Paradiz"
        else "Paradiz"
    }
}