class FileRequests(
    private val networkSession: NetworkSession,
    val appKeys: IAppKeysStorage,
    val imageUtils: IImageUtils
) {

    private val endpoint = networkSession.ktorClient().endpoint
    private val ktorClient = networkSession.ktorClient().ktorClient
    private val fileUrl = "${endpoint}/${Endpoint.version}"
    private val moderationUrl = endpoint.moderationUrl()
    //private val fileApi: FileApi
    //private val moderationApi: ModerationApi

    init {
//        fileApi = networkSession.getFileApi()
//        moderationApi = networkSession.getModerationApi()
    }

    var moderatePhotoCalls: MutableList<Job> = mutableListOf()
    var uploadPhotoCalls: MutableList<Job> = mutableListOf()
    var uploadingPhoto = false

    fun uploadPhotoByPath(
        filePath: String,
//        listener: ProgressRequestBody.UploadCallbacks?,
        moderateApiUser: String,
        moderateApiSecret: String,
        onSuccess: (AccountPhotoData?) -> Unit = {},
        onModerateError: (String) -> Unit = {},
        onError: (String?) -> Unit = {}
    ) {
        val file = filePath.replace("file://", "")
        val imageFile = imageUtils.compressFileToByteKMM(file)

        uploadPhoto(
            fileName = imageFile.name,
            fileByteArray = imageFile.bytes,
            moderateApiUser = moderateApiUser,
            moderateApiSecret = moderateApiSecret,
            onSuccess = onSuccess,
            onModerateError = onModerateError,
            onError = onError
        )
    }
    fun uploadPhotoByBlob(
        blob: String,
        fileByteArray: ByteArray,
        moderateApiUser: String,
        moderateApiSecret: String,
        onSuccess: (AccountPhotoData?) -> Unit = {},
        onModerateError: (String) -> Unit = {},
        onError: (String?) -> Unit = {}
    ) {
        val fileName = blob.substringAfterLast("/")

        uploadPhoto(
            fileName = "$fileName.jpg",
            fileByteArray = fileByteArray,
            moderateApiUser = moderateApiUser,
            moderateApiSecret = moderateApiSecret,
            onSuccess = onSuccess,
            onModerateError = onModerateError,
            onError = onError
        )
    }

    private fun uploadPhoto(
        fileName: String, fileByteArray: ByteArray,
        moderateApiUser: String,
        moderateApiSecret: String,
        onSuccess: (AccountPhotoData?) -> Unit = {},
        onModerateError: (String) -> Unit = {},
        onError: (String?) -> Unit = {}
    ) {
        moderatePhoto(fileName, fileByteArray, moderateApiUser, moderateApiSecret, onSuccess = { photo ->
            if (moderatePhotoCalls.size == 0) return@moderatePhoto
            val moderateResult = photo ?: ModeratePhoto()
            if (!correctPhoto(moderateResult)) {
                onModerateError("Not correct by our parameters")
                return@moderatePhoto
            }
            networkSession.getLogger().log(LogLvl.DEBUG, "OkHttp", "uploadPhoto after moderate. fileName = $fileName")

            val body = formData {
                append("photo", fileByteArray, Headers.build {
                    append(HttpHeaders.ContentType, "image/jpeg")
                    append(HttpHeaders.ContentDisposition, "filename=${fileName}")
                })

                append("nudity_score", moderateResult.nudity.raw ?: 0.0)
                append("nudity_partial_score", moderateResult.nudity.partial ?: 0.0)
                append("weapon_score", moderateResult.weapon ?: 0.0)
                append("alcohol_score", moderateResult.alcohol ?: 0.0)
                append("drugs_score", moderateResult.drugs ?: 0.0)
                append("offensive_score", moderateResult.offensive.prob ?: 0.0)
            }

            val job = CoroutineScope(Dispatchers.Default).launch {
                try {
                    val url = "$fileUrl/profile/photos"
                    ktorClient.multipart<AccountPhotoData>(
                        url, body, getToken(), RequestType.POST,
                        ResponseCallback(networkSession, onSuccess = {
                            onSuccess(it)
                            uploadPhotoCalls.removeFirstOrNull()
                            uploadingPhoto = false
                        }, onErrorWithMessage = {
                            onError(it)
                            uploadPhotoCalls.removeFirstOrNull()
                            uploadingPhoto = false
                        })
                    )
                } catch (e: Exception) {
                    onError(e.message)
                    uploadPhotoCalls.removeFirstOrNull()
                    uploadingPhoto = false
                }
            }
            uploadPhotoCalls.add(job)
//            job.start()
        }, onError = { onModerateError("Request error: $it") })
    }

    fun stopUploadPhoto() {
        try {
            moderatePhotoCalls.forEach { it.cancel() }
            uploadPhotoCalls.forEach { it.cancel() }
            moderatePhotoCalls.clear()
            uploadPhotoCalls.clear()
        } catch (_: Exception) {
        }
    }

    fun uploadAvatarByPath(
        filePath: String,
        onSuccess: (AccountSingle?) -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        val file = filePath.replace("file://", "")
        val imageFile = imageUtils.compressFileToByteKMM(file)
        uploadAvatar(imageFile.name, imageFile.bytes, onSuccess, onError)
    }

    fun uploadAvatarByBlob(
        blob: String, fileByteArray: ByteArray,
        onSuccess: (AccountSingle?) -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        val fileName = blob.substringAfterLast("/")
        uploadAvatar("$fileName.jpg", fileByteArray, onSuccess, onError)
    }

    private fun uploadAvatar(
        fileName: String, fileByteArray: ByteArray,
        onSuccess: (AccountSingle?) -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        val body = formData {
            append("avatar", fileByteArray, Headers.build {
                append(HttpHeaders.ContentType, "image/jpeg")
                append(HttpHeaders.ContentDisposition, "filename=${fileName}")
            })
        }

        val url = "$fileUrl/profile/avatar"
        ktorClient.multipart(
            url, body, getToken(), RequestType.PUT,
            ResponseCallback(networkSession, onSuccess, onErrorWithMessage = onError)
        )
    }

    fun deleteAvatar(
        onSuccess: (AccountDataSingle?) -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        val url = "$fileUrl/profile/avatar"
        ktorClient.getOrDeleteInfo(
            url, getToken(), requestType = RequestType.DELETE,
            responseCallback = ResponseCallback(
                networkSession, onSuccess, onErrorWithMessage = onError
            )
        )
        /*val call = { fileApi.deleteAvatar(getToken()) }
        RequestQueue().enqueue(
            call, (ResponseCallback(networkSession, onSuccess, onErrorWithMessage = onError))
        )*/
    }

    fun syncPhotos(
        photos: MutableList<AccountPhoto>,
        onSuccess: (AccountSingle?) -> Unit = {}, onError: (String?) -> Unit = {}
    ) = try {
        val syncSort = mutableListOf<AccountPhotoSort>()
        photos.forEachIndexed { index, it ->
            syncSort.add(AccountPhotoSort(it.id.toInt(), index + 1))
        }

        val url = "$fileUrl/profile/photos"
        ktorClient.postData(
            url, AccountSyncPhotos(syncSort), getToken(), requestType = RequestType.PUT,
            responseCallback = ResponseCallback(
                networkSession, onSuccess, onErrorWithMessage = onError
            )
        )
        /*val call = {
            fileApi.syncPhotoPositions(AccountSyncPhotos(syncSort), token = getToken())
        }
        RequestQueue().enqueue(
            call, (ResponseCallback(networkSession, onSuccess, onErrorWithMessage = onError))
        )*/
    } catch (e: Throwable) {
        onError(e.message)
    }

    fun deletePhoto(
        photoId: String, onSuccess: (Unit?) -> Unit = {}, onError: (String?) -> Unit = {}
    ) {
        val url = "$fileUrl/profile/photos/${photoId}"
        ktorClient.getOrDeleteInfo(
            url, getToken(), requestType = RequestType.DELETE,
            responseCallback = ResponseCallback(
                networkSession, onSuccess, onErrorWithMessage = onError
            )
        )
        /*val call = { fileApi.deletePhoto(photoId, getToken()) }
        RequestQueue().enqueue(
            call, (ResponseCallback(networkSession, onSuccess, onErrorWithMessage = onError))
        )*/
    }

    private fun moderatePhoto(
        fileName: String, fileByteArray: ByteArray,
        moderateApiUser: String,
        moderateApiSecret: String,
        onSuccess: (ModeratePhoto?) -> Unit = {},
        onError: (String?) -> Unit = {}
    ) {
        val body = formData {
            append("media", fileByteArray, Headers.build {
                append(HttpHeaders.ContentType, "multipart/form-data")
                append(HttpHeaders.ContentDisposition, "filename=${fileName}")
            })
            append("api_user", moderateApiUser)
            append("api_secret", moderateApiSecret)
            append("models", "nudity,wad,offensive")
        }

        val job = CoroutineScope(Dispatchers.Default).launch {
            try {
                val url = "$moderationUrl/check.json"
                val data: ModeratePhoto? = ktorClient.multipartWithResult(url, body)
                CommonLogger().log(LogLvl.DEBUG, "moderatePhotoResult", data.toString())
                onSuccess(data)

                moderatePhotoCalls.removeFirstOrNull()
            } catch (e: Exception) {
                onError(e.message)
                moderatePhotoCalls.removeFirstOrNull()
            }
        }
        moderatePhotoCalls.add(job)
    }

    private fun correctPhoto(moderateResult: ModeratePhoto): Boolean = when {
        (moderateResult.nudity.raw ?: 0.0) > 0.7 -> false
        (moderateResult.weapon ?: 0.0) > 0.7 -> false
        (moderateResult.alcohol ?: 0.0) > 0.7 -> false
        (moderateResult.drugs ?: 0.0) > 0.7 -> false
        (moderateResult.offensive.prob ?: 0.0) > 0.7 -> false
        else -> true
    }

    private fun getToken(): String {
        return "Bearer ${appKeys.userToken}"
    }
}