@Composable
internal fun JsMainAdditionalScreen(
    page: AdditionalPageRoute,
    obtainEvent: (AppScreenEvent) -> Unit,
    onBack: (AdditionalPageRoute?) -> Unit,
) {
    when (page) {

        SettingsAccountDelete -> {
            SettingsAccountDeleteScreenJs(
                viewModelCallback = { event ->
                    when (event) {
                        SettingsAccountDeleteEvent.Back -> onBack.invoke(SettingsAccountPause)
                        is SettingsAccountDeleteEvent.ClearLocalData -> {}
                        SettingsAccountDeleteEvent.DeleteRecursively -> {}
                    }
                }
            )
        }

        SettingsAccountPause -> {
            SettingsAccountPauseScreenJs(
                viewModelCallback = { event ->
                    when (event) {
                        SettingsAccountPauseEvent.Back -> onBack.invoke(null)
                        SettingsAccountPauseEvent.SettingsAccountDelete -> {
                            onBack.invoke(SettingsAccountDelete)
                        }

                        is SettingsAccountPauseEvent.SettingsFreeTrial -> {}
                        is SettingsAccountPauseEvent.SubscribeDiscountQuick -> {
                            onBack.invoke(SettingsAccountDelete)
                        }
                    }
                }
            )
        }

        is SettingsBlockedUsers -> {
            SettingsBlockedUsersScreenJs(
                isBlockedUsers = page.isBlockedUsers,
                back = { onBack.invoke(null) }
            )
        }

        SettingsChangeEmail -> {
            SettingsChangeEmailScreenJs(
                viewModelColback = { event ->
                    when (event) {
                        SettingsEmailEvent.Back -> onBack.invoke(null)
                        is SettingsEmailEvent.DialogResetPassword -> {}
                    }
                }
            )
        }

        SettingsChangePassword -> {
            SettingsChangePasswordScreenJs(
                viewModelColback = { event ->
                    when (event) {
                        SettingsPasswordEvent.Back -> onBack.invoke(null)
                    }
                }
            )
        }

        SettingsCredentials -> {

        }

        SettingsInfo -> {
            SettingsInfoScreenJs(
                viewModelCallback = { event ->
                    when (event) {
                        SettingsInfoEvent.Back -> onBack.invoke(null)
                        is SettingsInfoEvent.SettingsWebPage -> {
                            onBack.invoke(
                                SettingsWebPage(
                                    event.endpoint, event.title, SettingsInfo
                                )
                            )
                        }
                    }
                }
            )
        }

        is SettingsInvisibleGender -> {
            SettingsInvisibleGenderScreenJs(
                handleEvent = {},
                profileData = page.profileData,
                viewModelCallback = { event ->
                    when (event) {
                        SettingsInvisibleGenderEvent.Back -> onBack.invoke(SettingsInvisibleMode)
                        SettingsInvisibleGenderEvent.OnBoardingGenderInfo -> {}
                        is SettingsInvisibleGenderEvent.SubscribePage -> {}
                    }
                },
                viewModelEvent = {}
            )
        }

        SettingsInvisibleMode -> {
            SettingsInvisibleModeScreenJs(
                viewModelCallback = { event ->
                    when (event) {
                        SettingsInvisibleModeEvent.Back -> onBack.invoke(null)
                        is SettingsInvisibleModeEvent.SettingsInvisibleGender -> onBack.invoke(
                            SettingsInvisibleGender(profileData = event.profileData)
                        )

                        is SettingsInvisibleModeEvent.SubscribePage -> {}
                    }
                },
                initEventCallback = {}
            )
        }

        SettingsLanguage -> {
            SettingsLanguageScreenJs(onBack = { onBack.invoke(null) })
        }

        SettingsLogin -> {

        }

        SettingsNotifications -> {
            SettingsNotificationsScreenJs(
                viewModelCallback = { event ->
                    when (event) {
                        SettingsNotificationsEvent.Back -> onBack.invoke(null)
                    }
                },
                viewModelEvent = {}
            )
        }

        is SettingsWebPage -> {
            SettingsWebScreenJs(
                title = page.title,
                endpoint = page.url,
                onBack = { onBack.invoke(page.fromPage) },
                callback = {}
            )
        }

        is PhotosSelect -> {
            ProfilePhotosSelectScreenJs(
                fromPage = PhotosFromPage.Settings,
                cropType = CropPhotoType.CROP_PHOTO,
                viewModelCallback = { event ->
                    when (event) {
                        is ProfileSelectPhotosEvent.ClearData -> {}
                        ProfileSelectPhotosEvent.DeleteAvatarEvent -> {}
                        ProfileSelectPhotosEvent.OnBack -> onBack.invoke(null)
                        is ProfileSelectPhotosEvent.PickPhotoManager -> {}
                        is ProfileSelectPhotosEvent.ProfileFaceVerification -> {}
                        is ProfileSelectPhotosEvent.ShowCropPhotoPage -> {}
                        ProfileSelectPhotosEvent.ShowOnBoardingNextPage -> {}
                        ProfileSelectPhotosEvent.ShowProfileVerification -> {}
                        is ProfileSelectPhotosEvent.UpdateAvatarEvent -> {}
                        is ProfileSelectPhotosEvent.UpdateVerificationProfile -> {}
                    }
                }
            )
        }

        AdditionalPageRoute.PeopleProfileEdit -> {
            PeopleProfileEditScreenJs(
                viewModelCallback = { event ->

                }
            )
        }

        is AdditionalPageRoute.PeopleProfileAddInfo -> {
            ProfileAddInfoScreenJs(
                profileData = page.profileData,
                viewModelCallback = { event ->
                    when (event) {
                        ProfileAddInfoEvent.OnBack -> onBack.invoke(null)
                    }
                }
            )
        }
    }
}