@Composable
fun SettingsBlockedUsersScreenJs(
    isBlockedUsers: Boolean,
    back: () -> Unit,
    viewModel: SettingsBlockedUsersVM = rememberJsViewModel {
        SettingsBlockedUsersVM(isBlockedUsers, back)
    }
) {
    val viewState = viewModel.viewStates().collectAsState()
    PageColumnContainer {
        val tabBarTitle = if (viewModel.isBlockedUsers) stringResource(
            resource = Res.string.nav_settings_blocked_title
        ) else stringResource(resource = Res.string.nav_settings_hidden_title)
        JsCustomTabBar(
            onBack = { viewModel.back() },
            tabBarType = TabBars.DefaultTabBar(tabBarTitle)
        )

        Box(
            modifier = Modifier.fillMaxWidth().weight(1)
        ) {
            when (val value = viewState.value) {
                SettingsBlockedUsersVS.EmptyUsers -> {
                    val title =
                        if (viewModel.isBlockedUsers) stringResource(resource = Res.string.nav_settings_blocked_user_empty)
                        else stringResource(resource = Res.string.dialog_hide_profile_empty_placeholder)
                    DefaultEmptyPlaceholderJs(title, "ic_empty_blocked_user")
                }

                SettingsBlockedUsersVS.Loading -> LoadingState()
                is SettingsBlockedUsersVS.WithUsers -> ShowUsersJs(value.accounts, viewModel)
            }
        }
    }
}

@Composable
private fun ShowUsersJs(accounts: List<Account>, viewModel: SettingsBlockedUsersVM) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(topBottom = 8.dp)
            .gap(6.dp)
    ) {
        accounts.forEach { account ->
            key(account.id) {
                UserItemJs(
                    account = account,
                    viewModel = viewModel,
                    modifier = Modifier
                        .transition(
                            Transition.of(
                                property = TransitionProperty.All,
                                duration = 200.ms,
                                timingFunction = TransitionTimingFunction.Ease
                            )
                        )
                ) {
                    viewModel.obtainEvent(
                        SettingsBlockedUsersEvent.UnblockUser(
                            account.id,
                            accounts
                        )
                    )
                }
            }
        }
    }
}

@Composable
private fun UserItemJs(
    account: Account,
    viewModel: SettingsBlockedUsersVM,
    modifier: Modifier = Modifier,
    unblockUser: () -> Unit
) {
    Row(modifier = modifier.fillMaxWidth().height(90.dp)) {
        Box(
            modifier = Modifier.padding(start = 16.dp, top = 12.dp, end = 12.dp)
        ) {
            val avatar = account.avatar
            Box(
                modifier = Modifier.size(66.dp).clipByCorner(33)
            ) {
                AsyncAvatarJs(
                    avatar = avatar ?: ""
                )
            }
        }

        Column(
            modifier = Modifier
                .padding(start = 16.dp).weight(1),
            verticalArrangement = Arrangement.Center
        ) {
            Box(modifier = Modifier.weight(1)) {
                Row(
                    modifier = Modifier.fillMaxSize(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    JsTextView(
                        text = account.nickname
                            ?: stringResource(resource = Res.string.people_start_profile_anonymous),
                        textSize = 16,
                        modifier = Modifier.weight(1),
                        fontWeight = FontWeight.Medium,
                    )

                    val unblockText =
                        if (viewModel.isBlockedUsers) stringResource(resource = Res.string.chat_dialog_unblock)
                        else stringResource(resource = Res.string.dialog_hide_profile_restore)
                    JsTextView(
                        text = unblockText,
                        textSize = 14,
                        modifier = Modifier.padding(16.dp).clickable {
                            unblockUser.invoke()
                        },
                        textColor = JsMainTheme.colors.text_color_application,
                        fontWeight = FontWeight.Medium,
                    )
                }
            }

            Box(
                modifier = Modifier.fillMaxWidth().height(1.dp)
                    .background(JsMainTheme.colors.color_dividing_line)
            )
        }
    }
}