@Composable
fun SettingsInvisibleGenderScreenJs(
    handleEvent: (MutableList<String>) -> Unit,
    profileData: ProfileData,
    viewModelCallback: (SettingsInvisibleGenderEvent) -> Unit,
    viewModelEvent: ((EventVM) -> Unit) -> Unit,
    viewModel: SettingsInvisibleGenderVM = rememberJsViewModel {
        SettingsInvisibleGenderVM(handleEvent, profileData, viewModelCallback, viewModelEvent)
    }
) {

    PageColumnContainer {
        val tabBarType =
            TabBars.TabBarWithRightButton(
                onRightButtonClick = { viewModel.obtainEvent(BaseEventVM.ClickedBtn(true)) },
                rightButtonTitle = stringResource(resource = Res.string.nav_settings_invisible_mode_by_gender_btn_top)
            )
        JsCustomTabBar(
            onBack = { viewModel.obtainEvent(BaseEventVM.ClickBackBtn) },
            tabBarType = tabBarType
        )

        Box(modifier = Modifier.fillMaxWidth().weight(1)) {
            Column(
                modifier = Modifier.fillMaxSize(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Box(modifier = Modifier.fillMaxHeight(5.percent))

                JsTextView(
                    text = stringResource(resource = Res.string.nav_settings_invisible_mode_by_gender_page_title),
                    textSize = 24,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.fillMaxWidth(80.percent),
                    textAlign = TextAlign.Center
                )

                if (AppVariant.isFiorryOrHeaven()) Spacer(modifier = Modifier.height(8.dp))
                Box(
                    modifier = Modifier.fillMaxWidth().weight(1),
                    contentAlignment = if (AppVariant.isEliziumOrParadiz()) Alignment.Center else Alignment.TopCenter
                ) {
                    Column(modifier = Modifier.fillMaxWidth()) {
                        JsButtonsMultiSelect(
                            viewModel.multiSelectListFlow,
                            modifier = Modifier.fillMaxWidth(),
                        ) {
                            viewModel.obtainEvent(SettingsInvisibleGenderEventVM.SetSelectItem(it))
                        }

                        if (AppVariant.isEliziumOrParadiz()) Spacer(
                            modifier = Modifier.fillMaxHeight(
                                40.percent
                            )
                        )
                    }
                }
            }

            if (viewModel.multiSelectListFlow.value.size > 2) {
                Box(
                    modifier = Modifier
                        .padding(start = 16.dp, end = 16.dp, top = 16.dp, bottom = 24.dp)
                        .align(Alignment.BottomEnd)
                        .clickable {
                            viewModel.obtainEvent(SettingsInvisibleGenderEventVM.InfoBtnClick)
                        },
                    contentAlignment = Alignment.Center
                ) {
                    JsImageView(
                        drawableId = "ic_genders_info",
                        modifier = Modifier
                            .size(32.dp)
                    )
                }
            }
        }
        val gradientColors = listOf(
            JsMainTheme.colors.gradient_main_button_start,
            JsMainTheme.colors.gradient_main_button_end
        )
        JsMainButtonCustom(
            text = stringResource(Res.string.nav_settings_save),
            colors = gradientColors,
            arrowIsVisible = true
        ) {
            viewModel.obtainEvent(BaseEventVM.ClickedBtn())
        }
    }
}