@Composable
fun SettingsAccountPauseScreenJs(
    viewModelCallback: (SettingsAccountPauseEvent) -> Unit,
    viewModel: SettingsAccountPauseVM = rememberJsViewModel {
        SettingsAccountPauseVM(viewModelCallback)
    }
) {
    PageColumnContainer {
        val buttonColor =
            if (viewModel.myAccountPause.value) JsMainTheme.colors.main_color_green
            else JsMainTheme.colors.app_main_color
        val backgroundColor =
            if (AppVariant.isEliziumOrParadiz()) JsMainTheme.colors.bg_onboarding
            else JsMainTheme.colors.main_color_background
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(backgroundColor)
                .clipByCorner(0)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxWidth(85.percent)
                    .fillMaxHeight()
                    .align(Alignment.Center),
                verticalArrangement = Arrangement.Center,
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                JsImageView(
                    drawableRes = if (viewModel.myAccountPause.value) FreezeUnfreezeTexts.FREEZE_TEXTS.image else FreezeUnfreezeTexts.UNFREEZE_TEXTS.image,
                    contentScale = ContentScale.FillWidth,
                    modifier = Modifier.fillMaxWidth().padding(top = 24.dp)
                )

                Box(modifier = Modifier.fillMaxWidth().weight(1))

                JsTextView(
                    text = stringResource(resource = if (viewModel.myAccountPause.value) FreezeUnfreezeTexts.FREEZE_TEXTS.title else FreezeUnfreezeTexts.UNFREEZE_TEXTS.title),
                    textSize = 24,
                    modifier = Modifier.margin(top = 16.dp),
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center
                )

                JsTextView(
                    text = stringResource(resource = if (viewModel.myAccountPause.value) FreezeUnfreezeTexts.FREEZE_TEXTS.text else FreezeUnfreezeTexts.UNFREEZE_TEXTS.text),
                    textSize = 14,
                    modifier = Modifier.margin(top = 12.dp),
                    fontWeight = FontWeight.Medium,
                    textColor = JsMainTheme.colors.text_color_gray,
                    textAlign = TextAlign.Center
                )

                Box(modifier = Modifier.fillMaxWidth().weight(1))

                Box(
                    modifier = Modifier
                        .margin(top = 24.dp)
                        .fillMaxWidth(85.percent)
                        .height(50.dp)
                ){
                    SplashFiorryButton(
                        title = stringResource(resource = if (viewModel.myAccountPause.value) FreezeUnfreezeTexts.FREEZE_TEXTS.buttonTitle else FreezeUnfreezeTexts.UNFREEZE_TEXTS.buttonTitle),
                        backgroundColor = buttonColor,
                        backgroundGradientColor = null,
                        buttonWidth = 100
                    ) { viewModel.pauseAccount() }

                    if (viewModel.showButtonProgress.value){
                        LoadingState()
                    }
                }

                DrawLineTextJs(
                    text = stringResource(resource = Res.string.nav_account_pause_delete_btn),
                    modifier = Modifier.margin(top = 16.dp),
                    textSize = 15,
                ){ viewModel.deleteAccount() }

                Box(modifier = Modifier.fillMaxWidth().weight(1))
            }

            JsCustomTabBar(
                onBack = { viewModel.back() },
                withBackground = false,
                tabBarType = TabBars.EmptyTabBar
            )
        }
    }
}