@Composable
fun DialogSettingsAccountMeasurement(
    callback:(Account?) -> Unit,
    onDismiss: () -> Unit,
) {
    val accountRepository by di.instance<AccountRepository>()
    var isMetric by remember { mutableStateOf(false) }
    var onClick by remember { mutableStateOf(false) }
    val account: Account? = null

    LaunchedEffect(Unit) {
        val account = accountRepository.getMyAccount()
        isMetric = account?.measurementUnits != 2
    }

    LaunchedEffect(onClick) {
        when {
            isMetric -> account?.measurementUnits = 2
            else -> account?.measurementUnits = 1
        }
        if (account?.measurementUnits == 2)
            AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.measurementSelectImperial.name)
        else AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.measurementSelectMetrics.name)

        val updateAccount = Account()
        updateAccount.measurementUnits = account?.measurementUnits
        accountRepository.updateAccount(updateAccount, onSuccess = {
            callback.invoke(it)
            onDismiss()
        })
    }

    Box(
        modifier = Modifier.fillMaxSize().zIndex(9000)
            .background(JsMainTheme.colors.main_color_black_transparent_70)
            .clickable {  onDismiss() }
            .padding(horizontal = 32.dp),
        contentAlignment = Alignment.Center
    ) {
        Box(
            modifier = Modifier
                .minWidth(250.dp)
                .background(JsMainTheme.colors.main_color_bg_1)
                .borderRadius(16.dp)
                .border(width = 2.dp, color = JsMainTheme.colors.color_dialog_stroke)
                .boxShadow(
                    blurRadius = 4.dp,
                    spreadRadius = 0.dp,
                    offsetX = 0.dp,
                    offsetY = 2.dp
                )
                .onClick { event -> event.stopPropagation() }
        ) {
            Column(modifier = Modifier.fillMaxWidth()) {
                JsTextView(
                    text = stringResource(Res.string.nav_settings_measurement_title),
                    modifier = Modifier.margin(left = 24.dp, top = 16.dp).padding(right = 24.dp),
                    textSize = 20,
                    fontWeight = FontWeight.Bold
                )

                MeasurementItem(
                    selected = isMetric,
                    text = stringResource(Res.string.nav_settings_measurement_metric),
                    onClick = { isMetric = true }
                )

                MeasurementItem(
                    selected = !isMetric,
                    text = stringResource(Res.string.nav_settings_measurement_imperial),
                    onClick = { isMetric = false }
                )

                Row(
                    modifier = Modifier.align(Alignment.End).margin(top = 8.dp),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    JsTextView(
                        text = stringResource(Res.string.btn_cancel).uppercase(),
                        modifier = Modifier.padding(leftRight = 24.dp, topBottom = 10.dp)
                            .clickable {
                                callback.invoke(null)
                                onDismiss()
                            },
                        textSize = 14,
                        textColor = JsMainTheme.colors.app_main_color,
                        fontWeight = FontWeight.Medium
                    )
                    JsTextView(
                        text = stringResource(Res.string.dialog_btn_ok).uppercase(),
                        modifier = Modifier.padding(leftRight = 24.dp, topBottom = 10.dp).clickable {
                            onClick = true
                        },
                        textSize = 14,
                        textColor = JsMainTheme.colors.app_main_color,
                        fontWeight = FontWeight.Medium
                    )
                }
            }
        }
    }
}

@Composable
private fun MeasurementItem(
    selected: Boolean,
    text: String,
    onClick: () -> Unit,
) {

    Row(
        modifier = Modifier.fillMaxWidth().margin(left = 24.dp).height(48.dp).clickable {
            onClick.invoke()
        },
        verticalAlignment = Alignment.CenterVertically
    ) {
        DefaultRadioButtonJs(
            selected = selected
        )
        JsTextView(
            text = text,
            modifier = Modifier.fillMaxWidth().margin(right = 8.dp).padding(leftRight = 16.dp),
            textSize = 16,
            fontWeight = FontWeight.Normal
        )
    }
}

