package ui.components

import androidx.lifecycle.DefaultLifecycleObserver
import androidx.lifecycle.Lifecycle
import androidx.lifecycle.LifecycleOwner
import androidx.lifecycle.ViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotpref.logging.CommonLogger
import kotpref.logging.LogLvl
import managers.BusEvent
import managers.EventBusManager

abstract class EventsViewModel<State : Any, Event>(initialState: State) :
    StateViewModel<State>(initialState) {

    abstract fun obtainEvent(event: Event)

    override fun onLifecycleEvent(event: Lifecycle.Event) {}
}

abstract class StateViewModel<State : Any>(initialState: State) : DefaultViewModel() {

    private val _uiState = MutableStateFlow(initialState)
    fun getUiState(): StateFlow<State> = _uiState.asStateFlow()

    protected var uiState: State
        get() = _uiState.value
        set(value) {
            if (uiState != value) {
                _uiState.value = value
            } else {
                _uiState.update { value }
            }
        }

    override fun onLifecycleEvent(event: Lifecycle.Event) {}
    override fun onEventBusMessage(event: BusEvent) {}

}

abstract class DefaultViewModel(val initEventBusManager: Boolean = false) : BaseViewModel() {

    init {
        if (initEventBusManager) {
            CommonLogger().log(
                LogLvl.INFO, "EventBusManager", "addObserver init ${className()}"
            )
            EventBusManager.addObserver(className(), ::onEventBusMessage)
        }
    }

    override fun onCleared() {
        if (initEventBusManager) EventBusManager.removeObserver(className())
        super.onCleared()
    }

    abstract fun onLifecycleEvent(event: Lifecycle.Event)
    abstract fun onEventBusMessage(event: BusEvent)

    fun addLifecycleObserver(lifecycle: Lifecycle) {
        val logger = CommonLogger()
        val observer = object : DefaultLifecycleObserver {
            override fun onCreate(owner: LifecycleOwner) {
                val currentClassName = className()
                if (initEventBusManager && currentClassName.isNotEmpty()) {
                    CommonLogger().log(
                        LogLvl.INFO, "EventBusManager", "addObserver $currentClassName"
                    )
                    EventBusManager.addObserver(currentClassName, ::onEventBusMessage)
                }
                logger.log(LogLvl.INFO, "Lifecycle", "onCreate $currentClassName")
                onLifecycleEvent(Lifecycle.Event.ON_CREATE)
            }

            override fun onStart(owner: LifecycleOwner) {
                onLifecycleEvent(Lifecycle.Event.ON_START)
                logger.log(LogLvl.INFO, "Lifecycle", "onStart ${className()}")
            }

            override fun onResume(owner: LifecycleOwner) {
                onLifecycleEvent(Lifecycle.Event.ON_RESUME)
                logger.log(LogLvl.INFO, "Lifecycle", "onResume ${className()}")
            }

            override fun onPause(owner: LifecycleOwner) {
                onLifecycleEvent(Lifecycle.Event.ON_PAUSE)
                logger.log(LogLvl.INFO, "Lifecycle", "onPause ${className()}")
            }

            override fun onStop(owner: LifecycleOwner) {
                onLifecycleEvent(Lifecycle.Event.ON_STOP)
                logger.log(LogLvl.INFO, "Lifecycle", "onStop ${className()}")
            }

            override fun onDestroy(owner: LifecycleOwner) {
                val currentClassName = className()
                if (initEventBusManager && currentClassName.isNotEmpty()) {
                    logger.log(
                        LogLvl.INFO, "EventBusManager", "removeObserver $currentClassName"
                    )
                    EventBusManager.removeObserver(currentClassName)
                }
                onLifecycleEvent(Lifecycle.Event.ON_DESTROY)
                logger.log(LogLvl.INFO, "Lifecycle", "onDestroy $currentClassName")
            }
        }
        lifecycle.addObserver(observer)
    }
}

abstract class BaseViewModel : ViewModel() {
    fun className(): String = this::class.simpleName ?: ""
}
