package web.screens.settings.settingsLanguage

import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import dependencies.RepositoriesProvider
import dependencies.di
import kotpref.models.Languages
import kotpref.models.account.Account
import managers.analytics.AnalyticsManager
import managers.analytics.AnalyticsSettingsEvents
import org.kodein.di.instance
import web.helpers.ActualAppStrings.currentAppLanguageCode


class JsSettingsLanguagesVM(
    val onBack: () -> Unit,
) : ViewModel() {
    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val currentAppLanguage = currentAppLanguageCode.value
    var currentLanguage = mutableStateOf(currentAppLanguage)

    private var clickBackBtn = false

    private fun saveLanguage() {
        val language = Languages.entries.first { it.locale == currentLanguage.value }

        AnalyticsManager.onSendEvent(
            when (language) {
                Languages.ENGLISH -> AnalyticsSettingsEvents.selectEnglishLanguage.name
                Languages.RUSSIAN -> AnalyticsSettingsEvents.selectRussianLanguage.name
                Languages.SPANISH -> AnalyticsSettingsEvents.selectSpanishLanguage.name
                Languages.PORTUGUESE -> AnalyticsSettingsEvents.selectPortugueseLanguage.name
                Languages.GERMAN -> AnalyticsSettingsEvents.selectGermanLanguage.name
                else -> AnalyticsSettingsEvents.selectEnglishLanguage.name
            }
        )
        AnalyticsSettingsEvents.doneLanguage.name
        val updateAccount = Account()
        updateAccount.language = language.locale
        repositoriesProvider.accountRepository.updateAccount(updateAccount)
        onBack.invoke()
    }

    fun changeLanguage(local: String, callback: () -> Unit){
        currentLanguage.value = local
        repositoriesProvider.appKeys.defaultLocale = local
        currentAppLanguageCode.value = local
        callback.invoke()
    }

    fun backBtn() {
        if (clickBackBtn) return
        clickBackBtn = true
        if (currentLanguage.value != currentAppLanguage) saveLanguage()
        else onBack.invoke()
    }
}