enum class LogLvl(val priority: Int) {
    VERBOSE(2),
    DEBUG(3),
    INFO(4),
    WARN(5),
    ERROR(6),
    CRITICAL(7) //ASSERT
}

class CommonLogger {

    fun log(
        logLevel: LogLvl, location: String, message: String = "", exception: Throwable? = null
    ) {
        try {
            printEvent(logLevel, location, message, exception)
        } catch (e: Throwable) {
            printEvent(LogLvl.CRITICAL, "LOGGER", "can't proceed logs due to :", e)
        }
    }

