    private fun enter(log: String): String {
        return if (AppVariant.isReleaseBuild()) ""
        else {
            val maxSpaces = stringLength - log.length
            if (maxSpaces <= 0) return ""
            var bigSpace = "                                        "
            while (bigSpace.length < maxSpaces) {
                bigSpace += bigSpace
            }
            return bigSpace.substring(0, maxSpaces)
        }
    }




    fun logResponse(response: HttpResponse, stringBody: String, logLevel: LogLvl) {
        val code = response.status.value
        val headers = response.request.headers.toMap().toString()
        val url = response.request.url.toString()
        val method = response.request.method.value
        val request = response.request.content as? TextContent
        val requestText = request?.text ?: ""
        printResponse(
            logLevel, method, url, requestText, code, stringBody,
            response.responseTime.timestamp - response.requestTime.timestamp, headers
        )
    }

    private fun printResponse(
        logLevel: LogLvl, method: String, url: String, requestText: String, code: Int,
        stringBody: String, responseTime: Long = 0L, headers: String = ""
    ) {
        log(logLevel, "OkHttp", " \n")
        log(logLevel, "OkHttp", "--> $method (${responseTime}ms) $url")
        if (headers.isNotEmpty()) log(logLevel, "OkHttp", "Headers $headers")
        if (requestText.isNotEmpty()) log(logLevel, "OkHttp", "Body $requestText")
        log(logLevel, "OkHttp", "$code  $stringBody")
        log(logLevel, "OkHttp", "<-- END")
    }
}
