import ui.components.DefaultViewModel
import ui.components.EventVM
import ui.resources.ResManager
import ui.screens.onboarding.paywall.getPriceFormat

sealed class OnBoardingTransTrialEvent : EventVM {
    data object OnBoardingNextPage : OnBoardingTransTrialEvent()
    data object Back : OnBoardingTransTrialEvent()
}

class OnBoardingTransTrialVM(
    val previewMode: Boolean,
    private val viewModelCallback: (OnBoardingTransTrialEvent) -> Unit
) : DefaultViewModel(true) {

    private val repositoriesProvider by di.instance<RepositoriesProvider>()
    private val amplitudeManager by di.instance<AmplitudeManager>()
    val dialogManager by di.instance<IDialogManager>()
    val billingManager by di.instance<IBillingManager>()

    private val accountRepository = repositoriesProvider.accountRepository
    private val appKeys = repositoriesProvider.appKeys

    var stripeProduct: StripeProduct? = null
    val stripeClientSecret = mutableStateOf("")
    val showStripeAppleGoogle = mutableStateOf(false)

    val productId = mutableStateOf("")
    val fullPriceString = mutableStateOf("")
    val priceString = mutableStateOf("")
    val showingProgress = mutableStateOf(false)
    val showingPreloader = mutableStateOf(true)
    var notVisibleForGenders = listOf<AccountIam>()
    var notVisibleGenders = mutableStateOf("")

    init {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingTransTrialPreferenceScreenShown)
        if (!previewMode) loadProductInfo()
        viewModelScope.launch {
            var account = accountRepository.getMyAccount()
            val interestedIn = account?.info?.interestedIn ?: listOf()
            notVisibleForGenders = AccountIam.entries
                .filter { !interestedIn.contains(it.position) }

            var genders = ""
            notVisibleForGenders.forEach { gender ->
                if (!genders.isEmpty()) genders += ", "
                genders += ResManager.getString(gender.secondResId())
            }
            notVisibleGenders.value = genders
            delay(200)
            showingPreloader.value = false
        }
    }

    fun showNextPage() {
        viewModelCallback(OnBoardingTransTrialEvent.OnBoardingNextPage)
    }

    fun clickedBtn() {
        if (previewMode) {
            var notVisibleGenders = ""
            notVisibleForGenders.forEach { gender ->
                if (notVisibleGenders.isNotEmpty()) notVisibleGenders += ","
                notVisibleGenders += "${gender.position}"
            }
            appKeys.trans4TransModeActivatedKey = notVisibleGenders

            showNextPage()
            return
        }
        if (AppVariant.isWeb()) {
            loadStripeClientSecret()
        } else {
            val trialProductId =
                accountRepository.userAdaptyPaywalls.adaptyPaywallConfig?.productIds?.firstOrNull {
                    Billings.isTrialSubscribe(it)
                }
            val billing = Billings.getBillingByProductId(trialProductId)
            if (billing != null) {
                showingProgress.value = true
                billingManager.buyContent(billing, "trans4trans")
            } else {
                showNextPage()
            }
        }
    }

    fun loadProductInfo() {
        val trialProductId =
            accountRepository.userAdaptyPaywalls.adaptyPaywallConfig?.productIds?.firstOrNull {
                Billings.isTrialSubscribe(it)
            }
        if (trialProductId.isNullOrEmpty()) {
            showNextPage()
            return
        }

        fun initProductInfo(productInfo: ProductInfo) {
            productId.value = productInfo.productId
            val price = productInfo.priceAmountMicros / 1000000.0
            val priceCurrentCode = productInfo.priceCurrencyCode
            val priceFormat = getPriceFormat(price)
            fullPriceString.value = "$priceCurrentCode $priceFormat"

            if (
                Billings.isWeekSubscribe(productInfo.productId) ||
                Billings.isMonthSubscribe(productInfo.productId)
            ) {
                priceString.value = "$priceCurrentCode $priceFormat"
            } else if (Billings.is3MonthsSubscribe(productInfo.productId)) {
                val priceFormat = getPriceFormat(price / 3)
                priceString.value = "$priceCurrentCode $priceFormat"
            } else if (Billings.is6MonthsSubscribe(productInfo.productId)) {
                val priceFormat = getPriceFormat(price / 6)
                priceString.value = "$priceCurrentCode $priceFormat"
            } else {
                val priceFormat = getPriceFormat(price / 12)
                priceString.value = "$priceCurrentCode $priceFormat"
            }
        }

        if (AppVariant.isWeb()) {
            billingManager.getAllStripeProducts { products ->
                stripeProduct = products.firstOrNull { it.productId == trialProductId }
                val productInfo = ProductInfo(
                    productId = trialProductId,
                    priceAmountMicros = (stripeProduct?.amount ?: 0).toLong() * 10_000L,
                    priceCurrencyCode = (stripeProduct?.currency ?: "").uppercase()
                )
                initProductInfo(productInfo)
            }
        } else {
            val productInfo = billingManager.getSubscribePrice(trialProductId)
            if (productInfo == null) {
                showNextPage()
                return
            }
            initProductInfo(productInfo)
        }
    }

    fun loadStripeClientSecret() {
        var stripeProduct = stripeProduct ?: return

        fun loadClientSecret() {
            showingProgress.value = true
            viewModelScope.launch {
                accountRepository.loadStripeClientSecret(
                    priceId = stripeProduct.priceId ?: "",
                    productId = stripeProduct.productId,
                    variationId = stripeProduct.variationId,
                    onSuccess = {
                        val clientSecret = it?.data?.clientSecret ?: ""
                        stripeClientSecret.value = clientSecret
                        showStripeAppleGoogle.value = true
                        showingProgress.value = false
                    }, onError = {
                        showingProgress.value = false
                    })
            }
        }

        /*if (AppVariant.isDebug()) {
            billingManager.getAllStripeProducts { products ->
                stripeProduct = products.firstOrNull { Billings.isMonthSubscribe(it.productId ?: "") } ?: stripeProduct
                loadClientSecret()
            }
        } else*/
        loadClientSecret()
    }

    fun boughtSuccess() {
        viewModelScope.launch {
            val myAccount = accountRepository.getMyAccount() ?: Account()
            val subscriptionStatus = myAccount.subscriptionStatus ?: AccountSubscriptionStatus()
            val subscription = subscriptionStatus.subscription ?: AccountSubscription()
            subscription.type = 2
            subscription.productId = "stripe_trial"
            subscriptionStatus.subscription = subscription
            myAccount.subscriptionStatus = subscriptionStatus

            val interestedIn = myAccount.info.interestedIn ?: mutableListOf()
            val notVisibleForGenders = AccountIam.entries.map { it.position }
                .filterNot { it in interestedIn }.toMutableList()

            myAccount.notVisibleForGenders = notVisibleForGenders
            accountRepository.saveMyAccount(myAccount)

            accountRepository.updateAccount(
                myAccount, onSuccess = { EventBusManager.post(InvisibleModeUpdate()) })
            showingProgress.value = false
            showNextPage()
        }

    }

    @UiThread
    fun back() {
        CommonLogger().log(LogLvl.DEBUG, "OnBoardingTransTrialVM", "back")
        viewModelCallback(OnBoardingTransTrialEvent.Back)
    }

    @UiThread
    fun backSystem(): Boolean {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingBackButtonClicked("onboarding_trans_trial_preference_screen"))
        appKeys.onboardingCurrentPage--
        return false
    }

    override fun onLifecycleEvent(event: Lifecycle.Event) {

    }

    override fun onEventBusMessage(event: BusEvent) {
        when (event) {
            is BusEvent.SubscribeSuccess -> boughtSuccess()
            is BusEvent.SubscribeCanceled -> showingProgress.value = false
            else -> {}
        }
    }
}