package kotpref.models.photos

import kotlinx.serialization.SerialName
import kotpref.models.photos.ModerateNudity
import kotpref.models.photos.ModerateOffensive

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-10-02.
 */
@kotlinx.serialization.Serializable
data class ModeratePhoto(
    @SerialName("weapon") var weapon: Double? = 0.0,
    @SerialName("alcohol") var alcohol: Double? = 0.0,
    @SerialName("drugs") var drugs: Double? = 0.0,
    @SerialName("nudity") var nudity: ModerateNudity = ModerateNudity(),
    @SerialName("offensive") var offensive: ModerateOffensive = ModerateOffensive()
)