package web.screens.settings.settingsWebPage

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxSize
import com.varabyte.kobweb.compose.ui.toAttrs
import org.jetbrains.compose.web.dom.Iframe
import ui.views.TabBars
import web.views.JsCustomTabBar
import web.views.PageColumnContainer

@Composable
fun SettingsWebScreenJs(
    title: String,
    endpoint: String,
    onBack: () -> Unit,
    callback: () -> Unit = {}
) {

    PageColumnContainer {
        JsCustomTabBar(
            onBack = { onBack.invoke() },
            tabBarType = TabBars.DefaultTabBar(title)
        )
        Box(
            modifier = Modifier
                .fillMaxSize()
                .weight(1)
        ) {
            Iframe(
                attrs = Modifier
                    .fillMaxSize()
                    .toAttrs {
                        attr("src", endpoint)
                    }
            )
        }
    }
}