sealed class SettingsAccountPauseEvent {
    data class SettingsFreeTrial(val billingType: String, val fromPausePage: Boolean = false) :
        SettingsAccountPauseEvent()

    data class SubscribeDiscountQuick(val fromDeletePage: Boolean): SettingsAccountPauseEvent()
    data object SettingsAccountDelete: SettingsAccountPauseEvent()
    data object Back: SettingsAccountPauseEvent()
}

class SettingsAccountPauseVM(
    val viewModelCallback: (SettingsAccountPauseEvent) -> Unit
) : ViewModel() {
    val billingManager by di.instance<IBillingManager>()
    val repositoriesProvider by di.instance<RepositoriesProvider>()
    private val accountRepository = repositoriesProvider.accountRepository

    val myAccountPause = mutableStateOf(false)

    //    var onPause = false
    private var myAccount: Account? = null
    private var showBanners = { accountRepository.lastSubscribeType == 0 }

    val showButtonProgress = mutableStateOf(false)
    val showProgressContainer = mutableStateOf(false)

    init {
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            myAccount = accountRepository.getMyAccount()
            if (myAccount?.status == 5) myAccountPause.value = true
            showButtonProgress.value = false
            if (showBanners()) EventBusManager.post(AdsInitEvent())
        }
    }

    fun updateDataByResume() {
        showButtonProgress.value = false
    }

    fun pauseAccount() {
        if (showButtonProgress.value) return
        showButtonProgress.value = true
        if (myAccountPause.value) {
            accountRepository.unfreezeMyAccount(onSuccess = {
                AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.reestablishMyAccountSettings.name)
                EventBusManager.post(UnfreezeAccount())
                myAccountPause.value = false
                showButtonProgress.value = false
            }, onError = { showButtonProgress.value = false })
        } else accountRepository.freezeMyAccount(onSuccess = {
            AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.suspendAccount.name)
            EventBusManager.post(FreezeAccount())
            myAccountPause.value = true
            showButtonProgress.value = false
        }, onError = { showButtonProgress.value = false })
    }

    fun deleteAccount() {
        showProgressContainer.value = true
        AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.totallyDelete.name)
        billingManager.getPurchaseDetails(callback = { purchasesResult ->
            val productId = billingManager.getProductId(purchasesResult) ?: ""
            if (productId.isEmpty()) {
                showProgressContainer.value = false
                /*if (AppVariant.isDebug())
                    router.route(Destination.SubscribePropose(OpenProposeFromPage.MainStart.name))
                else*/
                viewModelCallback.invoke(SettingsAccountPauseEvent.SubscribeDiscountQuick(fromDeletePage = true))
            } else showDeletePage()
        })
    }

    private fun showDeletePage(initAdsAgain: Boolean = false) {
        if (initAdsAgain) EventBusManager.post(AdsInitEvent())
        showProgressContainer.value = false
        viewModelCallback.invoke(SettingsAccountPauseEvent.SettingsAccountDelete)
    }

    fun closeAd() {
        EventBusManager.post(AdsInitEvent())
        showProgressContainer.value = false
    }

    private fun checkUsedFreeTrial() {
        billingManager.getPurchaseDetails(callback = { purchasesResult ->
            val productId = billingManager.getProductId(purchasesResult) ?: ""
            if (productId.isEmpty()) {
                viewModelCallback.invoke(SettingsAccountPauseEvent.SettingsFreeTrial(
                    Billings.Plus0Trial3.getSubscribe(),
                    true
                ))
            } else showDeletePage()
        })
    }

    @UiThread
    fun back() {
        viewModelCallback.invoke(SettingsAccountPauseEvent.Back)
    }
}

enum class FreezeUnfreezeTexts(
    val image: DrawableResource,
    val title: StringResource,
    val buttonTitle: StringResource,
    val text: StringResource
) {
    FREEZE_TEXTS(
        image = Res.drawable.ic_settings_play, title = Res.string.suspend_hidden_title,
        buttonTitle = Res.string.suspend_hidden_btn, text = Res.string.suspend_hidden_text
    ),
    UNFREEZE_TEXTS(
        image = Res.drawable.ic_settings_pause, title = Res.string.nav_account_pause_title,
        buttonTitle = Res.string.nav_account_pause_btn, text = Res.string.nav_account_pause_text
    )
}