enum class MainScreenEvent {
    ShowMainPage,
    SettingsEditProfile,
    SettingsChangePassword
}

enum class AppScreenEvent {
    ShowStartPages,
    ShowOnboardingPages,
    ShowMainPages,
}

class AppScreenVM :
    EventsViewModel<AppNavigationPage, AppScreenEvent>(AppNavigationPage.Loading) {

    private val dialogManager: IDialogManager by di.instance()
    private val repositoriesProvider by di.instance<RepositoriesProvider>()
    val appKeys = repositoriesProvider.appKeys

    val className = "AppScreenVM"
    var showDialogState = mutableStateListOf<ShowAlertState>()

    var initPage = false
    val showingLoader = mutableStateOf(false)
    val loadingDelayExecutor =
        DelayedActionExecutor(500, { showingLoader.value = false }, viewModelScope)

    init {
        EventBusManager.addObserver(className, ::onEventBusMessage)
        dialogManager.showDialog = { state ->
            showDialogState.add(state)
        }
        viewModelScope.launch {
            val appKeys = repositoriesProvider.appKeys
            if (appKeys.userRegistered /*|| AppVariant.isLocalSettings()*/) {
                setUiState(AppNavigationPage.MainScreen)
            } else if (appKeys.startOnboarding) {
                setUiState(AppNavigationPage.OnboardingScreen)
            } else {
                setUiState(AppNavigationPage.StartScreen)
            }
            delay(300)
            initPage = true
        }
    }

    private fun setUiState(state: AppNavigationPage) {
        CommonLogger().log(LogLvl.DEBUG, "AppScreenVM", "setUiState = $state")
        uiState = state
        EventBusManager.postEvent(BusEvent.ChangeMainScreenState(state.name))
    }

    override fun obtainEvent(event: AppScreenEvent) {
        when (event) {
            AppScreenEvent.ShowStartPages -> setUiState(AppNavigationPage.StartScreen)
            AppScreenEvent.ShowMainPages -> setUiState(AppNavigationPage.MainScreen)
            AppScreenEvent.ShowOnboardingPages -> setUiState(AppNavigationPage.OnboardingScreen)
        }
    }

    override fun onEventBusMessage(event: BusEvent) {
        when (event) {
            //is BusEvent.Logout -> logout()
            else -> {}
        }
    }
}