package kotpref.models.typeConverter.multi

import kotpref.models.account.enums.AccountInterests
import kotpref.models.account.enums.getString
import org.jetbrains.compose.resources.StringResource


/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-16.
 */
class AccountInterestsConverter {
    companion object {
        fun valuesToList(positions: MutableList<String>?): MutableList<AccountInterests>? {
            if (positions == null) return null
            val list = mutableListOf<AccountInterests>()
            positions.forEach { item ->
                val interest = AccountInterests.showingItems.firstOrNull { it.value == item }
                interest?.let { list.add(interest) }
            }
            return list
        }

        fun valuesToStringList(positions: MutableList<String>?): MutableList<StringResource> {
            if (positions == null) return mutableListOf()
            val list = mutableListOf<StringResource>()
            positions.forEach { item ->
                val interest = AccountInterests.showingItems.firstOrNull { it.value == item }
                interest?.let { list.add(interest.resId()) }
            }
            return list
        }

        suspend fun stringsToValues(list: MutableList<String>?): MutableList<String>? {
            val positions = mutableListOf<String>()
            list?.forEach { item ->
                val interest = AccountInterests.showingItems
                    .firstOrNull { it.resId().getString() == item }?.value
                interest?.let { positions.add(interest) }
            }
            return positions
        }

        fun stringToValues(text: String): MutableList<String> {
            return text.split(", ").toMutableList()
        }

        suspend fun stringToList(text: String?): MutableList<AccountInterests>? {
            return valuesToList(stringsToValues(text?.split(", ")?.toMutableList()))
        }
    }
}