sealed class SettingsAccountDeleteEvent{
    data class ClearLocalData(
        val reason: String, val closeWebSocket: Boolean = true, val startSplashPage: Boolean = true
    ) : SettingsAccountDeleteEvent()

    data object DeleteRecursively: SettingsAccountDeleteEvent()
    data object Back: SettingsAccountDeleteEvent()
}

class SettingsAccountDeleteVM(
    val viewModelCallback: (SettingsAccountDeleteEvent) -> Unit
) : ViewModel() {

    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val dialogManager by di.instance<IDialogManager>()
    val firebaseManager by di.instance<IFirebaseManager>()
    val billingManager by di.instance<IBillingManager>()
    val amplitudeManager by di.instance<AmplitudeManager>()

    private val accountRepository = repositoriesProvider.accountRepository
    private val chatRepository = repositoriesProvider.chatRepository
    val loading = mutableStateOf(false)

    val list = listOf(
        DeleteReason(
            image = ResManager.drawable.ic_navigation_delete_met_someone,
            text = Res.string.nav_account_delete_met_someone,
            reason = 1
        ),
        DeleteReason(
            image = ResManager.drawable.ic_navigation_delete_my_data,
            text = Res.string.nav_account_delete_my_data,
            reason = 2
        ),
        DeleteReason(
            image = ResManager.drawable.ic_navigation_delete_not_like_app,
            text = Res.string.nav_account_delete_not_like,
            reason = 3
        ),
        DeleteReason(
            image = ResManager.drawable.ic_navigation_delete_something_broken,
            text = Res.string.nav_account_delete_something_broken,
            reason = 4
        ),
        DeleteReason(
            image = ResManager.drawable.ic_navigation_delete_offended,
            text = Res.string.nav_account_delete_offended,
            reason = 5
        ),
        DeleteReason(
            image = ResManager.drawable.ic_navigation_delete_other,
            text = Res.string.nav_account_delete_other,
            reason = 6
        )
    )

    fun deleteAccount(reason: Int) {
        viewModelScope.launch(Dispatchers.Main) {
            val withText = reason == 3 || reason == 4 || reason == 6
            val mesType = if (withText) EDialogType.DIALOG_DELETE_ACCOUNT_TEXT
            else EDialogType.DIALOG_DELETE_ACCOUNT
            val title = when (reason) {
                3 -> ResManager.getString(Res.string.nav_account_delete_not_like)
                4 -> ResManager.getString(Res.string.nav_account_delete_something_broken)
                6 -> ResManager.getString(Res.string.nav_account_delete_other)
                else -> ""
            }
            /*dialogManager.showMessage(
                mesType, title, callback = object : ADialogOkCallback() {
                    override fun onDialogOk() {
                        deleteAccountAndClearData(reason)
                    }

                    override fun onDialogOk(result: String) {
                        deleteAccountAndClearData(reason, result)
                    }
                })*/
        }

    }

    private fun deleteAccountAndClearData(reason: Int, message: String? = null) {
        var canClearDate = false
        var showedDeleteError = false
        var showedSuccessMessage = false

        loading.value = true

        fun clearLocalDate() {
            if (showedSuccessMessage) return
            showedSuccessMessage = true
            sendEvent(reason)
            viewModelCallback.invoke(SettingsAccountDeleteEvent.ClearLocalData(
                "delete_acc_by_user", false
            ))
            loading.value = false
            viewModelScope.launch(Dispatchers.Main) {
                delay(500)
                val text = ResManager.getString(Res.string.nav_settings_delete_message)
                dialogManager.showMessageDialog(text)
                viewModelCallback.invoke(SettingsAccountDeleteEvent.DeleteRecursively)
            }
        }

        fun errorDeleteAccount() {
            if (showedDeleteError) return
            viewModelScope.launch(Dispatchers.Main) {
                loading.value = false
                showedDeleteError = true
                val title = ResManager.getString(Res.string.nav_account_delete_error_title)
                val text = ResManager.getString(Res.string.nav_account_delete_error_text)
//                dialogManager.showMessage(EDialogType.DIALOG_WITH_TEXT, title, text)
            }

        }

        fun successDeleteAccount() {
            firebaseManager.unsubscribeTopic()
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val account = accountRepository.getMyAccount()
                sendDeleteLog(account)
                val messageWithReason =
                    "reason = ${if (reason == 0) 99 else reason}${if (!message.isNullOrEmpty()) "; message = $message" else ""}"
                accountRepository.deleteAccount(messageWithReason, onSuccess = {
                    amplitudeManager.sendEvent(
                        AmplitudeEvent.UserDeleteAccount(
                            account?.accountId, account?.uuid, account?.profileId,
                            "delete_screen", 6, messageWithReason
                        )
                    )

                    if (canClearDate) clearLocalDate()
                    else canClearDate = true
                }, reason = 6, onError = { errorDeleteAccount() })
            }
        }
        chatRepository.deleteAccount(
            onSuccess = {
                chatRepository.closeWebSocket()
                if (canClearDate) clearLocalDate() else canClearDate = true
            }, onError = { errorDeleteAccount() }
        )
        successDeleteAccount()
    }

    private fun sendDeleteLog(account: Account?) {
        val authProvider = account?.login ?: ""
        val email = account?.email ?: ""
        val message = "auth_provider_id = $authProvider; email = $email"
        accountRepository.loggedError(ScreenEnum.DeleteAccountSettings, message)
    }

    private fun sendEvent(reason: Int) {
        when (reason) {
            1 -> AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.deleteAccountMetSomeOne.name)
            2 -> AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.deleteAccountDeleteMyData.name)
            3 -> AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.deleteAccountDontLikeApp.name)
            4 -> AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.deleteAccountSomethingBroken.name)
            5 -> AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.deleteAccountWasOffended.name)
            6 -> AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.deleteAccountOther.name)
        }
    }

    @UiThread
    fun back() {
        viewModelCallback.invoke(SettingsAccountDeleteEvent.Back)
    }

    fun systemBack(): Boolean {
        AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.deleteAccountCancel.name)
        return false
    }
}

data class DeleteReason(val image: DrawableResource, val text: StringResource, val reason: Int)

@Composable
fun navAccountDeleteText() = when {
    AppVariant.isHeaven() -> stringResource(resource = Res.string.nav_account_delete_text_heaven)
    AppVariant.isElizium() -> stringResource(resource = Res.string.nav_account_delete_text_elizium)
    AppVariant.isParadiz() -> stringResource(resource = Res.string.nav_account_delete_text_paradiz)
    else -> stringResource(resource = Res.string.nav_account_delete_text)
}