@Composable
fun JsPeopleStartScreen(
    obtainEvent: (MainStartScreenEvent) -> Unit,
    viewModel: ComposePeopleStartVM = rememberJsViewModel { ComposePeopleStartVM() }
) {
    val repositoriesProvider by di.instance<RepositoriesProvider>()
    val accountRepository = repositoriesProvider.accountRepository
    val scope = rememberCoroutineScope()

    fun deleteAccount() {
        scope.launch(Dispatchers.Main) { /* runBlocking */
            BillingManager.productDetailsList.clear()
            accountRepository.deleteAccount(onSuccess = {
                scope.launch(Dispatchers.Main) {
                    repositoriesProvider.database.clearDatabase()
                    val appKeys = repositoriesProvider.appKeys
                    appKeys.userBirthday = 0L
                    appKeys.startOnboarding = false
                    appKeys.userRegistered = false
                    appKeys.onboardingCurrentPage = 0
                    appKeys.webRegisterPassword = ""
                    obtainEvent(MainStartScreenEvent.ClearData)
                }
            }, onError = {
                obtainEvent(MainStartScreenEvent.ClearData)
            }, reason = 1)
        }
    }

    Box(modifier = Modifier.fillMaxSize()) {
        Column(modifier = Modifier.fillMaxSize()) {
            Box(
                modifier = Modifier.fillMaxWidth().height(56.dp)
                    .background(JsMainTheme.colors.main_color_header)
            ) {
                Row(
                    modifier = Modifier.fillMaxSize(), // appBarContent
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row( // RadioGroup
                        modifier = Modifier
                            .margin(left = 8.dp)
                            .height(36.dp)
                            .padding(start = 2.dp, end = 2.dp)
                            .background(JsMainTheme.colors.top_bar_switch_background)
                            .clipByCorner(16)
                            .align(Alignment.CenterVertically),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        JsImageView(
                            if (viewModel.peopleSwipeContainerVisible.value) "ic_people_type_swipes" else "ic_people_type_swipes_unselect",
                            modifier = Modifier.size(32.dp)
                                .clickable { viewModel.changePeopleContainer() }
                        )

                        Spacer(Modifier.size(4.dp))

                        JsImageView(
                            if (viewModel.peopleContainerVisible.value) "ic_people_type_default" else "ic_people_type_default_unselect",
                            modifier = Modifier.size(32.dp)
                                .clickable { viewModel.changePeopleContainer() }
                        )
                    }

                    JsTextView(
                        text = stringResource(Res.string.people_start_title),
                        20,
                        textColor = JsMainTheme.colors.text_color_default,
                        modifier = Modifier
                            .padding(start = 16.dp, end = 16.dp, bottom = 2.dp)
                            .align(Alignment.CenterVertically)
                    )

                    Box(Modifier.weight(1f))

                    Row(
                        modifier = Modifier.height(56.dp)
                            .align(Alignment.CenterVertically)
                    ) {
                        Box( // peopleSearchItem
                            modifier = Modifier
                                .width(40.dp)
                                .height(56.dp)
                                .padding(top = 8.dp, bottom = 8.dp)
                                .clickable { viewModel.showSearchPage() },
                            contentAlignment = Alignment.Center
                        ) {
                            if (viewModel.peopleSearchBgVisible.value) Box(
                                modifier = Modifier.size(34.dp).align(Alignment.Center)
                                    .background(JsMainTheme.colors.radio_button_background)
                                    .clipByCorner()
                            )
                            JsImageView(
                                "ic_people_search",
                                modifier = Modifier.size(24.dp)
                            )
                        }

                        Box( // peopleCompatibilityItem
                            modifier = Modifier
                                .width(40.dp)
                                .height(56.dp)
                                .padding(top = 8.dp, bottom = 8.dp)
                                .clickable { viewModel.showCompatibilityPage() }
                        ) {
                            if (viewModel.peopleCompatibilityBgVisible.value) Box(
                                modifier = Modifier.size(34.dp).align(Alignment.Center)
                                    .background(JsMainTheme.colors.radio_button_background)
                                    .clipByCorner()
                            )
                            JsImageView(
                                "ic_people_compatibility",
                                modifier = Modifier.size(24.dp).align(Alignment.Center)
                            )
                        }

                        Box( // peopleFilterItem
                            modifier = Modifier
                                .width(40.dp)
                                .height(56.dp)
                                .padding(top = 8.dp, bottom = 8.dp, end = 4.dp)
                                .clickable { viewModel.showFilters() }
                        ) {
                            if (viewModel.peopleFilterBgVisible.value) Box(
                                modifier = Modifier.size(34.dp).align(Alignment.Center)
                                    .background(JsMainTheme.colors.radio_button_background)
                                    .clipByCorner()
                            )
                            JsImageView(
                                "ic_filter",
                                modifier = Modifier.size(24.dp).align(Alignment.Center)
                            )
                        }
                    }
                }
                Box(
                    modifier = Modifier.fillMaxWidth().height(1.dp)
                        .background(JsMainTheme.colors.main_color_background)
                        .align(Alignment.BottomCenter)
                )
            }

            Box(modifier = Modifier.fillMaxWidth().weight(1f)) {
                // SwipeRefreshLayout (placeholder)
                if (viewModel.peopleContainerVisible.value) Column(modifier = Modifier.fillMaxSize()) {
                    if (viewModel.peopleItemsVisible.value) Box(modifier = Modifier.fillMaxSize()) {
                        JsTextView(
                            "RecyclerView Placeholder",
                            14,
                            modifier = Modifier.align(Alignment.Center)
                        )
                    }
                }

                if (viewModel.peopleSwipeContainerVisible.value) Box( // peopleSwipeContainer
                    modifier = Modifier.fillMaxSize()
                        .background(JsMainTheme.colors.main_color_background)
                ) {
                    // SwipeRefreshLayout (placeholder)
                    Column(modifier = Modifier.fillMaxSize()) {
                        // ComposeView swipeContainer
                        Box(modifier = Modifier.fillMaxSize()) {
                            JsTextView(
                                "Swipe Container ComposeView Placeholder",
                                14,
                                modifier = Modifier.align(Alignment.Center)
                            )
                        }
                    }
                }

                if (viewModel.emptyContainerVisible.value) Column( // emptyContainer
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(top = 2.dp, bottom = 0.dp)
                        .padding(bottom = 0.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    // ImageView emptyContainerImage
                    JsImageView(
                        "", // Placeholder for @drawable/ic_no_people_found
                        modifier = Modifier
                            .fillMaxWidth(50.percent)
                            .padding(bottom = 16.dp)
                    )

                    JsTextView(
                        text = stringResource(Res.string.people_start_empty_text),
                        18,
                        textColor = JsMainTheme.colors.text_color_hint,
                        modifier = Modifier
                            .fillMaxWidth(85.percent)
                            .padding(top = 16.dp)
                    )

                    Box( // emptyContainerBtn
                        modifier = Modifier
                            .fillMaxWidth(70.percent)
                            .height(50.dp)
                            .background(Color("#FFC107")) // bg_subscribe_plus_buy_btn placeholder
                            .clickable { viewModel.clickEmptyBtn() }
                            .padding(top = 16.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        JsTextView(
                            text = stringResource(Res.string.people_start_empty_btn),
                            16,
                            textColor = JsMainTheme.colors.text_color_white
                        )
                    }
                }

                if (viewModel.peopleContainerVisible.value) Column( // compatibilityProgressContainer
                    modifier = Modifier.fillMaxSize(),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.Center
                ) {
                    // LottieAnimationView (placeholder)
                    Box(
                        modifier = Modifier
                            .fillMaxWidth(60.percent)
                            .height(0.dp)
                            .aspectRatio(1f)
                    ) {
                        JsTextView(
                            "LottieAnimationView Placeholder",
                            14,
                            modifier = Modifier.align(Alignment.Center)
                        )
                    }
                    JsTextView(
                        text = stringResource(Res.string.people_start_compatibility_loading_title),
                        22,
                        modifier = Modifier
                            .fillMaxWidth(80.percent)
                            .padding(top = 8.dp),
                        textColor = JsMainTheme.colors.text_color_default
                    )
                    JsTextView(
                        text = stringResource(Res.string.people_start_compatibility_loading_text),
                        14,
                        modifier = Modifier
                            .fillMaxWidth(80.percent)
                            .padding(top = 8.dp),
                        textColor = JsMainTheme.colors.text_color_default
                    )
                }

                // ComposeView defaultBlockContainer (placeholder)
                if (viewModel.defaultBlockContainerVisible.value) Box(modifier = Modifier.fillMaxSize()) {
                    JsTextView(
                        "ComposeView Placeholder",
                        14,
                        modifier = Modifier.align(Alignment.Center)
                    )
                }

                if (viewModel.dialogWowMutualContainerVisible.value) Box( // dialog_wow_mutual_container
                    modifier = Modifier.fillMaxSize()
                ) {
                    // Include item_dialog_wow_mutual (placeholder)
                    JsTextView(
                        "Dialog Wow Mutual Placeholder",
                        14,
                        modifier = Modifier.align(Alignment.Center)
                    )
                }
            }

            if (viewModel.paginationProgressContainerVisible.value) Box( // paginationProgressContainer
                modifier = Modifier
                    .fillMaxWidth()
                    .height(50.dp) // Assuming a height for ProgressBar
                    .background(Color("#1A000000")) // bg_people_item_gradient - placeholder for gradient
                    .padding(4.dp),
                contentAlignment = Alignment.Center
            ) {
                // ProgressBar (placeholder)
                Box(
                    modifier = Modifier.size(24.dp)
                        .background(JsMainTheme.colors.text_color_white)
                ) // Placeholder for ProgressBar
            }

            if (viewModel.verificationContainerVisible.value) Box( // verificationContainer
                modifier = Modifier
                    .fillMaxWidth()
                    .height(26.dp)
                    .background(JsMainTheme.colors.main_color_verification_in_progress) // tools:background
                    .clickable { viewModel.onVerificationProfileClick() },
                contentAlignment = Alignment.Center
            ) {
                JsTextView(
                    text = stringResource(Res.string.verification_status_in_progress),
                    14,
                    modifier = Modifier.fillMaxWidth().padding(bottom = 2.dp),
                    textColor = JsMainTheme.colors.text_color_default,
                    textAlign = TextAlign.Center
                )
            }
        }

        if (AppVariant.isDebug()) {
            Box(
                contentAlignment = Alignment.CenterStart,
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(top = (56 + 16).dp)
                    .height(56.dp)
                    .clickable { deleteAccount() }
            ) {
                JsTextView(
                    stringResource(resource = Res.string.dialog_btn_delete), textSize = 15,
                    textColor = JsMainTheme.colors.app_main_color,
                    fontWeight = FontWeight.Normal,
                    modifier = Modifier.padding(all = 16.dp).fillMaxHeight()
                )
            }
        }

        if (viewModel.hiddenContainerVisible.value) Box( // hiddenContainer
            modifier = Modifier.fillMaxSize().zIndex(4)
        ) {
            JsTextView(
                "Suspend Hidden Content Placeholder",
                14,
                modifier = Modifier.align(Alignment.Center)
            )
        }

        if (viewModel.dialogContainerVisible.value) Box(
            modifier = Modifier.fillMaxSize()
                .clickable { /* This makes it clickable and focusable, but doesn't handle actual click behavior yet */ }
        ) {
            JsPeopleFilterPrompt(viewModel) // Calling the included layout as a Composable
        }
    }
}

