@Composable
fun JsSubscribeDiscountMain(
    productDetails: List<ProductDetails>,
    enjoyedByText: String,
    weekPrice: Double,
    paywallButtonsStyle: Int,
    showOtherProduct: () -> Unit,
    isReview: Boolean,
    isWeekFormat: Boolean,
    annual12MonthsText: Boolean,
    cancelAnytimeNewStyle: Boolean,
    callback: (Int) -> Unit = {}
) {

    val productDetail =
        /*if (AppVariant.isTestBuild()) productDetails.last() else*/
        productDetails.firstOrNull() ?: return

    val period: SubscriptionPeriod =
        Billings.getPeriodByProductId(productDetail.productDetails.productId)

    val periodTitle = JsSubscribeHelper.periodTitle(period, annual12MonthsText = annual12MonthsText)

    val textPrices = getTextPriceCompose(
        productDetails = productDetail.productDetails,
        discountDetails = productDetail.discountDetails,
        period = period,
        weekPrice = weekPrice,
        isWeekFormat = isWeekFormat
    )

    val lastTextPrice = textPrices.textPricePeriod
    val lastTextPriceByPeriod =
        if (isReview) "$lastTextPrice / $periodTitle"
        else "${textPrices.textPriceForWeek} ${
            stringResource(
                if (isWeekFormat) Res.string.subscribe_settings_weekly_text
                else Res.string.subscribe_settings_month_text
            ).lowercase()
        }"

    val percentDiscount = textPrices.textPercentDiscount
    val percentDiscountTextRes = stringResource(Res.string.onboarding_propose_subscription_discount)
    val percentDiscountText = "-$percentDiscount% $percentDiscountTextRes"

    val textPrice =
        if (percentDiscount.isNotEmpty()) textPrices.textPriceDiscountPeriod else lastTextPrice

    val onlyText = stringResource(Res.string.onboarding_propose_subscription_only)
    val onlyPrice = textPrices.textDefaultPricePeriod

    val accountRepository by di.instance<AccountRepository>()
    val isShowBilledAnnually =
        accountRepository.userAdaptyPaywalls.adaptyPaywallConfig?.isShowBilledAnnually() ?: true

    val textPriceByPeriod =
        if (isReview) "$textPrice / $periodTitle" else onlyPrice
    val onlyTextPricePeriod =
        if (isReview) "$onlyText $onlyPrice" else stringResource(Res.string.paywall_subscribe_billed_annually)

    Column(
        modifier = Modifier.fillMaxWidth().onSizeChanged { _, _ -> callback(productDetails.size) },
        horizontalAlignment = Alignment.CenterHorizontally
    ) {

        if (percentDiscount.isNotEmpty()) {
            Row(
                modifier = Modifier.fillMaxWidth(0.9f.toPercent()),
                horizontalArrangement = Arrangement.spacedBy(
                    16.dp, Alignment.CenterHorizontally
                )
            ) {
                Box(
                    modifier = Modifier
                        .height(32.dp)
                        .clipByCorner(16)
                        .border(
                            1.dp, style = LineStyle.Solid,
                            color = JsMainTheme.colors.main_color_white_transparent_70.copy(0.5f)
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    JsTextView(
                        text = lastTextPriceByPeriod.uppercase(),
                        modifier = Modifier.padding(horizontal = 16.dp),
                        textColor = JsMainTheme.colors.text_color_gray,
                        textSize = 14,
                        fontWeight = FontWeight.Normal,
                        textDecoration = TextDecorationLine.LineThrough,
                    )
                }

                Box(
                    modifier = Modifier
                        .height(32.dp)
                        .clipByCorner(16)
                        .border(
                            1.dp, style = LineStyle.Solid,
                            JsMainTheme.colors.main_color_white_transparent_70.copy(0.5f),
                        ),
                    contentAlignment = Alignment.Center
                ) {
                    JsAutoResizeText(
                        text = percentDiscountText.uppercase(),
                        modifier = Modifier.padding(horizontal = 16.dp),
                        color = JsMainTheme.colors.subscribe_propose_new_design_settings,
                        maxTextSize = 14,
                        fontWeight = FontWeight.Normal,
                        textAlign = TextAlign.Center,
                        maxLines = 1
                    )
                }
            }
            Spacer(modifier = Modifier.height(8.dp))
        }


        JsTextView(
            text = textPriceByPeriod,
            textColor = JsMainTheme.colors.text_color_default,
            textSize = 24,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )

        if (isReview || isShowBilledAnnually)
            JsTextView(
                text = onlyTextPricePeriod,
                textColor = JsMainTheme.colors.main_color_white_transparent_70.copy(0.4f),
                textSize = 14,
                fontWeight = FontWeight.Normal,
                textAlign = TextAlign.Center
            )
        Spacer(modifier = Modifier.height(32.dp))


        if (productDetails.size > 1) {
            JsTextView(
                text = stringResource(Res.string.onboarding_propose_subscription_view_other_plans),
                modifier = Modifier
                    .clickable { showOtherProduct.invoke() },
                textColor = JsMainTheme.colors.text_color_default,
                textSize = 12,
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center
            )
            Spacer(modifier = Modifier.height(16.dp))
        }

        if (paywallButtonsStyle != 4) {
            if (paywallButtonsStyle != 3) {
                Box(
                    modifier = Modifier.fillMaxWidth(0.85f.toPercent()),
                    contentAlignment = Alignment.Center
                ) {
                    if (cancelAnytimeNewStyle) {
                        Row(
                            Modifier.padding(vertical = 4.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            JsImageView(
                                Res.drawable.ic_subscribe_cancel_anytime,
                                tintColor = Color.rgb(0xA660EB),
                                modifier = Modifier.size(22.dp)
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            JsTextView(
                                stringResource(Res.string.onboarding_propose_subscription_cancel_anytime_new_style_stripe),
                                14,
                                textColor = Color.rgb(0xA660EB),
                                textAlign = TextAlign.Center
                            )
                            Spacer(modifier = Modifier.width(6.dp))
                            Spacer(modifier = Modifier.size(22.dp))
                        }
                    } else Box(
                        modifier = Modifier
                            .height(36.dp)
                            .clipByCorner(20)
                            .border(
                                1.dp, style = LineStyle.Solid,
                                JsMainTheme.colors.text_color_white,
                            ),
                        contentAlignment = Alignment.Center
                    ) {
                        Row(
                            Modifier
                                .fillMaxHeight()
                                .padding(horizontal = 16.dp),
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            JsImageView(
                                "ic_subscribe_cancel_anytime_web",
                                modifier = Modifier.size(20.dp)
                            )
                            JsTextView(
                                text = stringResource(Res.string.onboarding_propose_subscription_cancel_anytime_stripe),
                                modifier = Modifier.padding(start = 8.dp),
                                textColor = JsMainTheme.colors.text_color_white,
                                textSize = 12,
                                fontWeight = FontWeight.Normal,
                                textAlign = TextAlign.Center
                            )
                        }
                    }
                }
            }

            if (paywallButtonsStyle != 2) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 16.dp),
                    horizontalArrangement = Arrangement.spacedBy(
                        2.dp,
                        Alignment.CenterHorizontally
                    )
                ) {
                    repeat(5) {
                        JsImageView(
                            Res.drawable.ic_subscribe_star,
                            modifier = Modifier.size(20.dp),
                            contentScale = ContentScale.Crop
                        )
                    }
                }

                JsTextView(
                    text = enjoyedByText,
                    modifier = Modifier.padding(top = 2.dp),
                    textColor = JsMainTheme.colors.main_color_white_transparent_70,
                    textSize = 12,
                    fontWeight = FontWeight.Medium
                )
            }
        }
    }
}
