package web.views

import androidx.compose.runtime.Composable
import com.varabyte.kobweb.compose.foundation.layout.Arrangement
import com.varabyte.kobweb.compose.foundation.layout.Column
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxHeight
import com.varabyte.kobweb.compose.ui.modifiers.fillMaxSize
import com.varabyte.kobweb.compose.ui.modifiers.padding
import org.jetbrains.compose.web.css.percent
import web.helpers.dp

@Composable
fun DefaultEmptyPlaceholderJs(
    title: String, image: String
) {
    Column(modifier = Modifier.fillMaxSize(),
        verticalArrangement = Arrangement.Center,
        horizontalAlignment = Alignment.CenterHorizontally){
        Spacer(modifier = Modifier.weight(0.45))
        JsImageView(
            drawableId = image,
            modifier = Modifier.fillMaxHeight(20.percent)
        )
        SubtitleTextJs(title, modifier = Modifier.padding(top = 16.dp))
        Spacer(modifier = Modifier.weight(0.55))
    }
}