@Composable
fun SettingsChangeEmailScreenJs(
    viewModelColback: (SettingsEmailEvent) -> Unit,
    viewModel: SettingsEmailVM = rememberJsViewModel {
        SettingsEmailVM(viewModelColback)
    }
) {
    val tabBarType = TabBars.EmptyTabBar

    PageColumnContainer {
        JsCustomTabBar(
            onBack = { viewModel.back() },
            withBackground = false,
            tabBarType = tabBarType
        )

        Box(modifier = Modifier.fillMaxWidth().weight(1)) {
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Spacer(modifier = Modifier.height(24.dp))
                JsTextView(
                    text = stringResource(Res.string.nav_settings_credentials_change_email),
                    textSize = 24,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier,
                    textAlign = TextAlign.Center
                )
                Spacer(modifier = Modifier.height(24.dp))

                JsOutlinedTextField(
                    value = viewModel.emailValue.value.text,
                    textSize = 14,
                    textMinHeight = 50,
                    label = stringResource(Res.string.auth_text_hint_email),
                    isError = viewModel.emailError.value.isNotEmpty(),
                    errorText = viewModel.emailError.value,
                    modifier = Modifier.fillMaxWidth(80.percent)
                        .onFocusIn { viewModel.emailError.value = "" },
                    onValueChange = {
                        viewModel.emailValue.value = TextFieldValue(it)
                    }
                )

                if (viewModel.showPassword.value){
                    Spacer(modifier = Modifier.height(12.dp))
                    OutlinedPasswordFieldItemJs(
                        passwordValue = viewModel.passwordValue.value,
                        label = stringResource(Res.string.nav_settings_password_current_title),
                        errorText = viewModel.passwordError.value,
                        errorCallback = { viewModel.passwordError.value = "" },
                        onValueChange = { viewModel.passwordValue.value = it }
                    )

                    Spacer(modifier = Modifier.height(8.dp))
                    Row(
                        modifier = Modifier
                    ){
                        JsTextView(
                            text = stringResource(Res.string.nav_settings_credentials_change_email),
                            textSize = 14,
                            textColor = JsMainTheme.colors.app_main_color,
                            fontWeight = FontWeight.Medium,
                            modifier = Modifier.padding(top = 8.dp, bottom = 8.dp, left = 16.dp, right = 16.dp),
                            textAlign = TextAlign.Center
                        )
                        Spacer(modifier = Modifier.width(16.dp))
                    }
                }
            }

            if (viewModel.showProgress.value) LoadingState()
        }
        val gradientColors = listOf(
            JsMainTheme.colors.gradient_main_button_start,
            JsMainTheme.colors.gradient_main_button_end
        )
        JsMainButtonCustom(
            text = stringResource(Res.string.onboarding_location_btn),
            colors = gradientColors,
            arrowIsVisible = true,
            alpha = viewModel.alpha,
            onClick = { if ( viewModel.enabled)  viewModel.changeEmail() }
        )
    }
}