@Composable
fun JsSubscribeBoxButton(
    modifier: Modifier,
    productDetails: PurchaseInfo,
    discountDetails: PurchaseInfo?,
    selectedProductID: MutableState<String>,
    discountOnlyForPopularProduct: Boolean,
    isPopular: Boolean,
    startPrice: Double,
    btnProgress: MutableState<Boolean>,
    isReview: Boolean,
    isWeekFormat: Boolean,
    annual12MonthsText: Boolean,
    isPlus: Boolean,
    isBottomDrawerFragment: Boolean,
    textPeriodSize: MutableState<Int>,
    onClick: () -> Unit,
) {
    val period: SubscriptionPeriod = Billings.getPeriodByProductId(productDetails.productId)

    val onSelected =
        selectedProductID.value == productDetails.productId || selectedProductID.value == discountDetails?.productId
    val periodTitle = JsSubscribeHelper.periodTitle(period, isReview, annual12MonthsText)

    val textPrices = getTextPriceComposeNew(
        productDetails = productDetails,
        discountDetails = discountDetails,
        period = period,
        startPrice = startPrice,
        isWeekFormat = isWeekFormat
    )

    val price =
        if (isReview) textPrices.textPriceDiscountPeriod.ifEmpty { textPrices.textPricePeriod }
        else textPrices.textDefaultPriceWeek

    val pricePerWeek = if (isReview) textPrices.textDefaultPricePeriod else {
        if (isWeekFormat) stringResource(Res.string.subscribe_settings_weekly_text).lowercase()
        else stringResource(Res.string.subscribe_settings_month_text).lowercase()
    }

    Box(
        modifier = modifier
            .padding(horizontal = 2.dp)
            .fillMaxSize()
            .clickable { onClick.invoke() }
    ) {
        val borderWidth = if (onSelected) 3.dp else 3.dp
        val colors = if (onSelected) {
            if (isPlus) listOf(
                JsMainTheme.colors.gradient_subscribe_plus_color_start,
                JsMainTheme.colors.gradient_subscribe_plus_color_end
            ) else listOf(
                JsMainTheme.colors.gradient_subscribe_unlim_color_start,
                JsMainTheme.colors.gradient_subscribe_unlim_color_end
            )
        } else listOf(
            JsMainTheme.colors.box_paywall_subscribe_button_gray.copy(alpha = 0.9f),
            JsMainTheme.colors.box_paywall_subscribe_button_gray.copy(alpha = 0.9f)
        )
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(top = 12.dp, bottom = 8.dp)
        ) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .clipByCorner(10)
                    .gradientBackground(colors)
                    .padding(all = borderWidth)
            ) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .clipByCorner(10)
                        .background(
                            if (isBottomDrawerFragment) JsMainTheme.colors.box_subscribe_propose_backgraund_gray
                            else JsMainTheme.colors.main_color_background
                        )
                ) {
                    Column(
                        modifier = Modifier.fillMaxSize(),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center
                    ) {
                        Spacer(modifier = Modifier.height(24.dp))
                        if (isReview) Box(modifier = Modifier.weight(1f))

                        val fontSizeValue =
                            remember(periodTitle) { mutableStateOf(textPeriodSize.value) }
                        val readyToDraw = remember(periodTitle) { mutableStateOf(false) }
                        JsAutoResizeText(
                            text = periodTitle.uppercase(),
                            modifier = Modifier.padding(horizontal = 8.dp),
                            color = JsMainTheme.colors.text_color_default.copy(alpha = if (isReview) 1f else 0.5f),
                            maxTextSize = if (readyToDraw.value) textPeriodSize.value else fontSizeValue.value,
                            minTextSize = 6,
                            fontWeight = FontWeight.Normal,
                            textAlign = TextAlign.Center,
                            maxLines = 1
                        )
                        Spacer(modifier = Modifier.height(if (isReview) 6.dp else 2.dp))
                        Box(modifier = Modifier.weight(if (isReview) 2f else 1f))
                        JsAutoResizeText(
                            text = price.uppercase(),
                            modifier = Modifier.padding(horizontal = 8.dp),
                            maxTextSize = 24,
                            minTextSize = 10,
                            color = JsMainTheme.colors.text_color_default,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center,
                            maxLines = 1
                        )
                        Spacer(modifier = Modifier.height(if (isReview) 16.dp else 6.dp))

                        JsAutoResizeText(
                            text = pricePerWeek.lowercase(),
                            modifier = Modifier.padding(horizontal = 6.dp),
                            color = JsMainTheme.colors.text_color_default,
                            maxTextSize = 12,
                            minTextSize = 6,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center,
                            maxLines = 1
                        )

                        Spacer(modifier = Modifier.height(4.dp))
                        Box(modifier = Modifier.weight(2f))

                        if ((isPopular || !discountOnlyForPopularProduct) && textPrices.textPercent > 0 && !isReview) {

                            val discountColor =
                                /*if (onSelected) JsMainTheme.colors.box_paywall_subscribe_button_gray.copy(0.9f) else */
                                JsMainTheme.colors.box_discount_subscribe_button
                            Box(
                                modifier = Modifier
                                    .padding(horizontal = 4.dp)
                                    .height(20.dp)
                                    .clipByCorner()
                                    .border(
                                        width = 1.dp,
                                        style = LineStyle.Solid,
                                        color = discountColor
                                    ),
                                contentAlignment = Alignment.Center
                            ) {
                                val textPercentDiscount =
                                    /*if (textPrices.textPercentDiscount.isEmpty()) */
                                    "${stringResource(Res.string.paywall_box_buttons_save)} ${textPrices.textPercent}%"
                                /*else "${stringResource(Res.string.paywall_box_buttons_save} ${textPrices.textPercentDiscount}%"*/
                                JsAutoResizeText(
                                    text = textPercentDiscount.uppercase(),
                                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                    color = discountColor,
                                    maxTextSize = 10,
                                    minTextSize = 4,
                                    fontWeight = FontWeight.ExtraBold,
                                    textAlign = TextAlign.Center,
                                    maxLines = 1
                                )
                            }
                        } else if (!isReview) Spacer(modifier = Modifier.height(10.dp))

                        Box(modifier = Modifier.weight(1f))
                        Spacer(modifier = Modifier.height(16.dp))
                    }
                    if (btnProgress.value && selectedProductID.value == productDetails.productId) {
                        Box(
                            modifier = Modifier.fillMaxSize(),
                            contentAlignment = Alignment.Center
                        ) {
                            LoadingState()
                        }
                    }
                }
            }
        }

        if (isPopular) {
            val itemColor =
                if (isPlus) JsMainTheme.colors.gradient_subscribe_plus_color_end
                else Color.rgb(0x995AE5)

            Box(
                modifier = Modifier
                    .padding(top = 2.dp, start = 6.dp, end = 6.dp)
                    .rotate((-4).deg)
                    .align(Alignment.TopCenter)
                    .clipByCorner(6)
                    .border(width = 2.dp, style = LineStyle.Solid, color = itemColor)
                    .background(JsMainTheme.colors.main_color_background),
                contentAlignment = Alignment.Center
            ) {
                JsAutoResizeText(
                    text = stringResource(Res.string.onboarding_propose_subscription_popular).uppercase(),
                    modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                    maxTextSize = 10,
                    minTextSize = 6,
                    color = itemColor,
                    fontWeight = FontWeight.ExtraBold,
                    textAlign = TextAlign.Center,
                    maxLines = 1
                )
            }
        }
    }
}