@Composable
fun JsDatePicker(
    modifier: Modifier = Modifier,
    startDate: LocalDate,
    monthFormat: MonthFormat = MonthFormat.SHORT,
    itemHeight: Int,
    rowCount: Int,
    selectorProperties: SelectorProperties = JsPickerDefaults.selectorProperties(),
    onDateChanged: (LocalDate) -> Unit
) {
    val scrollState = remember { mutableStateOf(PickerScrollState.NON) }

    val today = DateTimeConverter.getCurrentDate().date

    val selectedDay = remember { mutableIntStateOf(startDate.day) }
    val selectedMonth = remember { mutableIntStateOf(startDate.month.number) }
    val selectedYear = remember { mutableIntStateOf(startDate.year) }

    val shortMonthsList = shortMonthsList()
    val fullMonthsList = fullMonthsList()
    val monthItems = when (monthFormat) {
        MonthFormat.NUMERIC -> (1..12).map { it.toString().padStart(2, '0') }
        MonthFormat.FULL -> fullMonthsList
        MonthFormat.SHORT -> shortMonthsList
    }
    val monthStartIndex = monthItems.size * 50 + (selectedMonth.intValue - 1)

    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceEvenly
        ) {
            JsPickerScrollingDay(
                modifier = Modifier.weight(1f),
                selectedDay = selectedDay,
                selectedMonth = selectedMonth,
                selectedYear = selectedYear,
                scrollState = scrollState,
                rowCount = rowCount,
                itemHeight = itemHeight,
                selectorProperties = selectorProperties,
            ) { dayStr ->
                if (dayStr.isEmpty()) return@JsPickerScrollingDay
                selectedDay.intValue = dayStr.toInt()
                val correctedDate = LocalDate(
                    selectedYear.intValue, selectedMonth.intValue, selectedDay.intValue
                ).coerceAtMost(today)
                onDateChanged(correctedDate)
            }

            JsPickerScrollingMonth(
                modifier = Modifier.weight(1f),
                startIndex = monthStartIndex,
                items = monthItems,
                itemsCount = monthItems.size * 100,
                scrollState = scrollState,
                rowCount = rowCount,
                itemHeight = itemHeight,
                selectorProperties = selectorProperties,
            ) { monthValue ->
                if (monthValue.isEmpty()) return@JsPickerScrollingMonth
                val newMonth = when (monthFormat) {
                    MonthFormat.NUMERIC -> monthValue.toInt()
                    MonthFormat.FULL -> fullMonthsList.indexOf(monthValue) + 1
                    MonthFormat.SHORT -> shortMonthsList.indexOf(monthValue) + 1
                }

                val maxDay = getMaxDaysInMonth(selectedYear.intValue, newMonth)
                val correctDay = selectedDay.intValue.coerceAtMost(maxDay)
                selectedDay.intValue = correctDay
                selectedMonth.intValue = newMonth
                val correctedDate = LocalDate(
                    selectedYear.intValue, selectedMonth.intValue, selectedDay.intValue
                ).coerceAtMost(today)
                onDateChanged(correctedDate)
            }

            JsPickerYears(
                modifier = Modifier.weight(1f),
                startItem = selectedYear.intValue,
                today = today,
                scrollState = scrollState,
                rowCount = rowCount,
                itemHeight = itemHeight,
                selectorProperties = selectorProperties,
            ) { yearStr ->
                if (yearStr.isEmpty()) return@JsPickerYears
                selectedYear.intValue = yearStr.toInt()
                val maxDay = getMaxDaysInMonth(selectedYear.intValue, selectedMonth.intValue)
                val correctDay = selectedDay.intValue.coerceAtMost(maxDay)
                selectedDay.intValue = correctDay
                selectedMonth.intValue = selectedMonth.value
                val correctedDate = LocalDate(
                    selectedYear.intValue, selectedMonth.intValue, selectedDay.intValue
                ).coerceAtMost(today)
                onDateChanged(correctedDate)
            }
        }
    }
}

enum class PickerScrollState {
    DAY, MONTH, YEARS, NON
}

