enum class ScreenEnum(val event: String, val option: String, val screen: String = "") {
    GetPhotosEditProfile("manage_photo", "get_photos", "edit_profile"),
    GetPhotosManager("manage_photo", "get_photos", "photos"),

    UploadPhotoEditProfile("manage_photo", "upload_photo", "edit_profile"),
    UploadPhotoManager("manage_photo", "upload_photo", "photos"),
    UploadPhotoCropPage("manage_photo", "upload_photo", "crop_avatar"),

    UpdateOrderEditProfile("manage_photo", "update_photos_order", "edit_profile"),
    UpdateOrderPhotoManager("manage_photo", "update_photos_order", "photos"),

    DeletePhotoManager("manage_photo", "delete_photo", "photos"),

    UploadAvatarEditProfile("manage_photo", "upload_avatar", "edit_profile"),
    UploadAvatarManager("manage_photo", "upload_avatar", "photos"),
    UploadAvatarCropPage("manage_photo", "upload_avatar", "crop_avatar"),

    DeleteAvatarManager("manage_photo", "delete_avatar", "photos"),

    ModerateEditProfile("manage_photo", "moderate_photo", "edit_profile"),
    ModeratePhotoManager("manage_photo", "moderate_photo", "photos"),
    ModerateCropPage("manage_photo", "moderate_photo", "crop_avatar"),

    DeleteAccountOnboarding("my_account", "delete_account", "onboarding_start"),
    DeleteAccountSettings("my_account", "delete_account", "settings_delete"),

    LocationGetCoordinates("location", "get_system_location"),
    LocationGetPlace("location", "get_place_name"),
    LocationUpdate("location", "update_location");

    fun getEventString(): String {
        return "$event.$option${if (screen.isNotEmpty()) ".$screen" else ""}"
    }
}