package ui.screens.settings.settingsChangePassword

import androidx.annotation.UiThread
import androidx.compose.runtime.mutableStateOf
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dependencies.AccountRepository
import dependencies.di
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.auth_sign_in_wrong_password
import fiori.sharedmodule.generated.resources.auth_sign_in_wrong_password_min_size
import fiori.sharedmodule.generated.resources.dialog_changing_password_error_text
import fiori.sharedmodule.generated.resources.dialog_changing_password_success_text
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.utils.IDialogManager
import org.kodein.di.instance
import ui.resources.ResManager


sealed class SettingsPasswordEvent{
    data object Back: SettingsPasswordEvent()
}

class SettingsPasswordVM(
    private val viewModelCallback: (SettingsPasswordEvent) -> Unit,
) : ViewModel() {

    private val accountRepository by di.instance<AccountRepository>()
    private val dialogManager by di.instance<IDialogManager>()

    val showProgress = mutableStateOf(false)

    val oldPasswordValue = mutableStateOf("")
    val oldPasswordError = mutableStateOf("")

    val newPasswordValue = mutableStateOf("")
    val newPasswordError = mutableStateOf("")

    val repeatNewPasswordValue = mutableStateOf("")
    val repeatNewPasswordError = mutableStateOf("")

    val alpha =
        if (oldPasswordValue.value.isNotEmpty() && newPasswordValue.value.isNotEmpty()
            && repeatNewPasswordValue.value.isNotEmpty() && oldPasswordError.value.isEmpty()
            && repeatNewPasswordError.value.isEmpty() && newPasswordError.value.isEmpty()
        ) 1f else 0.3f

    val enabled =
        oldPasswordValue.value.isNotEmpty() && newPasswordValue.value.isNotEmpty()
                && repeatNewPasswordValue.value.isNotEmpty() && oldPasswordError.value.isEmpty()
                && repeatNewPasswordError.value.isEmpty() && newPasswordError.value.isEmpty()

    fun changePassword() {
        if (newPasswordValue.value.length < 6) {
            showError(
                errorNewPassword = true,
                errorOldPassword = false,
                errorRepeatPassword = false
            )
            return
        }
        if (newPasswordValue.value != repeatNewPasswordValue.value) {
            showError(
                errorOldPassword = false,
                errorNewPassword = false,
                errorRepeatPassword = true
            )
            return
        }

        accountRepository.changeEmailAccountPassword(
            oldPasswordValue.value,
            newPasswordValue.value,
            onSuccess = {
                dialogManager.showMessageDialog(Res.string.dialog_changing_password_success_text)
                back()
            },
            onError = {
                showError(
                    errorOldPassword = true,
                    errorNewPassword = false,
                    errorRepeatPassword = false
                )
            })
    }

    fun hideError(errorPasswordField: ErrorPasswordField) {
        when (errorPasswordField) {
            ErrorPasswordField.OldPassword -> oldPasswordError.value = ""
            ErrorPasswordField.NewPassword -> newPasswordError.value = ""
            ErrorPasswordField.RepeatPassword -> repeatNewPasswordError.value = ""

        }
    }

    fun showError(
        errorOldPassword: Boolean,
        errorNewPassword: Boolean,
        errorRepeatPassword: Boolean,
    ) {
        viewModelScope.launch(Dispatchers.Main) {
            when {
                errorOldPassword -> oldPasswordError.value =
                    ResManager.getString(Res.string.auth_sign_in_wrong_password)

                errorNewPassword -> newPasswordError.value =
                    ResManager.getString(Res.string.auth_sign_in_wrong_password_min_size)

                errorRepeatPassword -> repeatNewPasswordError.value =
                    ResManager.getString(Res.string.dialog_changing_password_error_text)
            }
        }
    }

    @UiThread
    fun back() {
        viewModelCallback.invoke(SettingsPasswordEvent.Back)
    }
}

enum class ErrorPasswordField { OldPassword, NewPassword, RepeatPassword }