package ui.screens.settings.settingsChangeEmail

import androidx.annotation.UiThread
import androidx.compose.runtime.mutableStateOf
import androidx.compose.ui.text.input.TextFieldValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.auth_sign_in_wrong_password_min_size
import fiori.sharedmodule.generated.resources.error_message_email_not_correct
import fiori.sharedmodule.generated.resources.error_message_email_same_value
import fiori.sharedmodule.generated.resources.nav_settings_email_changed_success
import dependencies.di
import dependencies.AccountRepository
import kotpref.utils.EmailValid
import managers.analytics.AnalyticsManager
import managers.analytics.AnalyticsRegistrationEvents
import managers.analytics.AnalyticsSettingsEvents
import ui.resources.ResManager
import managers.AmplitudeEvent
import managers.AmplitudeManager
import kotpref.models.AuthorizationType
import kotpref.models.account.Account
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.eventBus.EventBusManager
import kotpref.eventBus.UpdateUserEmail
import kotpref.models.typeConverter.DateTimeConverter
import kotpref.utils.IDialogManager
import org.kodein.di.instance

sealed class SettingsEmailEvent{
    data class DialogResetPassword(val type : AuthorizationType, val email: String) : SettingsEmailEvent()
    data object Back: SettingsEmailEvent()
}

class SettingsEmailVM(
    val viewModelCallback: (SettingsEmailEvent) -> Unit
) : ViewModel() {

    private val dialogManager by di.instance<IDialogManager>()
    private val accountRepository by di.instance<AccountRepository>()
    private val amplitudeManager by di.instance<AmplitudeManager>()
    private var account: Account? = null

    val showProgress = mutableStateOf(false)
    val showPassword = mutableStateOf(false)

    val emailValue = mutableStateOf(TextFieldValue(""))
    val emailError = mutableStateOf("")

    val passwordValue = mutableStateOf("")
    val passwordError = mutableStateOf("")

    var oldEmail = ""

    val alpha =
        if (oldEmail != emailValue.value.text && emailValue.value.text.isNotEmpty()
            && emailError.value.isEmpty() && passwordError.value.isEmpty()
        ) 1f else 0.3f
    val enabled =
        oldEmail != emailValue.value.text && emailValue.value.text.isNotEmpty()
                && emailError.value.isEmpty() && passwordError.value.isEmpty()

    init {
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            account = accountRepository.getMyAccount()
            account?.email?.let {
                oldEmail = it
                emailValue.value = TextFieldValue(it)
            }
            showPassword.value = account?.emailVerified == true
        }
    }

    var lastClickTime = 0L
    fun changeEmail() {
        val currentTime = DateTimeConverter.currentTimeMillis()
        if (currentTime - lastClickTime <= 500) return
        lastClickTime = currentTime

        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            if (emailValue.value.text.isEmpty() || EmailValid.isEmailValid(emailValue.value.text)) {
                if (oldEmail != emailValue.value.text) {
                    showProgress.value = true
                    val password = if (account?.emailVerified == true) {
                        passwordValue.value
                    } else null

                    if (passwordValue.value.length < 6 && showPassword.value) {
                        showError(
                            emailErrorValue = false,
                            passwordErrorValue = true,
                            message = ResManager.getString(Res.string.auth_sign_in_wrong_password_min_size)
                        )
                        return@launch
                    }

                    val changedSuccess =
                        ResManager.getString(Res.string.nav_settings_email_changed_success)
                    accountRepository.changeAccountEmail(
                        emailValue.value.text,
                        password,
                        onSuccess = {
                            amplitudeManager.sendEvent(AmplitudeEvent.VerificationEmailStartScreenChangeSuccess)
                            AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.changeEmailSuccess.name)
                            accountRepository.getAppKeys().startTimeVerificationMail =
                                DateTimeConverter.currentTimeMillis() - 1000 * 60 * 4L
                            showMessage(changedSuccess)
                            back()
                            EventBusManager.post(UpdateUserEmail())
                        },
                        onError = {
                            AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.changeEmailFailed.name)
                            val showPassword = showPassword.value
                            if (!showPassword) {
                                showError(true, false, it ?: " ")
                            } else {
                                showError(true, true, " ")
                            }
                        })
                } else showError(
                    emailErrorValue = true,
                    passwordErrorValue = false,
                    message = ResManager.getString(Res.string.error_message_email_same_value)
                )
            } else showError(
                emailErrorValue = true,
                passwordErrorValue = false,
                message = ResManager.getString(Res.string.error_message_email_not_correct)
            )
        }
    }

    private fun showMessage(message: String) {
        showProgress.value = false
        dialogManager.showMessageDialog(message)
    }

    fun forgotPass() {
        AnalyticsManager.onSendEvent(AnalyticsRegistrationEvents.signInForgotPasswordEmail.name)
        viewModelCallback.invoke(SettingsEmailEvent.DialogResetPassword(AuthorizationType.EMAIL, oldEmail))
    }

    private fun showError(emailErrorValue: Boolean, passwordErrorValue: Boolean, message: String) {
        showProgress.value = false
        if (emailErrorValue) emailError.value = message
        if (passwordErrorValue) passwordError.value = message
    }

    @UiThread
    fun back() {
        viewModelCallback.invoke(SettingsEmailEvent.Back)
    }

}