private const val COLOR_MODE_KEY = "web:colorMode"

@InitSilk
fun initColorMode(ctx: InitSilkContext) {
    ctx.config.initialColorMode =
        ColorMode.loadFromLocalStorage(COLOR_MODE_KEY) ?: ColorMode.systemPreference
}

@InitSilk
fun initStyles(ctx: InitSilkContext) {
    ctx.stylesheet.apply {
        registerStyleBase("html, body") { Modifier.fillMaxHeight() }
        registerStyleBase("body") { Modifier.scrollBehavior(ScrollBehavior.Smooth) }
    }
}

@App
@Composable
fun AppEntry(content: @Composable () -> Unit) {
    val vercelConfig = remember { mutableStateOf<VercelConfig?>(null) }

    LaunchedEffect(Unit) {
        vercelConfig.value = VercelManager.loadVercelConfig()
    }

    val config = vercelConfig.value
    if (config == null) {
        //LoadingScreen()
        return
    }

    val paramsCtx = getParamsCtx()
    var configAppVariant = config.appVariant ?: ""

    isTestUser = false
    val testUserCode = paramsCtx["test_user"]
    if (!testUserCode.isNullOrEmpty()) {
        val original = atob(testUserCode)
        println("TEST USER  testUserCode = $testUserCode")
        println("TEST USER  original = $original")
        if (original == "kV3VjW8%#s8AJm2U3&9jekJ^VkEnZk") {
            isTestUser = true
            println("TEST USER  TRUE")

            if (paramsCtx["show_logs"] == "true" && configAppVariant.isNotEmpty() &&
                !configAppVariant.contains("debug", true)
            ) configAppVariant += "debug"
        }
    }

    WebAppVariant.isStage = config.isStage?.toBoolean() ?: false
    WebAppVariant.configAppVariant = configAppVariant

    WebAppVariant.init()
    CommonLogger().log(LogLvl.DEBUG, "VercelManager", "configAppVariant = $configAppVariant")
    CommonLogger().log(LogLvl.DEBUG, "VercelManager", "resultVercel /api/config: $config")
    ResManager.stringManager = object : IResStringManager {
        override fun getPlatformString(resId: StringResource): String {
            return ActualAppStrings.get(resId.key)
        }

        override fun getPlatformString(resId: StringResource, formatArgs: Array<String>): String {
            return ActualAppStrings.formatString(
                ActualAppStrings.get(resId.key), args = formatArgs
            )
        }
    }
    WebDependencies()
    initAppLanguage()
    SilkApp {
        JsMainAppTheme {
            content()
        }
    }
}

fun initAppLanguage() {
    val userLanguage = window.navigator.language // example: "en-US", "pt-PT"
    val baseLanguage = userLanguage.substringBefore("-") // "en", "pt" ...

    val appKeys by di.instance<IAppKeysStorage>()
    var locale = appKeys.defaultLocale
    if (locale.isEmpty()) {
        appKeys.defaultLocale = baseLanguage
        locale = baseLanguage
    }
    currentAppLanguageCode.value = locale
}

fun getParamsCtx(): Map<String, String> {
    val urlAddress = window.location.href
    val queryParamsString = urlAddress.substringAfter("?", "")

    if (queryParamsString.isEmpty()) return emptyMap()

    return queryParamsString
        .split("&")
        .mapNotNull { pair ->
            val parts = pair.split("=", limit = 2)
            if (parts.isNotEmpty()) {
                val key = parts[0]
                val value = if (parts.size > 1) parts[1] else ""
                key to value
            } else null
        }
        .toMap()
}
