sealed class PeopleProfileEditItemType {
    data class AgeType(val itemSubsType: Int = 0, val currentSubsType: Int = 0) :
        PeopleProfileEditItemType()

    data class LocationType(val itemSubsType: Int = 0, val currentSubsType: Int = 0) :
        PeopleProfileEditItemType()

    data object InvisibleType : PeopleProfileEditItemType()
    data object VerificationType : PeopleProfileEditItemType()
}

@Composable
fun PeopleProfileEditSettingsView(
    viewModel: PeopleProfileEditVM
) {
    val myAccount = viewModel.account.value

    val accountPlus = myAccount?.subscriptionStatus?.subscription?.type == 1
    val accountUnlimited = myAccount?.subscriptionStatus?.subscription?.type == 2

    Column(modifier = Modifier.settingsBgModifierJs()) {
        val ageIcon =
            if (accountPlus || accountUnlimited) "ic_subscribe_buy_diamond_main" else "ic_subscribe_plus_diamond"
        PeopleProfileEditSettingsItem(
            title = stringResource(Res.string.people_profile_settings_age),
            icon = ageIcon,
            itemType = PeopleProfileEditItemType.AgeType(),
            isChecked = viewModel.profileAgeSwitchChecked.value,
            onClick = {}
        )

        val locationIcon =
            if (accountUnlimited) "ic_subscribe_buy_diamond_main" else "ic_subscribe_unlimited_diamond"
        PeopleProfileEditSettingsItem(
            title = stringResource(Res.string.people_profile_settings_location),
            icon = locationIcon,
            itemType = PeopleProfileEditItemType.LocationType(),
            isChecked = viewModel.profileSettingsLocationSwitchChecked.value,
            onClick = {}
        )

        val invisibleModeTitle =
            stringResource(Res.string.nav_settings_invisible_mode_title).apply {
                if (SettingsVM.isInvisibleModeT4T(account)) "$this (T4T)"
            }

        PeopleProfileEditSettingsItem(
            title = invisibleModeTitle,
            icon = viewModel.invisibleIcon.value,
            iconTintColor = JsMainTheme.colors.text_color_white,
            itemType = PeopleProfileEditItemType.InvisibleType,
            isChecked = viewModel.profileSettingsLocationSwitchChecked.value,
            onClick = {}
        )

        if (myAccount?.getVerificationStatus() != AccountVerificationStatus.VERIFIED) {
            val backgroundColor =
                AccountVerificationStatusManagerJs().getVerificationStatusColor(  //Перенести AccountVerificationStatusManager
                    myAccount?.getVerificationStatus(), true
                )
            PeopleProfileEditSettingsItem(
                title = stringResource(Res.string.verification_settings_title),
                icon = "ic_settings_verification",
                iconTintColor = JsMainTheme.colors.text_color_white,
                showDivider = false,
                itemType = PeopleProfileEditItemType.VerificationType,
                backgroundColor = backgroundColor,
                isChecked = viewModel.profileSettingsLocationSwitchChecked.value,
                onClick = {}
            )
        }

    }
}

@Composable
fun PeopleProfileEditSettingsItem(
    title: String,
    icon: String,
    iconTintColor: Color? = null,
    itemType: PeopleProfileEditItemType,
    isChecked: Boolean = true,
    showDivider: Boolean = true,
    backgroundColor: Color? = null,
    onClick: () -> Unit
) {
    val modifier = if (backgroundColor != null) Modifier.background(backgroundColor) else Modifier
    Column(modifier.fillMaxWidth().padding(start = 12.dp).styleModifier {
        property("overflow-y", "hidden")
    }) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier
                .minHeight(50.dp)
                .padding(end = 16.dp)
                .fillMaxWidth()
                .clickable { onClick.invoke() }
        ) {

            JsImageView(
                drawableId = icon,
                tintColor = iconTintColor,
                contentScale = ContentScale.Fit,
                modifier = Modifier
                    .size(width = 36.dp, height = 48.dp)
                    .padding(top = 12.dp, bottom = 12.dp)
            )

            Spacer(modifier = Modifier.width(16.dp))

            JsAutoResizeText(
                text = title,
                maxTextSize = 18,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
                modifier = Modifier
                    .padding(top = 4.dp, end = 8.dp, bottom = 4.dp)
                    .weight(1)
            )

            when (itemType) {
                is PeopleProfileEditItemType.AgeType, is PeopleProfileEditItemType.LocationType -> {
                    JsDefaultSwitch(
                        checked = isChecked,
                        onCheckedChange = { onClick() },
                    )
                }

                else -> JsSettingsImageArrow()
            }
        }

        if (itemType == PeopleProfileEditItemType.InvisibleType) {
            JsAutoResizeText(
                text = stringResource(Res.string.nav_settings_invisible_mode_text),
                maxTextSize = 14,
                fontWeight = FontWeight.Medium,
                color = JsMainTheme.colors.text_color_gray_invisible_mode,
                modifier = Modifier
                    .padding(start = 12.dp, top = 4.dp, end = 10.dp, bottom = 14.dp)
                    .weight(1)
            )
        }

        if (showDivider) JsDividerLine(modifier = Modifier.fillMaxWidth())
    }
}


