import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.nav_settings_password_current_title
import fiori.sharedmodule.generated.resources.nav_settings_password_new_title
import fiori.sharedmodule.generated.resources.nav_settings_password_page_title
import fiori.sharedmodule.generated.resources.nav_settings_password_repeat_title
