@Composable
fun SettingsChangePasswordScreenJs(
    viewModelColback: (SettingsPasswordEvent) -> Unit,
    viewModel: SettingsPasswordVM = rememberJsViewModel {
        SettingsPasswordVM(viewModelColback)
    }
) {
    val tabBarType = TabBars.EmptyTabBar

    PageColumnContainer {
        JsCustomTabBar(
            onBack = { viewModel.back() },
            withBackground = false,
            tabBarType = tabBarType
        )

        Box(modifier = Modifier.fillMaxWidth().weight(1)) {
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Spacer(modifier = Modifier.fillMaxHeight(5.percent))
                JsTextView(
                    text = stringResource(Res.string.nav_settings_password_page_title),
                    textSize = 24,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier,
                    textAlign = TextAlign.Center
                )

                //TextField old password
                Spacer(modifier = Modifier.height(24.dp))
                OutlinedPasswordFieldItemJs(
                    passwordValue = viewModel.oldPasswordValue.value,
                    label = stringResource(Res.string.nav_settings_password_current_title),
                    errorText = viewModel.oldPasswordError.value,
                    errorCallback = { viewModel.oldPasswordError.value = "" },
                    onValueChange = { viewModel.oldPasswordValue.value = it }
                )

                //TextField new password
                Spacer(modifier = Modifier.height(24.dp))
                OutlinedPasswordFieldItemJs(
                    passwordValue = viewModel.newPasswordValue.value,
                    label = stringResource(Res.string.nav_settings_password_new_title),
                    errorText = viewModel.newPasswordError.value,
                    errorCallback = { viewModel.newPasswordError.value = "" },
                    onValueChange = { viewModel.newPasswordValue.value = it }
                )

                //TextField repeat new password
                Spacer(modifier = Modifier.height(24.dp))
                OutlinedPasswordFieldItemJs(
                    passwordValue = viewModel.repeatNewPasswordValue.value,
                    label = stringResource(Res.string.nav_settings_password_repeat_title),
                    errorText = viewModel.repeatNewPasswordError.value,
                    errorCallback = { viewModel.repeatNewPasswordError.value = "" },
                    onValueChange = { viewModel.repeatNewPasswordValue.value = it }
                )
            }

            if (viewModel.showProgress.value) LoadingState()
        }

        val gradientColors = listOf(
            JsMainTheme.colors.gradient_main_button_start,
            JsMainTheme.colors.gradient_main_button_end
        )
        JsMainButtonCustom(
            text = stringResource(Res.string.onboarding_location_btn),
            colors = gradientColors,
            arrowIsVisible = true,
            alpha = viewModel.alpha,
            onClick = { viewModel.changePassword() }
        )
    }
}