@Composable
fun SettingsLanguageScreenJs(
    onBack: () -> Unit,
    viewModel: JsSettingsLanguagesVM = rememberJsViewModel { JsSettingsLanguagesVM(onBack) }
) {
    PageColumnContainer {
        JsCustomTabBar(
            onBack = { viewModel.backBtn() },
            tabBarType = TabBars.DefaultTabBar(stringResource(Res.string.nav_settings_language))
        )
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(topBottom = 8.dp)
                .gap(6.dp)
        ) {
            Languages.entries.forEach {
                SettingsRadioItemJs(
                    title = stringResource(it.value),
                    isSelected = viewModel.currentLanguage.value == it.locale
                ) {
                    viewModel.changeLanguage(it.locale) {
                        JsThemeEventBus.updateCurrentLocal(it.locale)
                    }
                }
            }
        }
    }
}