package kotpref.models.paywall

import kotpref.models.onboarding.OnBoardingSubscribeShow
import kotpref.models.profile.CompatibilityQuestionAnswer
import kotlinx.serialization.SerialName
import kotpref.models.AppVariant

/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 27.03.2023.
 */
@kotlinx.serialization.Serializable
data class AdaptyPaywallConfig(

    @SerialName("onboarding_type")
    val onboardingType: Int? = null,

    @SerialName("onboarding_with_interests")
    val onboardingWithInterests: Boolean? = null,

    @SerialName("onboarding_with_compatibilities")
    val onboardingWithCompatibilities: Boolean? = null,

    @SerialName("paywall_type")
    val paywallType: Int? = null,

    /*
    1 - default
    2 - new design
    3 - trial design
    4 - new design + stars
     */
    @SerialName("paywall_style")
    private val paywallStyle: Int? = null,

    @SerialName("paywall_with_close")
    val paywallWithClose: Boolean? = null,

    @SerialName("paywall_button_colors")
    val paywallButtonColors: List<String>? = null,

    @SerialName("paywall_button_animated_style")
    val paywallButtonAnimatedStyle: Int? = null,

    @SerialName("paywall_button_text")
    val paywallButtonText: CompatibilityQuestionAnswer? = null,

    @SerialName("paywall_buttons_style")
    val paywallButtonStyle: Int? = null,

    @SerialName("paywall_enjoyed_by_text")
    val paywallEnjoyedByText: CompatibilityQuestionAnswer? = null,

    @SerialName("paywall_title_text_size")
    val paywallTitleTextSize: Int? = null,

    @SerialName("paywall_title_text")
    val paywallTitleText: CompatibilityQuestionAnswer? = null,

    @SerialName("paywall_title_select_texts")
    val paywallTitleSelectTexts: List<CompatibilityQuestionAnswer>? = null,

    @SerialName("onboarding-payment")
    val onboardingPayment: OnBoardingSubscribeShow? = null,

    @SerialName("settings_for_apple_review")
    private val settingsForAppleReview: Boolean? = null,

    @SerialName("paywall_with_new_buttons_style")
    private val paywallWithNewButtonsStyle: Boolean? = null,

    @SerialName("paywall_with_extra_trial")
    private val paywallWithExtraTrial: Boolean? = null,

    @SerialName("paywall_with_continue_text_button")
    private val paywallWithContinueTextButton: Boolean? = null,

    @SerialName("onboarding_flow_type")
    private val onboardingFlowType: String? = null,

    var productIds: List<String>? = null,

    @SerialName("paywall_with_extra_annual")
    private val paywallWithExtraAnnual: String? = null,

    @SerialName("new_horizontal_button_style")
    private val newHorizontalButtonStyle: Boolean? = null,

    @SerialName("show_billed_annually")
    private val showBilledAnnually: Boolean? = null,

    @SerialName("show_cancel_anytime_new_style")
    private val showCancelAnytimeNewStyle: Boolean? = null,

    @SerialName("show_bottom_total_price")
    private val showBottomTotalPrice: Boolean? = null,

    @SerialName("paywall_show_other_with_box_buttons")
    private val paywallShowOtherWithBoxButtons: Boolean? = null,

    @SerialName("paywall_show_other_with_cancel_anytime")
    private val paywallShowOtherWithCancelAnytime: Boolean? = null,

    @SerialName("paywall_show_other_with_bottom_total_price")
    private val paywallShowOtherWithBottomTotalPrice: Boolean? = null,

    @SerialName("paywall_show_other_without_popular")
    private val paywallShowOtherWithoutPopular: Boolean? = null,

    @SerialName("paywall_with_extra_annual_settings_for_apple_review")
    private val paywallWithExtraAnnualSettingsForAppleReview: Boolean? = null,

    @SerialName("paywall_box_discount_subscription")
    private var paywallBoxDiscountSubscription: String? = null,

    @SerialName("paywall_popular_product_id")
    private var paywallPopularProductId: String? = null,

    @SerialName("annual_12_months_text")
    private var annual12MonthsText: Boolean? = null,

    @SerialName("extra_dialog_12_months_text")
    private var extraDialog12MonthsText: Boolean? = null,

    @SerialName("apple_review_for_build_version")
    private var appleReviewForBuildVersion: String? = null,

    @SerialName("custom_subs_for_build_version")
    private var customSubscriptionsForBuildVersion: String? = null,

    ) {

    fun getProductIdList(): List<String>? {
        if (getCustomSubscriptionsForBuildVersion()) {
            val subsBillings = mutableListOf(
                Billings.MaxUnlim12Discount,
                Billings.Unlim6,
                Billings.Unlim1,
                Billings.MinUnlim12Discount
            )
            return subsBillings.map { it.getSubscribe() }
        } else {
            return productIds
        }
    }

    fun getPaywallStyle(): Int? {
        return (if (AppVariant.isTestBuild()) paywallStyle else paywallStyle) ?: 2
    }

    fun getPaywallButtonsStyle(): Int? {
        return if (AppVariant.isTestBuild()) paywallButtonStyle else paywallButtonStyle
    }

    fun getNewHorizontalButtonsStyle(): Boolean? {
        return if (AppVariant.isTestBuild()) newHorizontalButtonStyle else newHorizontalButtonStyle
    }

    fun getPaywallWithExtraTrial(): Boolean? {
        return if (AppVariant.isTestBuild()) paywallWithExtraTrial else paywallWithExtraTrial
    }

    fun getPaywallWithExtraAnnual(): String? {
        if (getCustomSubscriptionsForBuildVersion()) {
            return Billings.MinUnlim12Discount.getSubscribe()
        }
        return if (AppVariant.isTestBuild()) paywallWithExtraAnnual
        else paywallWithExtraAnnual
    }

    fun getPaywallWithBoxButtonsStyle(): Boolean? {
        return if (AppVariant.isTestBuild()) paywallWithNewButtonsStyle else paywallWithNewButtonsStyle
    }

    fun getPaywallBoxDiscountSubscription(): String? {
        return if (AppVariant.isTestBuild()) paywallBoxDiscountSubscription else paywallBoxDiscountSubscription
    }

    fun getPaywallPopularProductId(): String? {
        return if (AppVariant.isTestBuild()) paywallPopularProductId else paywallPopularProductId
    }

    fun isShowBilledAnnually(): Boolean? {
        return if (AppVariant.isTestBuild()) showBilledAnnually else showBilledAnnually
    }

    fun isUseCancelAnytimeNewStyle(): Boolean? {
        return if (AppVariant.isTestBuild()) showCancelAnytimeNewStyle else showCancelAnytimeNewStyle
    }

    fun isShowBottomTotalPrice(): Boolean? {
        return if (AppVariant.isTestBuild()) showBottomTotalPrice else showBottomTotalPrice
    }

    fun getPaywallShowOtherWithBoxButtons(): Boolean? {
        return if (AppVariant.isTestBuild()) true else paywallShowOtherWithBoxButtons
    }

    fun getPaywallShowOtherWithCancelAnytime(): Boolean? {
        return if (AppVariant.isTestBuild()) paywallShowOtherWithCancelAnytime else paywallShowOtherWithCancelAnytime
    }

    fun getPaywallShowOtherWithBottomTotalPrice(): Boolean? {
        return if (AppVariant.isTestBuild()) paywallShowOtherWithBottomTotalPrice else paywallShowOtherWithBottomTotalPrice
    }

    fun getPaywallShowOtherWithoutPopular(): Boolean? {
        return if (AppVariant.isTestBuild()) paywallShowOtherWithoutPopular else paywallShowOtherWithoutPopular
    }

    fun getPaywallWithExtraAnnualSettingsForAppleReview(): Boolean? {
        return if (AppVariant.isTestBuild()) paywallWithExtraAnnualSettingsForAppleReview
        else if (getAppleReviewForBuildVersion()) true else paywallWithExtraAnnualSettingsForAppleReview
    }

    fun getSettingsForAppleReview(): Boolean? {
        return if (getAppleReviewForBuildVersion()) true
        else if (AppVariant.isTestBuild()) settingsForAppleReview
        else settingsForAppleReview
    }

    fun getOnboardingFlowType(): String? {
        return if (AppVariant.isTestBuild()) onboardingFlowType else onboardingFlowType
    }

    fun getPaywallWithContinueTextButton(): Boolean? {
        return if (AppVariant.isTestBuild()) paywallWithContinueTextButton else paywallWithContinueTextButton
    }

    private fun getAppleReviewForBuildVersion(): Boolean {
        val appVersion = AppVariant.appVersion
        return if (AppVariant.isTestBuild()) appVersion == appleReviewForBuildVersion else appVersion == appleReviewForBuildVersion
    }

    private fun getCustomSubscriptionsForBuildVersion(): Boolean {
        val appVersion = AppVariant.appVersion
        return if (AppVariant.isTestBuild()) appVersion == customSubscriptionsForBuildVersion else appVersion == customSubscriptionsForBuildVersion
    }

    fun getAnnual12MonthsText(): Boolean? {
        return if (AppVariant.isTestBuild()) annual12MonthsText else annual12MonthsText
    }

    fun getExtraDialog12MonthsText(): Boolean? {
        return if (AppVariant.isTestBuild()) extraDialog12MonthsText else extraDialog12MonthsText
    }
}