@Composable
fun SettingsNotificationsScreenJs(
    viewModelCallback: (SettingsNotificationsEvent) -> Unit,
    viewModelEvent: ((SettingsNotificationsEventVM) -> Unit) -> Unit,
    viewModel: SettingsNotificationsVM = rememberJsViewModel {
        SettingsNotificationsVM(viewModelCallback, viewModelEvent)
    }
) {

    PageColumnContainer {
        JsCustomTabBar(
            onBack = { viewModel.obtainEvent(SettingsNotificationsEventVM.SaveData) },
            tabBarType = TabBars.DefaultTabBar(stringResource(Res.string.nav_settings_notifications_page_title))
        )
        Column(
            modifier = Modifier.fillMaxWidth()
        ) {
            SettingsNotificationsItemJs(
                text = stringResource(Res.string.nav_settings_notifications_messages_title),
                isChecked = viewModel.messageSwitch
            )
            SettingsNotificationsItemJs(
                text = stringResource(Res.string.nav_settings_notifications_wow_title),
                isChecked = viewModel.wowSwitch
            )
            SettingsNotificationsItemJs(
                text = stringResource(Res.string.nav_settings_notifications_email_title),
                isChecked = viewModel.emailSwitch
            )
        }
    }
}

@Composable
fun SettingsNotificationsItemJs(
    text: String,
    isChecked: MutableState<Boolean>,
) {
    Box(
        modifier = Modifier.fillMaxWidth().height(48.dp)
    ) {
        Column(
            modifier = Modifier
                .padding(start = 24.dp)
                .fillMaxSize(),
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .weight(1)
                    .padding(end = 8.dp),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Box(
                    modifier = Modifier.weight(1)
                ) {
                    JsTextView(
                        text = text,
                        textSize = 16,
                        fontWeight = FontWeight.Medium,
                        modifier = Modifier.align(Alignment.CenterStart)
                    )
                }
                JsDefaultSwitch(
                    checked = isChecked.value,
                    onCheckedChange = { isChecked.value = !isChecked.value },
                )
            }

            JsDividerLine()
        }
    }
}