enum class AccountIam(
    val resId: () -> StringResource, val position: Int, val secondResId: () -> StringResource
) {
    M({ Res.string.identity_m }, 4, { Res.string.identity_many_m }),
    T_W({ Res.string.identity_t_w }, 1, { Res.string.identity_many_t_w }),
    T_M({ Res.string.identity_t_m }, 2, { Res.string.identity_many_t_m }),
    W({ Res.string.identity_w }, 3, { Res.string.identity_many_w }),
    Q({ Res.string.identity_q }, 7, { Res.string.identity_many_q }),
    NB({ Res.string.identity_nb }, 6, { Res.string.identity_many_nb }),
    X({ Res.string.identity_x }, 5, { Res.string.identity_many_x });

    companion object {

        fun sortList() = when {
            AppVariant.isWeb() -> mutableListOf(M, T_M, T_W, W, NB)
            AppVariant.isFiorry() -> mutableListOf(M, T_W, T_M, W, Q, NB, X)
            AppVariant.isHeaven() -> mutableListOf(M, W, T_M, T_W, NB)
            else -> mutableListOf(M, W)
        }

        private val xdresserList = mutableListOf(T_W, T_M, X)
        private val withSubscriptionList = mutableListOf(M, W, NB)

        fun getImageByGender(genders: MutableList<AccountIam>): ImageByGender {
            val genderSize = genders.size

            if (genderSize == 1) {
                if (genders.contains(M) || genders.contains(T_M)) return ImageByGender.MAN
                if (genders.contains(W) || genders.contains(T_W)) return ImageByGender.WOMAN
            }

            if (genderSize == 2) {
                if (genders.contains(M) && genders.contains(T_M)) return ImageByGender.MAN

                if (genders.contains(W) && genders.contains(T_W)) return ImageByGender.WOMAN
            }

            return ImageByGender.MIX
        }

        fun withSubscription(selectGenders: MutableList<Int>?): Boolean {
            if (selectGenders.isNullOrEmpty()) return false
            var withSubscription = false
            withSubscriptionList.forEach {
                if (selectGenders.contains(it.position)) withSubscription = true
            }
            return withSubscription
        }

        fun showSpecialLimits(currentGender: AccountIam) = when {
            AppVariant.isFiorry() -> currentGender == T_W || currentGender == X
            AppVariant.isHeaven() -> currentGender == T_W
            else -> currentGender == W
        }

        fun showFreeTrial(iamList: MutableList<Int>) = when {
            AppVariant.isFiorryOrHeaven() -> iamList.contains(M.position) || iamList.contains(T_W.position)
            else -> true
        }
    }
}

enum class ImageByGender { MAN, WOMAN, MIX }

suspend fun StringResource.getString(): String {
    return ResManager.getString(this@getString)
}