package managers

import kotlinx.browser.window
import kotlinx.coroutines.await
import kotpref.models.VercelConfig
import kotpref.models.typeConverter.JsonObjectConverter
import kotpref.utils.GeneralConstants

object VercelManager {

    private var vercelConfig: VercelConfig? = null

    suspend fun loadVercelConfig(): VercelConfig {
        if (vercelConfig == null) {
            vercelConfig = try {
                val resp = window.fetch("/api/config").await()
                val text = resp.text().await()
                val result = JsonObjectConverter.stringToObject<VercelConfig?>(text)
                result ?: VercelConfig(
                    stripeKey = GeneralConstants.stripeWebKey,
                    mixpanelKey = GeneralConstants.mixpanelKey
                )
            } catch (e: Throwable) {
                VercelConfig(
                    stripeKey = GeneralConstants.stripeWebKey,
                    mixpanelKey = GeneralConstants.mixpanelKey
                )
            }
        }
        return vercelConfig ?: VercelConfig()
    }
}