@Composable
fun SettingsInvisibleModeScreenJs(
    viewModelCallback: (SettingsInvisibleModeEvent) -> Unit,
    initEventCallback: ((EventVM) -> Unit) -> Unit,
    viewModel: SettingsInvisibleModeVM = rememberJsViewModel {
        SettingsInvisibleModeVM(
            viewModelCallback = viewModelCallback,
            initEventCallback = initEventCallback
        )
    }
) {

    val isChecked = viewModel.isInvisible.value
    val subscribeType = viewModel.subscribeType.value
    PageColumnContainer {
        JsCustomTabBar(
            onBack = { viewModel.obtainEvent(BaseEventVM.ClickBackBtn) },
            tabBarType = TabBars.DefaultTabBar(stringResource(Res.string.nav_settings_invisible_mode_title))
        )

        SettingsInvisibleItemJs(
            type = SettingsInvisibleItemType.InvisibleAllItems(isChecked) {
                viewModel.obtainEvent(SettingsInvisibleModeEventVM.InvisibleChangeSwitch)
            }, subscribeType = subscribeType
        )

        SettingsInvisibleItemJs(
            type = SettingsInvisibleItemType.InvisibleGenders(
                if (isChecked) viewModel.convertEnumToList().map {
                    stringResource(it)
                }
                else viewModel.selectGenders.value,
                onClick = {
                    viewModel.obtainEvent(SettingsInvisibleModeEventVM.OnInvisibleGenderClick)
                }),
            subscribeType = subscribeType
        )

        SettingsInvisibleItemJs(
            type = SettingsInvisibleItemType.InvisibleForAge(
                viewModel.initAgeContent,
                viewModel.minAgeSelect,
                viewModel.maxAgeSelect,
                onChangeAge = { fromAge, toAge ->
                    viewModel.obtainEvent(SettingsInvisibleModeEventVM.OnChangeAge(fromAge, toAge))
                }
            ),
            subscribeType = subscribeType
        )
    }
}

@Composable
fun SettingsInvisibleItemJs(type: SettingsInvisibleItemType, subscribeType: Int) {
    val title = when (type) {
        is SettingsInvisibleItemType.InvisibleGenders -> stringResource(
            resource = Res.string.nav_settings_invisible_mode_by_gender_title
        )

        is SettingsInvisibleItemType.InvisibleForAge -> stringResource(
            resource = Res.string.nav_settings_invisible_mode_by_age_title
        )

        else -> stringResource(resource = Res.string.nav_settings_invisible_mode_for_all_title)
    }

    val subtitle = when (type) {
        is SettingsInvisibleItemType.InvisibleGenders -> stringResource(resource = Res.string.nav_settings_invisible_mode_by_gender_text)
        else -> stringResource(resource = Res.string.nav_settings_invisible_mode_for_all_text)
    }

    Column(
        modifier = Modifier
            .fillMaxWidth()
            .padding(start = 16.dp, top = 12.dp)
            .clickable {
                if (type is SettingsInvisibleItemType.InvisibleGenders) {
                    type.onClick.invoke()
                }
            }
    ) {
        val switchWidth = remember(type) { mutableIntStateOf(16) }
        Row(
            modifier = Modifier.fillMaxWidth(),
            verticalAlignment = Alignment.CenterVertically
        ) {
            JsTextView(
                text = title,
                textSize = 18,
                fontWeight = FontWeight.Normal,
                modifier = Modifier.padding(start = 12.dp, end = 16.dp).weight(1)
            )

            when (type) {
                is SettingsInvisibleItemType.InvisibleGenders -> {
                    JsImageView(
                        drawableRes = Res.drawable.ic_arrow_right_settings,
                        modifier = Modifier.margin(leftRight = 16.dp).height(20.dp).onSizeChanged { w, _ ->
                            switchWidth.intValue = w
                        }
                    )
                }

                is SettingsInvisibleItemType.InvisibleAllItems -> {
                    JsDefaultSwitch(
                        checked = type.isChecked,
                        onCheckedChange = { type.onChangeState.invoke() },
                        modifier = Modifier
                            .margin(leftRight = 16.dp)
                            .onSizeChanged { w, _ ->
                                switchWidth.intValue = w
                            })
                }

                else -> {}
            }
        }

        when (type) {
            is SettingsInvisibleItemType.InvisibleForAge -> {
                fun getAgeValue(age: Int) =
                    if (age >= 50) ((10 - (60 - age)) * 5 + 50) else age

                val text = "${getAgeValue(type.ageFrom.value)}-${getAgeValue(type.ageTo.value)}"
                if (type.initAgeContent.value) {
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(end = 24.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        DefaultRangeSlider(
                            modifier = Modifier.padding(end = 8.dp).margin(topBottom = 8.dp).weight(1).height(30.dp),
                            currentMinValue = type.ageFrom.value,
                            currentMaxValue = type.ageTo.value,
                            onProgressChange = { fromAge, toAge ->
                                type.onChangeAge(fromAge, toAge)
                            }
                        )

                        AgeTextJs(text)
                    }
                }

            }

            is SettingsInvisibleItemType.InvisibleGenders -> {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 8.dp, end = (16 + switchWidth.intValue).dp, bottom = 8.dp)
                ) {
                    ItemSubtitleJs(subtitle, switchWidth)

                    if (type.genders.isNotEmpty()) {
                        FlowRowGenders(type.genders)
                    }
                }
            }

            else -> ItemSubtitleJs(subtitle, switchWidth)
        }

        JsDividerLine()
    }
}

@Composable
fun FlowRowGenders(
    genders: List<String>,
    color: Color = JsMainTheme.colors.bg_splash_sign_up_btn
) {
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .background(JsMainTheme.colors.main_color_background)
            .display(DisplayStyle.Flex)
            .flexWrap(FlexWrap.Wrap)
            .gap(4.px)
    ) {
        genders.forEach {
            GenderItemJs(text = it, color)
        }
    }
}

@Composable
private fun ItemSubtitleJs(subtitle: String, switchWidth: MutableState<Int>) {
    JsTextView(
        text = subtitle,
        textSize = 14,
        textColor = JsMainTheme.colors.text_color_gray_invisible_mode,
        fontWeight = FontWeight.Normal,
        modifier = Modifier.padding(top = 8.dp, end = switchWidth.value.dp, bottom = 12.dp)
    )
}

@Composable
fun GenderItemJs(
    text: String, color: Color = JsMainTheme.colors.bg_splash_sign_up_btn
) {
    Box(
        modifier = Modifier
            .padding(top = 2.dp, end = 4.dp, bottom = 2.dp)
            .background(color)
            .clipByCorner(25)
    ) {
        JsTextView(
            text = text,
            textSize = 14,
            fontWeight = FontWeight.Medium,
            modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
        )
    }
}

@Composable
private fun AgeTextJs(text: String){
    val textMaxWidth = remember { mutableIntStateOf(0) }
    if (textMaxWidth.intValue == 0){
        JsTextView(
            text = "100-100",
            textSize = 16,
            fontWeight = FontWeight.Normal,
            modifier = Modifier.onSizeChanged { w, _ ->
                textMaxWidth.intValue = w
            },
            maxLines = 1
        )
    } else {
        JsTextView(
            text = text,
            textSize = 16,
            fontWeight = FontWeight.Normal,
            modifier = Modifier.width(textMaxWidth.intValue.dp),
            maxLines = 1
        )
    }
}