package web.screens.profile.peopleProfileEdit.views

import androidx.compose.runtime.Composable
import androidx.compose.runtime.MutableState
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import com.varabyte.kobweb.compose.foundation.layout.Column
import com.varabyte.kobweb.compose.ui.Alignment
import com.varabyte.kobweb.compose.ui.Modifier
import kotlinx.coroutines.launch
import web.helpers.stringResource
import web.screens.profile.peopleProfileEdit.PeopleProfileEditVM
import web.screens.settings.settingsMain.settingsBgModifierJs

@Composable
fun PeopleProfileEditParametersView(
    viewModel: PeopleProfileEditVM,
    isEdit: Boolean = true
) {
    val scope = rememberCoroutineScope()
    val infoItemsList = viewModel.profileDataConverter.getParametersCategory()


    Column(
        modifier = Modifier.settingsBgModifierJs(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        repeat(infoItemsList.size) {
            val item = infoItemsList[it]
            val title = stringResource(resource = item.stringRes)
            val content: MutableState<Any> = remember { mutableStateOf("") }
            scope.launch {
                content.value = viewModel.profileDataConverter.getContentData(item, false)
            }

            PeopleProfileEditInfoItem(
                title = title,
                showDivider = it + 1 != infoItemsList.size,
                onClick = {}
            ){
                PeopleProfileEditDefaultContent(content = content.value)
            }
        }
    }
}