    fun convertFromZodiac(): String {
        val date = DateTimeConverter.stringToDate(account?.info?.birthday)
            ?: return ProfileZodiac.Aries.name

        val day = date.day
        val monthNumber = date.month.number

        return getZodiacValue(monthNumber, day).name
    }
    ///endregion


    private fun getZodiacValue(month: Int, day: Int): ProfileZodiac {
        return when (month) {
            1 -> if (day < 20) ProfileZodiac.Capricorn
            else ProfileZodiac.Aquarius

            2 -> if (day < 18) ProfileZodiac.Aquarius
            else ProfileZodiac.Pisces

            3 -> if (day < 21) ProfileZodiac.Pisces
            else ProfileZodiac.Aries

            4 -> if (day < 20) ProfileZodiac.Aries
            else ProfileZodiac.Taurus

            5 -> if (day < 21) ProfileZodiac.Taurus
            else ProfileZodiac.Gemini

            6 -> if (day < 21) ProfileZodiac.Gemini
            else ProfileZodiac.Cancer

            7 -> if (day < 23) ProfileZodiac.Cancer
            else ProfileZodiac.Leo

            8 -> if (day < 23) ProfileZodiac.Leo
            else ProfileZodiac.Virgo

            9 -> if (day < 23) ProfileZodiac.Virgo
            else ProfileZodiac.Libra

            10 -> if (day < 23) ProfileZodiac.Libra
            else ProfileZodiac.Scorpio

            11 -> if (day < 22) ProfileZodiac.Scorpio
            else ProfileZodiac.Sagittarius

            12 -> if (day < 22) ProfileZodiac.Sagittarius
            else ProfileZodiac.Capricorn

            else -> ProfileZodiac.Aries
        }
    }

