        fun isInvisibleModeT4T(account: Account?): Boolean {
            if (AppVariant.isFiorry() && account?.info?.iamList?.firstOrNull() == 1) {
                val iamInterestedIn = account.info.interestedIn ?: mutableListOf()
                val notVisibleForGenders = AccountIam.entries
                    .map { item -> item.position }
                    .filter { !iamInterestedIn.contains(it) }

                if (account.notVisibleForGenders == notVisibleForGenders) {
                    return true
                }
            }
            return false
        }
    }

