    fun getInvisibleIcon(): DrawableResource {
        val account = myAccount.value
        val genders = account?.notVisibleForGenders
        val minAge = account?.showMinAge ?: 18
        val maxAge = account?.showMaxAge ?: 100

        return if (
            ((genders?.size ?: 0) > 0 || minAge > 18 || maxAge < 100) && subscribeType.intValue != 0
        ) {
            ResManager.drawable.ic_settings_invisible_on
        } else Res.drawable.ic_settings_invisible
    }

    fun getInvisibleIconJs(): String {
        val account = myAccount.value
        val genders = account?.notVisibleForGenders
        val minAge = account?.showMinAge ?: 18
        val maxAge = account?.showMaxAge ?: 100

        return if (
            ((genders?.size ?: 0) > 0 || minAge > 18 || maxAge < 100) && subscribeType.intValue != 0
        ) "ic_settings_invisible_on" else "ic_settings_invisible"
    }

