    private fun updateAvatar() {
        if (!appKeys.userRegistered) return
        accountRepository.loadMe(onSuccess = { loadAvatar(it) }, ignoreTime = true)
    }

    private fun updateAvatarIfNeed() {
        if (!appKeys.userRegistered) return
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            val account = accountRepository.getMyAccount()
            if (myAccount.value?.avatar != account?.avatar) loadAvatar(account)
            else if (account?.photos.isNullOrEmpty()) deleteAvatar()
        }
    }

    private fun deleteAvatar() {
        if (!appKeys.userRegistered) return
        avatar.value = ""
        myAccount.value?.photos = null
    }

