    private fun updateSubscribe() {
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            val currentSubscribe = myAccount.value?.subscriptionStatus?.subscription?.type ?: 0
            myAccount.value = accountRepository.getMyAccount()
            val newSubscribe = myAccount.value?.subscriptionStatus?.subscription?.type ?: 0
            if (currentSubscribe != newSubscribe) {
                setInvisibleSelect()
                setSubscribe(newSubscribe)
                if (newSubscribe != 0) showRestoreItem.value = false
            }
        }
    }

