    fun showSubscriptionPage() {
        AnalyticsManager.onSendEvent(AnalyticsSettingsEvents.settingsSubscriptionsOpen.name)
        val showPage = when (myAccount.value?.subscriptionStatus?.subscription?.type ?: 0) {
            1, 2 -> SubscribeType.UNLIMITED
            else -> {
                val isOpenUnlimSubscriptionsByDefault =
                    accountRepository.userAdaptyPaywalls.adaptySubscriptionsConfig?.isOpenUnlimSubscriptionsFromSettings()
                if (isOpenUnlimSubscriptionsByDefault == false) SubscribeType.PLUS
                else SubscribeType.UNLIMITED
            }
        }
        viewModelCallback.invoke(
            SettingsRouteEvent.SubscribePage(
                showPage,
                openFromPage = "settings"
            )
        )
    }

