    private fun obtainEvent(event: SettingsEventVM) {
        when (event) {
            SettingsEventVM.DeleteAvatar -> deleteAvatar()
            SettingsEventVM.SetInvisibleSelect -> setInvisibleSelect()
            SettingsEventVM.UpdateAvatar -> updateAvatar()
            SettingsEventVM.UpdateAvatarIfNeed -> updateAvatarIfNeed()
            SettingsEventVM.UpdateCompatibility -> updateCompatibility()
            SettingsEventVM.UpdateLogin -> updateLogin()
            SettingsEventVM.UpdateNickname -> updateNickname()
            is SettingsEventVM.UpdatePeopleScreen -> updatePeopleScreen(event.newScreenType)
            SettingsEventVM.UpdateSubscribe -> updateSubscribe()
            is SettingsEventVM.UpdateVerificationProfileContainer ->
                updateVerificationProfileContainer(event.account)

            SettingsEventVM.LoadAvatarFromLocalAccount -> loadAvatarFromLocalAccount()
            SettingsEventVM.LoadedMyAccount -> onLoadedMyAccount()
        }
    }
