sealed class ProfileAddInfoEvent {
    data object OnBack : ProfileAddInfoEvent()
}

sealed interface ProfileAddScreenState {
    data object Loading : ProfileAddScreenState
    data object DateState : ProfileAddScreenState
    data object NumberState : ProfileAddScreenState
    data class MultiState(val isMulti: Boolean) : ProfileAddScreenState
    data object SingleState : ProfileAddScreenState
    data object TextState : ProfileAddScreenState
}

class ProfileAddInfoVM(
    private val profileData: ProfileData,
    val months: List<String>,
    val viewModelCallback: (ProfileAddInfoEvent) -> Unit,
) : DefaultViewModel(true) {


    val accountRepository by di.instance<AccountRepository>()
    val dialogManager by di.instance<IDialogManager>()

    private val _state: MutableStateFlow<ProfileAddScreenState> =
        MutableStateFlow(ProfileAddScreenState.Loading)
    val state: StateFlow<ProfileAddScreenState> get() = _state
    var isImperial = false
    val account: MutableState<Account?> = mutableStateOf(null)
    var profileMultiSelectList = mutableStateListOf<MultiSelectItem>()

    var birthdayDate = DateTimeConverter.getCurrentDate().date
    val birthdayValue = mutableStateOf("")
    val birthdayError = mutableStateOf("")

    val profileMultiSelectTitle = mutableStateOf("")

    init {
        viewModelScope.launch(Dispatchers.Main) { /* runBlocking */
            account.value = accountRepository.getMyAccount()
            isImperial = account.value?.measurementUnits == 2

            initState()
        }
    }

    fun initState() {
        profileData.infoData.forEach {
            profileMultiSelectList.add(MultiSelectItem(it))
        }
        val selectData = profileData.selectData
        return when (profileData.type) {
            AccountInfoType.Single -> {
                for (i in 0 until profileMultiSelectList.size) {
                    val multiSelectItem = profileMultiSelectList[i]
                    val index = profileMultiSelectList.indexOf(multiSelectItem)
                    if (multiSelectItem.itemTitle == selectData) {
                        profileMultiSelectList[index] = multiSelectItem.copy(onSelected = true)
                    }
                }
                _state.value = ProfileAddScreenState.SingleState
            }

            AccountInfoType.MultiHexagon, AccountInfoType.Multi -> {
                if (!selectData.isNullOrEmpty()) {
                    selectData.split(", ").forEach {
                        for (i in 0 until profileMultiSelectList.size) {
                            if (profileMultiSelectList[i].itemTitle == it) {
                                val multiSelectItem = profileMultiSelectList[i]
                                val index = profileMultiSelectList.indexOf(multiSelectItem)
                                profileMultiSelectList[index] =
                                    multiSelectItem.copy(onSelected = true)
                            }
                        }
                    }
                }
                val isMulti = profileData.profileDataField == ProfileDataField.Music
                        || profileData.profileDataField == ProfileDataField.Interests
                /*binding.buttonsRecycler
                    .setData(profileData)
                    .setSelectData(
                        selectList,
                        useGenderLimit = profileData.profileDataField == ProfileDataField.Iam,
                        isGenders = profileData.profileDataField == ProfileDataField.Interest
                    ).addItems(inflater, parent, binding.buttonsContainer)
                    .setInfoBtnClick({ infoBtnClick() })
                callback = { binding.buttonsRecycler.getSelectData() }*/
                _state.value = ProfileAddScreenState.MultiState(isMulti)
            }

            AccountInfoType.Date -> {

                val birthday = profileData.selectData?.substring(0, 10)
                if (birthday != null) {
                    birthdayDate = LocalDate.parse(birthday)
                    birthdayValue.value =
                        "${birthdayDate.day} ${months[birthdayDate.month.number - 1]} ${birthdayDate.year}"
                }
                _state.value = ProfileAddScreenState.DateState
            }

            AccountInfoType.NumberPicker -> {
                _state.value = ProfileAddScreenState.NumberState
            }

            else -> {
                _state.value = ProfileAddScreenState.TextState
            }
        }
    }

    fun setSelectMultiItem(item: MultiSelectItem,) {

        if (profileMultiSelectList.filter { it.onSelected }.size >= 10 && !item.onSelected) return

        val index = profileMultiSelectList.indexOf(item)
        profileMultiSelectList[index] = item.copy(onSelected = !item.onSelected)
//        alpha.value = if (multiSelectList.any { it.onSelected }) 1f else 0.3f
    }

    fun setSelectGenderItem(item: MultiSelectItem, isSingleSelect: Boolean) {

        val index = profileMultiSelectList.indexOf(item)
        if (isSingleSelect && !item.onSelected) {
            for (i in profileMultiSelectList.indices) {
                profileMultiSelectList[i] = profileMultiSelectList[i].copy(onSelected = i == index)
            }
        } else profileMultiSelectList[index] = profileMultiSelectList[index].copy(onSelected = !item.onSelected)
    }


    fun selectedDate(date: LocalDate, onDown: () -> Unit) {
        birthdayError.value = ""
        birthdayDate = date
        birthdayValue.value = "${date.day} ${months[date.month.number - 1]} ${date.year}"

        onDown.invoke()
    }

    fun saveData() {
        viewModelScope.launch(Dispatchers.Main) {
            val chooseItems = mutableListOf<String>()
            profileMultiSelectList.forEach {
                if (it.onSelected) chooseItems.add(it.itemTitle)
            }
            val ageString = getString(Res.string.pick_date_age_less_18_profile_title)
            if (chooseItems.isNotEmpty() && chooseItems[0] == ageString) {
                dialogManager.showMessageDialog(ageString)
            } else if (profileData.type == AccountInfoType.MultiHexagon
                && profileData.infoData.size == AccountIam.sortList().size
                && chooseItems.isEmpty()
            ) {
                dialogManager.showMessageDialog(getString(Res.string.error_message_edit_profile_iam_list))
            } else {
                EventBusManager.post(PeopleProfileAddInfoKMP(profileData, chooseItems))
            }
        }
    }

    fun onBack() {
        viewModelCallback.invoke(ProfileAddInfoEvent.OnBack)
    }

    override fun onLifecycleEvent(event: Lifecycle.Event) {

    }

    override fun onEventBusMessage(event: BusEvent) {

    }
}