package web.screens.profile.profilePhotosSelect

import androidx.compose.runtime.*
import com.varabyte.kobweb.compose.css.Overflow
import com.varabyte.kobweb.compose.dom.ref
import com.varabyte.kobweb.compose.foundation.layout.Box
import com.varabyte.kobweb.compose.ui.Modifier
import com.varabyte.kobweb.compose.ui.modifiers.*
import org.jetbrains.compose.web.attributes.Draggable
import org.jetbrains.compose.web.css.*
import org.jetbrains.compose.web.dom.Div
import org.w3c.dom.Element
import ui.screens.profile.profilePhotosSelect.ProfileSelectPhotosVM
import web.helpers.dp
import web.helpers.isMobileDevice
import web.helpers.toPercent
import web.screens.profile.profilePhotosSelect.cropImage.ResizeObserverEntry
import kotlin.math.min

@Composable
fun DragAndDropGridJs(
    viewModel: ProfileSelectPhotosVM,
    modifier: Modifier
) {
    val items = remember { List(9) { it } }
    val photosSize = viewModel.photosListFlow.value.size
    var draggedIndex by remember { mutableStateOf<Int?>(null) }
    // Настройки сетки
    val columns = 3
    val rows = 4
    val horizontalSpacing = 12
    val verticalSpacing = 14

    var containerWidth by remember { mutableStateOf(0.0) }
    var containerHeight by remember { mutableStateOf(0.0) }

    // Контейнер-измеритель
    Box(
        modifier
            .fillMaxSize()
            .padding(leftRight = 16.dp)
            .overflow(Overflow.Hidden),
        ref = ref { element ->
            val observer = ResizeObserver { entries, _ ->
                val rect = entries.firstOrNull()?.contentRect
                if (rect != null) {
                    containerWidth = rect.width
                    containerHeight = rect.height
                }
            }
            observer.observe(element)
            object : DisposableEffectResult {
                override fun dispose() {
                    observer.disconnect()
                }
            }
        }
    ) {
        if (containerWidth > 0 && containerHeight > 0) {
            val aspectRatio = 1.0 / 1.2
            val availableWidthForCells = containerWidth - (horizontalSpacing * (columns - 1))
            val maxCellW_byWidth = availableWidthForCells / columns
            val availableHeightForCells = containerHeight - (verticalSpacing * (rows - 1))
            val maxCellH_byHeight = availableHeightForCells / rows
            val maxCellW_byHeight = maxCellH_byHeight * aspectRatio
            val finalCellWidth = min(maxCellW_byWidth, maxCellW_byHeight)
            val finalCellHeight = finalCellWidth / aspectRatio
            val gridWidth = (finalCellWidth * columns) + (horizontalSpacing * (columns - 1))
            val gridHeight = (finalCellHeight * rows) + (verticalSpacing * (rows - 1))

            // --- Рендеринг Сетки ---
            // Используем key, чтобы сетка пересоздавалась при изменении размеров
            key(containerWidth, containerHeight) {
                Div(
                    attrs = {
                        style {
                            display(DisplayStyle.Grid)
                            gridTemplateColumns("repeat($columns, ${finalCellWidth}px)")
                            gridTemplateRows("repeat($rows, ${finalCellHeight}px)")
                            gap(verticalSpacing.px, horizontalSpacing.px)
                            width(gridWidth.px)
                            height(gridHeight.px)
                            // Центрируем по горизонтали
                            property("margin-left", "auto")
                            property("margin-right", "auto")
                            // Прижимаем к верху
                            property("margin-top", "0px")
                        }
                    }
                ) {
                    items.forEach { index ->
                        val photo =
                            if (index <= photosSize - 1) viewModel.photosListFlow.value[index] else null

                        val spanX = if (index == 0) 2 else 1
                        val spanY = if (index == 0) 2 else 1

                        Div(
                            attrs = {
                                style {
                                    property("grid-column", "span $spanX")
                                    property("grid-row", "span $spanY")
                                    width(1f.toPercent())
                                    height(1f.toPercent())
                                    display(DisplayStyle.Flex)
                                    justifyContent(JustifyContent.Center)
                                    alignItems(AlignItems.Center)
                                }
                                val isDraggable = photo != null
                                if (isDraggable) {
                                    draggable(Draggable.True)

                                    // Начали тащить
                                    onDragStart {
                                        draggedIndex = index
                                        it.dataTransfer?.effectAllowed = "move"
                                        viewModel.rollbackPhotoSelected(index)
                                    }

                                    onDragOver {
                                        it.preventDefault() // Обязательно для разрешения drop
                                    }

                                    // Бросили
                                    onDrop {
                                        it.preventDefault()
                                        val from = draggedIndex
                                        if (from != null && from != index) {
                                            viewModel.rollbackPhotoSwipe(from, index)
                                        }
                                        draggedIndex = null
                                    }

                                    onDragEnd {
                                        draggedIndex = null
                                        viewModel.rollbackPhotoSelected(null)
                                    }
                                }
                            }
                        ) {
                            ProfileSelectPhotosItemJs(
                                index = index,
                                photoUrl = photo?.url,
                                selectedPhotoIndex = /*viewModel.selectedPhoto.value*/ viewModel.fromRollbackPhoto.value,
                                showAddPhoto = photosSize == index,
                                uploadPhoto = viewModel.uploadPhoto.value,
                                addPhotoClick = {
                                    if (isMobileDevice) viewModel.addPhotoClick()
                                    else viewModel.addPhotoClick()//viewModel.showMenuPhotosBottomSheet.value = true
                                },
                                longPhotoClick = { viewModel.longPhotoClick(it) },
                                deletePhotoClick = { viewModel.deletePhotoClick(it) },
                                rollBack = { viewModel.rollbackPhoto(it) }
                            )
                        }
                    }
                }
            }
        }
    }
}

interface CustomGridScopeJs {
    fun item(
        spanX: Int = 1,
        spanY: Int = 1,
        modifier: Modifier = Modifier,
        content: @Composable () -> Unit
    )
}

private data class GridItem(
    val spanX: Int,
    val spanY: Int,
    val modifier: Modifier,
    val content: @Composable () -> Unit
)

external class ResizeObserver(callback: (Array<ResizeObserverEntry>, ResizeObserver) -> Unit) {
    fun observe(target: Element)
    fun disconnect()
}

external interface ResizeObserverEntry {
    val contentRect: DOMRectReadOnly
}

external interface DOMRectReadOnly {
    val width: Double;
    val height: Double
}