object FingerprintHelper {

    fun generateDeviceId(): String {
        val navigator = window.navigator
        val screen = window.screen

        val data = buildString {
            append("userAgent=${navigator.userAgent};")
            append("platform=${navigator.platform};")
            append("language=${navigator.language};")
            append("hardwareConcurrency=${navigator.hardwareConcurrency};")
            append("screenResolution=${screen.width}x${screen.height};")
            append("timezone=${getTimezone()};")
            append("webglVendor=${getWebGLVendor()};")
            append("webglRenderer=${getWebGLRenderer()};")
        }

        if (AppVariant.isDebug()) println(
            "FingerprintHelper: " +
                    "userAgent=${navigator.userAgent};" +
                    "platform=${navigator.platform};" +
                    "language=${navigator.language};" +
                    "hardwareConcurrency=${navigator.hardwareConcurrency};" +
                    "screenResolution=${screen.width}x${screen.height};" +
                    "timezone=${getTimezone()};" +
                    "webglVendor=${getWebGLVendor()};" +
                    "webglRenderer=${getWebGLRenderer()};"
        )

        return sha256(data)
    }

    private fun getWebGLVendor(): String {
        return try {
            val canvas = window.document.createElement("canvas") as org.w3c.dom.HTMLCanvasElement
            val gl = canvas.getContext("webgl") as? WebGLRenderingContext
            gl?.getParameter(WebGLRenderingContext.VENDOR)?.toString() ?: "unknown"
        } catch (e: Throwable) {
            "unknown"
        }
    }

    private fun getWebGLRenderer(): String {
        return try {
            val canvas = window.document.createElement("canvas") as org.w3c.dom.HTMLCanvasElement
            val gl = canvas.getContext("webgl") as? WebGLRenderingContext
            gl?.getParameter(WebGLRenderingContext.RENDERER)?.toString() ?: "unknown"
        } catch (e: Throwable) {
            "unknown"
        }
    }

    private fun getTimezone(): String {
        return try {
            TimeZone.currentSystemDefault().id
        } catch (e: Throwable) {
            "unknown"
        }
    }


    /// SHA 256 encoding
    private val k = longArrayOf(
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
