    )

    private fun sha256(input: String): String {
        val bytes = input.encodeToByteArray()
        val blocks = pad(bytes)

        var h0: Long = 0x6a09e667
        var h1: Long = 0xbb67ae85
        var h2: Long = 0x3c6ef372
        var h3: Long = 0xa54ff53a
        var h4: Long = 0x510e527f
        var h5: Long = 0x9b05688c
        var h6: Long = 0x1f83d9ab
        var h7: Long = 0x5be0cd19

        for (block in blocks) {
            val w = IntArray(64)

            for (i in 0 until 16) {
                w[i] = (block[i * 4].toInt() and 0xff shl 24) or
                        (block[i * 4 + 1].toInt() and 0xff shl 16) or
                        (block[i * 4 + 2].toInt() and 0xff shl 8) or
                        (block[i * 4 + 3].toInt() and 0xff)
            }

            for (i in 16 until 64) {
                val s0 =
                    w[i - 15].rotateRight(7) xor w[i - 15].rotateRight(18) xor (w[i - 15] ushr 3)
                val s1 =
                    w[i - 2].rotateRight(17) xor w[i - 2].rotateRight(19) xor (w[i - 2] ushr 10)
                w[i] = (w[i - 16] + s0 + w[i - 7] + s1)
            }

            var a: Long = h0
            var b: Long = h1
            var c: Long = h2
            var d: Long = h3
            var e: Long = h4
            var f: Long = h5
            var g: Long = h6
            var h: Long = h7

            for (i in 0 until 64) {
                val S1 = e.rotateRight(6) xor e.rotateRight(11) xor e.rotateRight(25)
                val ch = (e and f) xor (e.inv() and g)
                val temp1 = h + S1 + ch + k[i] + w[i]
                val S0 = a.rotateRight(2) xor a.rotateRight(13) xor a.rotateRight(22)
                val maj = (a and b) xor (a and c) xor (b and c)
                val temp2 = S0 + maj

                h = g
                g = f
                f = e
                e = d + temp1
                d = c
                c = b
                b = a
                a = temp1 + temp2
            }

            h0 += a
            h1 += b
            h2 += c
            h3 += d
            h4 += e
            h5 += f
            h6 += g
            h7 += h
        }

        if (AppVariant.isDebug()) println(
            "FingerprintHelper: " +
                    "h0 = $h0, h1 = $h1, h2 = $h2, h3 = $h3, h4 = $h4, h5 = $h5, h6 = $h6, h7 = $h7" +
                    "listOf = ${listOf(h0, h1, h2, h3, h4, h5, h6, h7).joinToString("")}"
        )

        return listOf(h0, h1, h2, h3, h4, h5, h6, h7).map { abs(it) }.joinToString("-") {
            abs(it.toInt()).toString(16).padStart(8, '0')
        }
    }

    private fun Int.rotateRight(bits: Int): Int = (this ushr bits) or (this shl (32 - bits))

    private fun pad(input: ByteArray): List<ByteArray> {
        val bitLen = input.size * 8L
        val padding = ((56 - (input.size + 1) % 64) + 64) % 64
        val output = input + byteArrayOf(0x80.toByte()) + ByteArray(padding) + bitLen.toBytes()
        return output.toList().chunked(64).map { it.toByteArray() }
    }

    private fun Long.toBytes(): ByteArray =
        byteArrayOf(
            (this shr 56).toByte(),
            (this shr 48).toByte(),
            (this shr 40).toByte(),
            (this shr 32).toByte(),
            (this shr 24).toByte(),
            (this shr 16).toByte(),
            (this shr 8).toByte(),
            this.toByte()
        )
}
