//@Entity
@kotlinx.serialization.Serializable
data class LastMessageItem(

    //@ColumnInfo(name = "last_message_item_id")
    @SerialName("id") val id: String,

    //@Embedded
    @SerialName("user") val user: LastMessageChatUser,

    //@ColumnInfo(name = "last_message_item_text")
    @SerialName("text") var text: String?,

    //@ColumnInfo(name = "last_message_item_type")
    @SerialName("type") var type: Int,

    //@ColumnInfo(name = "last_message_item_create_at")
    @SerialName("createdAt") var createdAt: String? = null

) {
    fun toChat(): ChatMessageItem = ChatMessageItem(
        id, user.toUser(), text, type, createdAt, ChatMessageStatus.READ,
        ChatMessageStatus.READ.resId(), false, null
    )
}
