sealed class SettingsInvisibleItemType {
    data class InvisibleAllItems(val isChecked: Boolean, val onChangeState: () -> Unit) :
        SettingsInvisibleItemType()

    data class InvisibleGenders(val genders: List<String>, val onClick: () -> Unit) :
        SettingsInvisibleItemType()

    data class InvisibleForAge(
        val initAgeContent: MutableState<Boolean>,
        val ageFrom: MutableState<Int>,
        val ageTo: MutableState<Int>,
        val onChangeAge: (Int, Int) -> Unit
    ) : SettingsInvisibleItemType()
}

class SettingsInvisibleModeVM(
    private val viewModelCallback: (SettingsInvisibleModeEvent) -> Unit,
    private val initEventCallback: ((EventVM) -> Unit) -> Unit,
) : ViewModel() {

    private val accountRepository by di.instance<AccountRepository>()

    private var myAccount: Account? = null
    private var lastMinAge = 18
    private var lastMaxAge = 60

    val isInvisible = mutableStateOf(false)
    val subscribeType = mutableStateOf(0)
    var selectGenders = mutableStateOf(listOf<String>())
    val minAgeSelect = mutableStateOf(lastMinAge)
    val maxAgeSelect = mutableStateOf(lastMaxAge)

    val initAgeContent = mutableStateOf(false)


    init {
        initEventCallback.invoke(::obtainEvent)
        initPage()
    }

    private fun initPage() {
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            myAccount = accountRepository.getMyAccount()
            subscribeType.value = myAccount?.subscriptionStatus?.subscription?.type ?: 0

            initAgeRange()

            val genders =
                AccountIamConverter.positionsToList(myAccount?.notVisibleForGenders)
                    ?: mutableListOf()

            isInvisible.value =
                (myAccount?.isInvisible ?: false) || genders.size == AccountIam.sortList().size
            selectGenders.value = convertEnumToList(genders).map { it.getString() }
        }
    }

    fun convertEnumToList(
        genders: MutableList<AccountIam> = AccountIam.sortList().toMutableList()
    ): List<StringResource> {
        val selectData = mutableListOf<StringResource>()
        /*if (subscribeType.value == 1 || subscribeType.value == 2)*/ genders.forEach {
            val identity = it.secondResId()
            selectData.add(identity)
        }
        return selectData
    }

    private fun invisibleChangeSwitch() {
        viewModelScope.launch(Dispatchers.Main) {
            /*if (subscribeType.value == 1 || subscribeType.value == 2) {*/
                if (isInvisible.value) {
                    if (selectGenders.value.size == convertEnumToList().size) {
                        selectGenders.value = mutableListOf()
                    }
                    AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeHideProfileOn.name)
                } else {
                    AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeHideProfileOff.name)
                }
                isInvisible.value = !isInvisible.value
            /*} else {
                AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeHideProfileSubscription.name)
                //isInvisible.value = !isInvisible.value
                viewModelCallback.invoke(
                    SettingsInvisibleModeEvent.SubscribePage(
                        returnToPeople = false,
                        openFromPage = "invisible_mode_all_genders"
                    )
                )
            }*/
        }
    }

    private fun initAgeRange() {
        /*if (subscribeType.value == 1 || subscribeType.value == 2) {*/
            myAccount?.showMinAge?.let {
                val setMinAge = setAgeValue(it)
                lastMinAge = setMinAge
                minAgeSelect.value = setMinAge
            }
            myAccount?.showMaxAge?.let {
                val setMaxAge = setAgeValue(it)
                lastMaxAge = setMaxAge
                maxAgeSelect.value = setMaxAge
            }
        //}

        initAgeContent.value = true
    }

    private fun onChangeAge(fromAge: Int, toAge: Int) {
        AnalyticsManager.onSendEvent(AnalyticsPeopleEvents.filterChangeAge.name)
        /*if (subscribeType.value == 1 || subscribeType.value == 2) {*/
            AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeChangeAge.name)

            val minAge = getAgeValue(fromAge)
            val maxAge = getAgeValue(toAge)
            if (maxAge - minAge >= 4) {
                lastMinAge = fromAge
                lastMaxAge = toAge
            } else {
                if (toAge != lastMaxAge) {
                    val step = when {
                        minAge <= 46 -> 4
                        minAge in 47..49 -> 50 + 1 - minAge
                        else -> 1
                    }
                    lastMaxAge = fromAge + step
                } else if (fromAge != lastMinAge) {
                    lastMinAge = toAge - (if (maxAge <= 50) 4 else 1)
                }
            }
            minAgeSelect.value = lastMinAge
            maxAgeSelect.value = if (lastMaxAge > 60) 60 else lastMaxAge
        /*} else {
            AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeChangeAgeSubscription.name)
            viewModelCallback.invoke(
                SettingsInvisibleModeEvent.SubscribePage(
                    returnToPeople = false,
                    openFromPage = "invisible_mode_age"
                )
            )
            minAgeSelect.value = 18
            maxAgeSelect.value = 60
        }*/
    }

    private fun getAgeValue(age: Int) =
        if (age >= 50) ((10 - (60 - age)) * 5 + 50) else age//18 + (age - 42) * 4

    private fun setAgeValue(age: Int) =
        if (age >= 50) ((age - 50) / 5 + 50) else age

    private fun onInvisibleGenderClick() {
        AnalyticsManager.onSendEvent(AnalyticsSubscriptionEvents.invisibleModeSelectGendersOpen.name)

        viewModelScope.launch(Dispatchers.Main) {
            val result = selectGenders.value
            var selectData = ""
            for (i in result.indices) {
                if (i != 0) selectData += ", "
                selectData += result[i]
            }
            val profileData = ProfileData(ProfileDataField.Iam, AccountInfoType.MultiHexagon)
            AccountIam.sortList().forEach {
                val identity = it.secondResId().getString()
                profileData.infoData.add(identity)
            }
            profileData.selectData = selectData
            viewModelCallback.invoke(SettingsInvisibleModeEvent.SettingsInvisibleGender(profileData))
        }
    }

    private fun initItem(data: MutableList<String>, fromInvisibleSwitch: Boolean = false) {
        if (!fromInvisibleSwitch) {
            isInvisible.value = data.size == AccountIam.sortList().size
        }
        selectGenders.value = data
    }

    private fun saveData() {
        val account = Account()
        account.id = myAccount?.id ?: ""
        val minValue = getAgeValue(minAgeSelect.value)
        //getAgeValue(binding.navInvisibleAgeSeek.selectedMinValue.toInt())
        account.showMinAge = if (minValue == 100) 95 else minValue
        account.showMaxAge = getAgeValue(maxAgeSelect.value)
        //getAgeValue(binding.navInvisibleAgeSeek.selectedMaxValue.toInt())
        viewModelScope.launch(Dispatchers.Main) {
            val genderList = mutableListOf<AccountIam>()
            if (isInvisible.value) {
                genderList.addAll(AccountIam.sortList().toTypedArray())
            } else {
                AccountIam.sortList().forEach {
                    val identity = it.secondResId().getString()
                    if (selectGenders.value.contains(identity)) genderList.add(it)
                }
            }
            val genders = AccountIamConverter.listToPositions(genderList)
            account.notVisibleForGenders = genders

            //account.isInvisible = isInvisible

            accountRepository.updateAccount(
                account, onSuccess = { EventBusManager.post(InvisibleModeUpdate()) })
        }
    }

    @UiThread
    private fun back() {
        viewModelCallback.invoke(SettingsInvisibleModeEvent.Back)
    }

    @UiThread
    private fun backSystem(): Boolean {
        saveData()
        return false
    }

    fun obtainEvent(event: EventVM) {
        when (event) {
            is SettingsInvisibleModeEventVM.InitItem -> initItem(event.data)
            is SettingsInvisibleModeEventVM.OnChangeAge -> onChangeAge(event.fromAge, event.toAge)
            SettingsInvisibleModeEventVM.InitPage -> initPage()
            SettingsInvisibleModeEventVM.OnInvisibleGenderClick -> onInvisibleGenderClick()
            SettingsInvisibleModeEventVM.InvisibleChangeSwitch -> invisibleChangeSwitch()

            is BaseEventVM.ClickSystemBack -> event.systemBack.invoke(backSystem())
            BaseEventVM.ClickBackBtn -> back()
            else -> {}
        }
    }

}