    fun updateVerificationProfile(myAccount: Account? = null) {
        viewModelScope.launch(Dispatchers.Main) {
            account = myAccount ?: accountRepository.getMyAccount()
        }
    }

    private fun showNextPage() {
        showProgress.value = false
        when (fromPage) {
            PhotosFromPage.Profile -> {
                EventBusManager.post(UploadCropPhoto())
                isDestroy = false
                viewModelCallback.invoke(ProfileSelectPhotosEvent.OnBack)
            }

            PhotosFromPage.Onboarding -> {
                amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAddPhotoScreenNextClicked)
                viewModelCallback.invoke(ProfileSelectPhotosEvent.ShowOnBoardingNextPage)
            }

            PhotosFromPage.VerificationDialog -> {
                if ((photos.size) <= 0) {
                    viewModelScope.launch(Dispatchers.Main) {
                        val title = getString(Res.string.verification_photos_empty_error_title)
                        val text = getString(Res.string.verification_photos_empty_error_text)
                        dialogManager.showMessageWithTitleDialog(title, text)
                    }
                } else {
                    showProgress.value = true
                    accountRepository.loadAmplifyCredentials(
                        onSuccess = {
                            viewModelCallback.invoke(
                                ProfileSelectPhotosEvent.ProfileFaceVerification(it)
                            )
                            showProgress.value = false
                        },
                        onError = { showProgress.value = false }
                    )
                }
            }

            else -> {
                isDestroy = false
                if (!clickSystemBtn) viewModelCallback.invoke(ProfileSelectPhotosEvent.OnBack)
            }
        }
    }

    private fun clickedBtnAddMore() {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingAddPhotoScreenPlusClicked)
//        supportFragmentManager?.let { pickPhotoManager.show(it) }
    }

    fun backButtonClick() {
        clickBackBtn = true
        isDestroy = false
        clickSystemBtn = false
        if (!isBtnShow) clickedBtn() else backPage()
    }

    private fun backPage() {
        onButtonClick {
            isDestroy = false
            viewModelCallback.invoke(ProfileSelectPhotosEvent.OnBack)
        }
    }

    private var clickSystemBtn = true
    private var clickBackBtn = false

    @UiThread
    fun backSystem(): Boolean {
        if (showMenuPhotosBottomSheet.value) {
            showMenuPhotosBottomSheet.value = false
            return false
        }
        isDestroy = false
        val result = clickSystemBtn
        return if (result) {
            if (userRegistered) {
                if (uploadPhotosList.isEmpty()) onButtonClick()
                else {
                    clickSystemBtn = false
                    backPage()
                }
                true
            } else {
                val shortOnboarding = accountRepository.isShortOnboardingFlow()
                if (shortOnboarding) {
                    cancelRegistration()
                }
                //appKeys.onboardingCurrentPage = 0
                true
            }
        } else {
            appKeys.onboardingCurrentPage = 0
            false
        }
    }

    private fun cancelRegistration() {
        amplitudeManager.sendEvent(AmplitudeEvent.OnboardingCancelButtonClicked)
        dialogManager.showMessageDialog(
            EDialogType.DIALOG_DELETE_ACCOUNT_ONBOARDING,
            callback = {
                viewModelScope.launch(Dispatchers.Main) {
                    val errorTitle =
                        ResManager.getString(Res.string.nav_account_delete_error_title)
                    val errorText =
                        ResManager.getString(Res.string.nav_account_delete_error_text)
                    accountRepository.deleteAccount(onSuccess = {
                        accountRepository.getAppKeys().userBirthday = 0L
                        viewModelCallback.invoke(ProfileSelectPhotosEvent.ClearData("delete_acc_from_profile_photos"))
                    }, onError = {
                        dialogManager.showMessageDialog(
                            EDialogType.DIALOG_WITH_TEXT, title = errorTitle, dialogText = errorText
                        )
                    }, reason = 2)
                }
            })
    }
}
