@Composable
fun PeopleProfileEditScreenJs(
    viewModelCallback: (PeopleProfileEditEvent) -> Unit,
    viewModel: PeopleProfileEditVM = rememberJsViewModel { PeopleProfileEditVM(viewModelCallback) }
) {
    val showCameraScreen = remember { mutableStateOf(false) }
    val galleryManager = rememberGalleryManager(
        onSuccess = {
            viewModel.pickPhoto = it
            viewModelCallback(PeopleProfileEditEvent.CropPhoto)
        },
        onError = {}
    )

    Column(
        modifier = Modifier.fillMaxSize().styleModifier {
            property("overflow-y", "hidden")
        }
            .background(JsMainTheme.colors.main_color_background)
    ) {
        JsCustomTabBar(
            onBack = { viewModel.onBack() },
            tabBarType = TabBars.DefaultTabBar(stringResource(resource = Res.string.people_profile_edit_title))
        )
        if (viewModel.isLoading.value){
            LoadingState()
        } else {
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .styleModifier {
                        property("overflow-y", "auto")
                    }
                    .padding(start = 16.dp, end = 16.dp, top = 12.dp, bottom = 14.dp)
            ) {
                PeopleProfileEditPhotoCategoryJs(viewModel)
                PeopleProfileEditSettingsCategoryJs(viewModel)
                PeopleProfileEditAboutMeCategoryJs(viewModel)
                PeopleProfileEditInfoCategoryJs(viewModel)
                PeopleProfileEditParametersCategoryJs(viewModel)
            }
        }
    }

      /*  ProfileEditState.CropPhoto -> {
            JsAnimatedVisibility(
                visible = viewState is ProfileEditState.CropPhoto,
                animationDirection = AnimationDirection.RIGHT_TO_LEFT,
                durationMs = 500
            ) {
                ProfilePhotoCropScreenJs(
                    viewModel.pickPhoto, onBack = {
                        viewModel.onBack()
                        viewModel.pickPhoto = ""
                    },
                    imageTooLarge = {
//                        viewModel.imageTooLarge()
                    }
                ) { blob, byteArray ->
                    CommonLogger().log(LogLvl.DEBUG, "PhotoUrl", "account photo url: $blob")
                    viewModel.onBack()
//                    viewModel.onCropResultBlob(blob, byteArray)
                }
            }
        }*/
}

