package dependencies

import kotpref.logging.CommonLogger
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers
import managers.EventBusManager
import network.restApi.Endpoint
import network.restApi.requests.AccountRequests
import network.restApi.requests.ChatRequests
import network.restApi.requests.FileRequests
import org.kodein.di.DI
import org.kodein.di.bind
import org.kodein.di.instance
import org.kodein.di.provider
import org.kodein.di.singleton


var di = DI {}

class DependenciesContainer(
    platformModules: List<DI.Module> = mutableListOf(),
    getUserAgentString: () -> HashMap<String, String>,
    appModules: List<DI.Module> = mutableListOf()
) {

    init {
        val allModules = mutableListOf<DI.Module>()
        allModules.addAll(platformModules)
        allModules.add(applicationDependencies())
        allModules.add(coroutinesDependencies())
        allModules.add(repositoryDependencies { getUserAgentString() })
        allModules.add(networkRequests())
        allModules.addAll(appModules)

        di = DI { importAll(allModules) }
    }

    companion object {
        const val BG_CONTEXT_TAG = "bgContext"
        const val UI_CONTEST_TAG = "uiContext"

    }

    fun coroutinesDependencies() = DI.Module("Coroutines module") {
        bind<CoroutineDispatcher>(UI_CONTEST_TAG) with provider { Dispatchers.Main }
        bind<CoroutineDispatcher>(BG_CONTEXT_TAG) with provider { Dispatchers.Default }
    }

    fun applicationDependencies() = DI.Module("Identifiers module", true) {
        bind<EventBusManager>() with singleton { EventBusManager }
        bind<Endpoint>() with singleton { Endpoint() }
        bind<CommonLogger>() with provider { CommonLogger() }
    }

    fun networkRequests() = DI.Module("Network requests module", true) {

        bind<AccountRequests>() with singleton {
            AccountRequests(instance(), instance())
        }

        bind<FileRequests>() with singleton {
            FileRequests(instance(), instance(), instance())
        }

        bind<ChatRequests>() with singleton {
            ChatRequests(
                instance(), instance(), instance(), instance(), instance()
            )
        }
    }

    fun repositoryDependencies(getUserAgentString: () -> HashMap<String, String>) =
        DI.Module("Repository module", true) {

            bind<AccountRepository>() with singleton {
                AccountRepository(
                    instance(), instance(), instance(), instance(), instance(), instance(),
                    instance(), instance(), getUserAgentString
                )
            }

            bind<FileRepository>() with singleton {
                FileRepository(instance(), instance(), instance(), instance())
            }

            bind<ChatRepository>() with singleton {
                ChatRepository(instance(), instance(), instance(), instance())
            }

            bind<RepositoriesProvider>() with singleton {
                RepositoriesProvider(
                    instance(), instance(), instance(), instance(),
                    instance(), instance(), instance()
                )
            }
        }

}