@Composable
fun SettingsAccountDeleteScreenJs(
    viewModelCallback: (SettingsAccountDeleteEvent) -> Unit,
    viewModel: SettingsAccountDeleteVM = rememberJsViewModel {
        SettingsAccountDeleteVM(viewModelCallback)
    }
) {

    PageColumnContainer() {
        JsCustomTabBar(
            onBack = { viewModel.back() },
            tabBarType = TabBars.DefaultTabBar(stringResource(Res.string.nav_settings_delete_title))
        )

        Box(
            modifier = Modifier
                .fillMaxWidth()
                .weight(1)
        ) {
            Column(
                modifier = Modifier.fillMaxSize(),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                Box(modifier = Modifier.fillMaxWidth().height(4.percent))

                JsTextView(
                    text = stringResource(resource = Res.string.nav_settings_delete_title),
                    textSize = 24,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp),
                    textAlign = TextAlign.Start
                )
                JsTextView(
                    text = navAccountDeleteTextJs(),
                    textSize = 14,
                    modifier = Modifier.fillMaxWidth()
                        .padding(start = 16.dp, top = 4.dp, end = 8.dp),
                    fontWeight = FontWeight.Medium,
                    textColor = JsMainTheme.colors.text_color_gray,
                    textAlign = TextAlign.Start
                )

                Box(modifier = Modifier.fillMaxWidth().height(6.percent))

                Column(
                    modifier = Modifier
                        .fillMaxWidth()
//                        .weight(1)
                        .padding(24.dp, vertical = 16.dp)
                        .styleModifier {
                            property("display", "grid")
                            property("grid-template-columns", "repeat(2, 1fr)")
                            property("grid-auto-rows", "1fr")
                            property("gap", "12px")
//                            property("height", "100%")
                        }
                ) {
                    viewModel.list.forEach {
                        SettingsAccountDeleteItemJs(it, viewModel::deleteAccount)
                    }
                }
            }
        }
    }
}

@Composable
fun SettingsAccountDeleteItemJs(item: DeleteReason, onClick: (Int) -> Unit) {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .backgroundColor(JsMainTheme.colors.main_color_bg_2)
            .borderRadius(4.dp)
            .boxShadow(
                blurRadius = 4.dp,
                spreadRadius = 0.dp,
                offsetX = 0.dp,
                offsetY = 0.dp
            )
            .clickable { onClick(item.reason) }
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(vertical = 4.dp, horizontal = 12.dp),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Box(modifier = Modifier.minHeight(20.dp).weight(0.25))
            Box(
                modifier = Modifier.fillMaxWidth(40.percent).aspectRatio(1).borderRadius(50.percent)
                    .background(JsMainTheme.colors.app_main_color),
                contentAlignment = Alignment.Center
            ) {
                JsImageView(
                    drawableRes = item.image,
                    modifier = Modifier
                        .fillMaxWidth(50.percent)
                )
            }

            Box(modifier = Modifier.minHeight(24.dp).weight(0.05))
            Box(modifier = Modifier.weight(1),
                contentAlignment = Alignment.Center) {
                JsTextView(
                    text = stringResource(resource = item.text),
                    textSize = 14,
                    fontWeight = FontWeight.Normal,
                    textAlign = TextAlign.Center,
                    maxLines = 2,
                )
            }
            Box(modifier = Modifier.minHeight(24.dp).weight(0.01))
        }
    }
}


@Composable
fun navAccountDeleteTextJs() = when {
    AppVariant.isHeaven() -> stringResource(resource = Res.string.nav_account_delete_text_heaven)
    AppVariant.isElizium() -> stringResource(resource = Res.string.nav_account_delete_text_elizium)
    AppVariant.isParadiz() -> stringResource(resource = Res.string.nav_account_delete_text_paradiz)
    else -> stringResource(resource = Res.string.nav_account_delete_text)
}